#[derive(Clone, Debug, Default)]
pub struct Startup {
    pub repository: Option<String>,
    pub account: Option<String>,
    pub pull_request: Option<u64>,
    pub data_dir: Option<PathBuf>,
    #[cfg(feature = "ui-smoke")]
    #[doc(hidden)]
    pub provider_reads_disabled: bool,
}

pub struct Root {
    review: Box<ReviewWorkspace>,
}

impl Root {
    pub fn review(window: &mut Window, cx: &mut Context<Self>, startup: Startup) -> Self {
        Self {
            review: Box::new(ReviewWorkspace::new(window, cx, startup)),
        }
    }

    pub(crate) fn system_notification_response(&mut self, tag: &str, cx: &mut Context<Self>) {
        self.review.handle_system_notification_response(tag, cx);
    }

    /// Presentation-only integration point for the separately owned local
    /// workspace. The review controller never provisions or drives this view.
    #[allow(dead_code)] // Consumed by the parent-owned local-workspace embedding commit.
    pub fn attach_pr_local_workspace(
        &mut self,
        repository_key: &str,
        pull_request: u64,
        view: AnyView,
    ) -> bool {
        let workspace = &mut self.review;
        let Some(tab) = workspace.tabs.iter_mut().find(|tab| {
            tab.repository.cache_key() == repository_key && tab.pull_request.number == pull_request
        }) else {
            return false;
        };
        tab.local_workspace = Some(view);
        true
    }

    #[allow(dead_code)] // Consumed by the parent-owned local-workspace embedding commit.
    pub fn pr_local_workspace(&self, repository_key: &str, pull_request: u64) -> Option<AnyView> {
        self.review
            .tabs
            .iter()
            .find(|tab| {
                tab.repository.cache_key() == repository_key
                    && tab.pull_request.number == pull_request
            })
            .and_then(|tab| tab.local_workspace.clone())
    }
}

impl Render for Root {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        self.review.render(window, cx)
    }
}

/// Surfaces stay on this app's own neutrals; every colour that carries meaning
/// comes from GitHub's Primer tokens, so a diff, a branch and a state read the
/// same here as on the pull request page they came from.
///
/// The neutral ramp aims at quiet separation, not at contrast for its own sake.
/// `canvas` is the one deliberate exception: it carries the window behind the
/// main section's frame, so it steps about 1.10:1 off `surface` — enough for the
/// frame to have an edge without the two reading as different materials. The
/// other surfaces sit closer, and a hairline lands near 1.40:1 against the
/// surface behind it — enough to find an edge, not enough to draw a box. Text is
/// the exception and is held to real thresholds, so `faint`, the lowest-ranked
/// text this app writes, clears 4.5:1 on `canvas`, `surface` and `elevated`. An
/// earlier ramp left `faint` at 3.15:1, which is unreadable rather than subtle.
///
/// Every neutral is cool, never warm. An earlier ramp tinted the surfaces warm
/// while the text stayed cool, which is invisible when the steps are tiny and
/// turns to a dirty yellow cast the moment they are not: a warm canvas beside a
/// pure-white panel reads as stained paper, and it fights both Primer's cool
/// semantic tokens and the AppKit material behind the sidebar.
#[derive(Clone, Copy)]
struct Palette {
    /// The page a panel's content sits on. Recedes from `surface` so a card
    /// laid on it reads as a card without needing a heavy outline.
    canvas: Rgba,
    /// Panels and cards: the lightest step in light mode, a raised step in dark.
    surface: Rgba,
    sidebar: Rgba,
    elevated: Rgba,
    text: Rgba,
    muted: Rgba,
    faint: Rgba,
    border: Rgba,
    selected: Rgba,
    accent: Rgba,
    /// Primer `bgColor-accent-muted`: branch chips and the hunk header.
    accent_subtle: Rgba,
    green: Rgba,
    red: Rgba,
    amber: Rgba,
    /// Primer `bgColor-*-emphasis`: the fill under text on a state pill.
    /// `done` is GitHub's merged purple.
    success_emphasis: Rgba,
    danger_emphasis: Rgba,
    done_emphasis: Rgba,
    /// Primer `bgColor-neutral-emphasis`: a draft pull request.
    neutral: Rgba,
    /// Primer `diffBlob` line and gutter tints.
    add_line: Rgba,
    add_gutter: Rgba,
    del_line: Rgba,
    del_gutter: Rgba,
    /// Primer `diffBlob-emptyLine-bgColor`: a side with no line at all.
    diff_empty: Rgba,
    dark: bool,
}

fn palette(dark: bool) -> Palette {
    if dark {
        Palette {
            canvas: rgba(0x111417ff),
            surface: rgba(0x1b1f24ff),
            sidebar: rgba(0x484848e0),
            elevated: rgba(0x22272dff),
            text: rgba(0xf0f6fcff),
            muted: rgba(0xb7bfc8ff),
            faint: rgba(0x8b949eff),
            border: rgba(0x373e47ff),
            selected: rgba(0xffffff14),
            accent: rgba(0x4493f8ff),
            accent_subtle: rgba(0x388bfd1a),
            green: rgba(0x3fb950ff),
            red: rgba(0xf85149ff),
            amber: rgba(0xd29922ff),
            success_emphasis: rgba(0x238636ff),
            danger_emphasis: rgba(0xda3633ff),
            done_emphasis: rgba(0x8957e5ff),
            neutral: rgba(0x656c76ff),
            add_line: rgba(0x2ea04326),
            add_gutter: rgba(0x3fb9504d),
            del_line: rgba(0xf851491a),
            del_gutter: rgba(0xf851494d),
            diff_empty: rgba(0x151b23ff),
            dark,
        }
    } else {
        Palette {
            canvas: rgba(0xf2f4f7ff),
            surface: rgba(0xffffffff),
            sidebar: rgba(0xf1f4f7f0),
            elevated: rgba(0xeef1f4ff),
            text: rgba(0x1f2328ff),
            muted: rgba(0x59636eff),
            faint: rgba(0x666f79ff),
            border: rgba(0xccd3dbff),
            selected: rgba(0x0000000f),
            accent: rgba(0x0969daff),
            accent_subtle: rgba(0xddf4ffff),
            green: rgba(0x1a7f37ff),
            red: rgba(0xd1242fff),
            amber: rgba(0x9a6700ff),
            success_emphasis: rgba(0x1f883dff),
            danger_emphasis: rgba(0xcf222eff),
            done_emphasis: rgba(0x8250dfff),
            neutral: rgba(0x59636eff),
            add_line: rgba(0xdafbe1ff),
            add_gutter: rgba(0xaceebbff),
            del_line: rgba(0xffebe9ff),
            del_gutter: rgba(0xffcecbff),
            diff_empty: rgba(0xf6f8faff),
            dark,
        }
    }
}

/// The graph's lane colours, in the order lanes are handed out.
///
/// GitHub's own answer for "colours that tell series in a graph apart" is
/// Primer's data-visualization scale — `--data-<hue>-color-emphasis`, which
/// resolves to index 5 of each display hue. These are those values, light and
/// dark, ordered so that neighbouring lanes never land on adjacent hues.
///
/// They are deliberately not the semantic colours in `Palette`. Primer is
/// explicit that the data scale is for visualizations and the semantic scale
/// is for meaning: a lane drawn in `red` would read as a failure rather than
/// as the fourth branch.
const LANE_COLORS_LIGHT: [u32; 12] = [
    0x006edb, // blue
    0x2c8141, // green
    0x894ceb, // purple
    0xb8500f, // orange
    0xce2c85, // pink
    0x127e81, // teal
    0xdf0c24, // red
    0x946a00, // yellow
    0x5a61e7, // indigo
    0xd43511, // coral
    0x527a29, // lime
    0xa830e8, // plum
];

const LANE_COLORS_DARK: [u32; 12] = [
    0x0576ff, // blue
    0x388f3f, // green
    0x975bf1, // purple
    0xc46212, // orange
    0xd34591, // pink
    0x158a8a, // teal
    0xeb3342, // red
    0xaa7109, // yellow
    0x7070e1, // indigo
    0xe1430e, // coral
    0x5f892f, // lime
    0xb643ef, // plum
];

/// The colour for one lane. `index` comes from the layout, which already keeps
/// it inside the palette, so this wraps rather than trusting that from afar.
fn lane_color(index: usize, dark: bool) -> Rgba {
    let scale = if dark {
        LANE_COLORS_DARK
    } else {
        LANE_COLORS_LIGHT
    };
    rgba((scale[index % scale.len()] << 8) | 0xff)
}

fn is_dark(window: &Window) -> bool {
    matches!(
        window.appearance(),
        WindowAppearance::Dark | WindowAppearance::VibrantDark
    )
}

fn input_style(colors: Palette) -> InputEditorStyle {
    InputEditorStyle {
        foreground: colors.text.into(),
        muted_foreground: colors.muted.into(),
        background: colors.elevated.into(),
        editor_gutter_background: Some(colors.elevated.into()),
        ..Default::default()
    }
}

fn new_input(
    value: impl Into<String>,
    placeholder: &'static str,
    window: &mut Window,
    cx: &mut Context<Root>,
) -> Entity<InputState> {
    let value = value.into();
    let colors = palette(is_dark(window));
    cx.new(|cx| {
        let mut editor = InputState::new(window, cx);
        editor.set_editor_style(input_style(colors));
        editor.set_value(value, window, cx);
        editor.set_placeholder(placeholder, window, cx);
        editor
    })
}

fn new_textarea(
    value: impl Into<String>,
    placeholder: &'static str,
    window: &mut Window,
    cx: &mut Context<Root>,
) -> Entity<TextareaState> {
    let value = value.into();
    let colors = palette(is_dark(window));
    cx.new(|cx| {
        let mut editor = TextareaState::new(window, cx).auto_grow(3, 8);
        editor.set_editor_style(input_style(colors));
        editor.set_value(value, window, cx);
        editor.set_placeholder(placeholder, window, cx);
        editor
    })
}

fn new_textarea_in_app(
    value: impl Into<String>,
    placeholder: &'static str,
    window: &mut Window,
    cx: &mut App,
) -> Entity<TextareaState> {
    let value = value.into();
    let colors = palette(is_dark(window));
    cx.new(|cx| {
        let mut editor = TextareaState::new(window, cx).auto_grow(3, 8);
        editor.set_editor_style(input_style(colors));
        editor.set_value(value, window, cx);
        editor.set_placeholder(placeholder, window, cx);
        editor
    })
}

struct ViewEditorInputs {
    name: Entity<InputState>,
    search: Entity<InputState>,
    author: Entity<InputState>,
    reviewer: Entity<InputState>,
    assignee: Entity<InputState>,
    label: Entity<InputState>,
    review_status: Entity<InputState>,
    check_status: Entity<InputState>,
    target_branch: Entity<InputState>,
    source_branch: Entity<InputState>,
    source_prefix: Entity<InputState>,
}

impl ViewEditorInputs {
    fn new(
        view: &cibergit::workspace::SavedView,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) -> Self {
        let prefix = view
            .groups
            .iter()
            .find_map(|group| match group {
                GroupBy::SourcePrefix(prefix) => Some(prefix.clone()),
                _ => None,
            })
            .unwrap_or_default();
        Self {
            name: new_input(&view.name, "View name", window, cx),
            search: new_input(&view.filter.search, "Title, number, or branch", window, cx),
            author: new_input(&view.filter.author, "Author login", window, cx),
            reviewer: new_input(&view.filter.reviewer, "Requested reviewer", window, cx),
            assignee: new_input(&view.filter.assignee, "Assignee", window, cx),
            label: new_input(&view.filter.label, "Label", window, cx),
            review_status: new_input(&view.filter.review_status, "e.g. approved", window, cx),
            check_status: new_input(&view.filter.check_status, "e.g. passing", window, cx),
            target_branch: new_input(&view.filter.target_branch, "Target branch", window, cx),
            source_branch: new_input(
                &view.filter.source_branch,
                "Exact source branch",
                window,
                cx,
            ),
            source_prefix: new_input(prefix, "e.g. feature/", window, cx),
        }
    }

    fn all(&self) -> [&Entity<InputState>; 11] {
        [
            &self.name,
            &self.search,
            &self.author,
            &self.reviewer,
            &self.assignee,
            &self.label,
            &self.review_status,
            &self.check_status,
            &self.target_branch,
            &self.source_branch,
            &self.source_prefix,
        ]
    }

    fn set_view(
        &self,
        view: &cibergit::workspace::SavedView,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) {
        let prefix = view
            .groups
            .iter()
            .find_map(|group| match group {
                GroupBy::SourcePrefix(prefix) => Some(prefix.as_str()),
                _ => None,
            })
            .unwrap_or_default();
        for (editor, value) in [
            (&self.name, view.name.as_str()),
            (&self.search, view.filter.search.as_str()),
            (&self.author, view.filter.author.as_str()),
            (&self.reviewer, view.filter.reviewer.as_str()),
            (&self.assignee, view.filter.assignee.as_str()),
            (&self.label, view.filter.label.as_str()),
            (&self.review_status, view.filter.review_status.as_str()),
            (&self.check_status, view.filter.check_status.as_str()),
            (&self.target_branch, view.filter.target_branch.as_str()),
            (&self.source_branch, view.filter.source_branch.as_str()),
            (&self.source_prefix, prefix),
        ] {
            editor.update(cx, |editor, cx| editor.set_value(value, window, cx));
        }
    }

    fn value(editor: &Entity<InputState>, cx: &Context<Root>) -> String {
        editor.read(cx).value().trim().to_owned()
    }

    fn filter(&self, base: &Filter, cx: &Context<Root>) -> Filter {
        Filter {
            search: Self::value(&self.search, cx),
            author: Self::value(&self.author, cx),
            reviewer: Self::value(&self.reviewer, cx),
            assignee: Self::value(&self.assignee, cx),
            label: Self::value(&self.label, cx),
            draft: base.draft,
            review_status: Self::value(&self.review_status, cx),
            check_status: Self::value(&self.check_status, cx),
            target_branch: Self::value(&self.target_branch, cx),
            source_branch: Self::value(&self.source_branch, cx),
            personal: base.personal.clone(),
            state: base.state.clone(),
        }
    }
}

