    fn confirm_lifecycle_mutation(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].submitted_summary_editor.close_after_save() {
            self.status = "Wait for the local draft close operation to finish.".into();
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status = "Another mutation is still in progress.".into();
            return;
        }
        let frozen = match self.tabs[index].lifecycle.take_confirmed() {
            Ok(frozen) => frozen,
            Err(error) => {
                self.status = error;
                cx.notify();
                return;
            }
        };
        let operation_id = frozen.operation_id().to_owned();
        let repository = self.tabs[index].repository.clone();
        let number = self.tabs[index].pull_request.number;
        let identity = repository.cache_key();
        let root_path = self.interaction_root.clone();
        self.tabs[index].write_in_flight = true;
        self.status = "Admitting one exact target mutation on the background executor…".into();
        let task = cx.background_spawn(async move {
            let key = ReviewKey::for_repository("github", &repository, number)
                .map_err(|error| error.to_string())?;
            let mut journal = ActionJournal::open(&root_path, key)?;
            let provider = GithubProvider::new(repository.account.clone());
            let (acknowledged, notice) = match frozen {
                FrozenMutation::Lifecycle { request, .. } => {
                    let mut admission = journal
                        .admission(JournalRequest::Lifecycle(Box::new(request.clone())));
                    match provider.execute_pr_lifecycle(&repository, &request, &mut admission) {
                        ProviderMutationOutcome::Acknowledged(ack) => (
                            true,
                            format!(
                                "GitHub durably acknowledged {} at {} on head {}.",
                                ack.operation_id,
                                ack.updated_at,
                                short_sha(&ack.head_sha)
                            ),
                        ),
                        ProviderMutationOutcome::PreflightRejected { reason } => {
                            (false, format!("Lifecycle write was not sent: {reason}"))
                        }
                        ProviderMutationOutcome::Uncertain { reason, .. } => (false, format!(
                            "Lifecycle outcome is uncertain and frozen against replay: {reason}"
                        )),
                    }
                }
                FrozenMutation::Discussion { request, .. } => {
                    let mut admission = journal
                        .admission(JournalRequest::Discussion(Box::new(request.clone())));
                    match provider.execute_pr_discussion(&repository, &request, &mut admission) {
                        ProviderMutationOutcome::Acknowledged(ack) => (
                            true,
                            format!(
                                "GitHub durably acknowledged {} for exact comment {}{}.",
                                ack.operation_id,
                                ack.comment.remote_id,
                                if ack.deleted { " (deleted)" } else { "" }
                            ),
                        ),
                        ProviderMutationOutcome::PreflightRejected { reason } => {
                            (false, format!("Discussion write was not sent: {reason}"))
                        }
                        ProviderMutationOutcome::Uncertain { reason, .. } => (false, format!(
                            "Discussion outcome is uncertain and frozen against replay: {reason}"
                        )),
                    }
                }
            };
            Ok::<_, String>((acknowledged, notice))
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity
                        && tab.pull_request.number == number
                        && tab.lifecycle.active_operation.as_deref() == Some(&operation_id)
                }) else {
                    // A closed tab cannot receive another tab's late reply. The
                    // durable journal remains authoritative for the completion.
                    return;
                };
                this.tabs[index].write_in_flight = false;
                let (acknowledged, notice) = match result {
                    Ok(value) => value,
                    Err(error) => (
                        false,
                        format!("Mutation admission failed; zero writes sent: {error}"),
                    ),
                };
                this.tabs[index].lifecycle.finish_operation(
                    &operation_id,
                    acknowledged,
                    notice.clone(),
                );
                this.status = notice;
                this.refresh_lifecycle(index, cx);
                this.refresh_details(index, cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn refresh_details(&mut self, index: usize, cx: &mut Context<Root>) {
        self.refresh_details_with_intent(index, true, cx);
    }

    fn load_cached_collaboration(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        tab.collaboration_cache_generation = tab.collaboration_cache_generation.saturating_add(1);
        let repository = tab.repository.clone();
        let token = CollaborationReadToken {
            workspace_instance: self.workspace_instance,
            tab_instance: tab.instance_generation,
            generation: tab.collaboration_cache_generation,
            repository_key: repository.cache_key(),
            pull_request: tab.pull_request.number,
        };
        let cache = self.collaboration_cache.clone();
        let number = tab.pull_request.number;
        let task = cx.background_spawn(async move { cache.load(&repository, number) });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let Some(tab_index) = this.tabs.iter().position(|tab| token.matches(this, tab))
                else {
                    return;
                };
                let tab = &mut this.tabs[tab_index];
                #[cfg(feature = "ui-smoke")]
                {
                    tab.collaboration_cache_completed_generation = token.generation;
                }
                match result {
                    Ok(Some(observation)) if tab.details.is_none() => {
                        let observed_at = observation.observed_at_unix_ms;
                        let age = collaboration_age_label(observed_at);
                        let prior_failure = match &tab.details_state {
                            LoadState::Error(error) => Some(error.clone()),
                            _ => None,
                        };
                        tab.cached_collaboration = Some(observation);
                        if let Some(cached) = &tab.cached_collaboration {
                            tab.checks_selection.reconcile(&cached.details.checks);
                        }
                        tab.details_state = LoadState::Cached(match prior_failure {
                            Some(error) => format!(
                                "Cached collaboration observed {age} · current read failed: {error}"
                            ),
                            None if this.general_reads.refresh_active(tab.details_refresh) => {
                                format!(
                                    "Cached collaboration observed {age} · refreshing current data"
                                )
                            }
                            None => format!("Cached collaboration observed {age}"),
                        });
                        tab.collaboration_cache_notice = None;
                    }
                    Ok(_) => {}
                    Err(error) => {
                        tab.collaboration_cache_notice = Some(format!(
                            "Offline collaboration cache was refused and preserved: {error:#}"
                        ));
                    }
                }
                if tab.inspector_section == InspectorSection::Checks {
                    this.scroll_selected_check_into_view(tab_index);
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn queue_collaboration_save(
        &mut self,
        index: usize,
        details: PullRequestDetails,
        prepared: Result<(PreparedWrite, u64), String>,
        cx: &mut Context<Root>,
    ) {
        let Some(tab) = self.tabs.get(index) else {
            return;
        };
        let key = tab.repository.cache_key();
        let number = tab.pull_request.number;
        let instance = tab.instance_generation;
        let workspace_instance = self.workspace_instance;
        let latest = self
            .collaboration_write_latest
            .entry(format!("{key}\u{1f}{number}"))
            .or_insert_with(|| Arc::new(AtomicU64::new(0)))
            .clone();
        let sequence = latest.fetch_add(1, Ordering::AcqRel).saturating_add(1);
        let cache = self.collaboration_cache.clone();
        let completion_latest = latest.clone();
        let task = cx.background_spawn(async move {
            if latest.load(Ordering::Acquire) != sequence {
                return Ok::<bool, String>(false);
            }
            let (prepared, observed_at) = prepared?;
            if latest.load(Ordering::Acquire) != sequence {
                return Ok(false);
            }
            cache
                .save(prepared, details, observed_at)
                .map_err(|error| format!("{error:#}"))?;
            Ok(true)
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                if this.workspace_instance != workspace_instance {
                    return;
                }
                let Some(tab) = this.tabs.iter_mut().find(|tab| {
                    tab.repository.cache_key() == key
                        && tab.pull_request.number == number
                        && tab.instance_generation == instance
                }) else {
                    return;
                };
                if !collaboration_completion_matches(
                    workspace_instance,
                    this.workspace_instance,
                    instance,
                    tab.instance_generation,
                ) {
                    return;
                }
                if completion_latest.load(Ordering::Acquire) != sequence {
                    return;
                }
                match result {
                    Ok(true) => tab.collaboration_cache_notice = None,
                    Ok(false) => {}
                    Err(error) => {
                        tab.collaboration_cache_notice = Some(format!(
                            "Fresh collaboration data remains usable, but its disposable offline cache was not updated: {error}"
                        ));
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn refresh_details_with_intent(
        &mut self,
        index: usize,
        explicit: bool,
        cx: &mut Context<Root>,
    ) {
        let Some((repository, number, admission)) =
            self.begin_tab_refresh(index, TabReadKind::Details, explicit, cx)
        else {
            return;
        };
        let tab = &mut self.tabs[index];
        let key = repository.cache_key();
        let journal_root = self.interaction_root.clone();
        let collaboration_cache = self.collaboration_cache.clone();
        #[cfg(feature = "ui-smoke")]
        let collaboration_read_disabled = self.collaboration_read_disabled;
        #[cfg(feature = "ui-smoke")]
        let collaboration_read_attempts = self.collaboration_read_attempts.clone();
        if tab.details.is_none() {
            tab.details_state = LoadState::Loading("Loading PR details…".into());
        }
        let (read_token, _cache) = admission.into_parts();
        let task = cx.background_spawn(async move {
            #[cfg(feature = "ui-smoke")]
            collaboration_read_attempts.fetch_add(1, Ordering::AcqRel);
            let prepared = collaboration_cache
                .prepare_write(&repository, number)
                .map_err(|error| format!("prepare disposable collaboration cache: {error:#}"));
            let provider = GithubProvider::new(repository.account.clone());
            let outcome = provider.general_read(|provider| {
                #[cfg(feature = "ui-smoke")]
                if collaboration_read_disabled {
                    return Err(anyhow::anyhow!(
                        "scoped collaboration transport fixture refused the provider read"
                    ));
                }
                let details = provider.details(&repository, number)?;
                let observed_at = now_unix_ms()
                    .map_err(|error| format!("capture collaboration observation time: {error:#}"));
                let cache_write = match (prepared, observed_at) {
                    (Ok(prepared), Ok(observed_at)) => Ok((prepared, observed_at)),
                    (Err(error), _) | (_, Err(error)) => Err(error),
                };
                let pending = provider.pending_review_observation(&repository, number);
                let journal = ReviewKey::for_repository("github", &repository, number)
                    .map_err(|error| error.to_string())
                    .and_then(|key| ActionJournal::open(&journal_root, key))
                    .and_then(|journal| journal.operations());
                Ok((details, pending, journal, cache_write))
            });
            (read_token, outcome)
        });
        cx.spawn(async move |root, cx| {
            let (read_token, outcome) = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let (result, cache, directive, failure) = outcome.into_parts();
                let tab_index = this.tabs.iter().position(|tab| {
                    tab.read_lane(TabReadKind::Details) == read_token.lane()
                });
                let current = tab_index.map(|index| {
                    this.tabs[index].read_context(this.workspace_instance, TabReadKind::Details)
                });
                let result = match this.general_reads.complete_refresh(
                    read_token, current.as_ref(), result, cache, &directive,
                ) {
                    read_sync::RefreshCompletion::Applied(result) => result,
                    read_sync::RefreshCompletion::Discarded => {
                        this.resume_general_read_followups(cx);
                        return;
                    }
                    read_sync::RefreshCompletion::Ignored => return,
                };
                let Some(tab_index) = tab_index else { return };
                match result {
                    Ok((details, pending, journal, cache_write)) =>
                    {
                        let observation = match pending {
                            Ok(observation) => observation,
                            Err(_) => {
                                this.queue_collaboration_save(
                                    tab_index,
                                    details.clone(),
                                    cache_write,
                                    cx,
                                );
                                let tab = &mut this.tabs[tab_index];
                                tab.details = Some(details);
                                tab.cached_collaboration = None;
                                if let Some(details) = &tab.details {
                                    tab.checks_selection.reconcile(&details.checks);
                                }
                                let notice = "PR details updated; pending review data is incomplete and previous linkage was retained."
                                    .to_owned();
                                tab.details_state = LoadState::Cached(notice.clone());
                                match journal {
                                    Ok(operations) => {
                                        tab.journal_operations = operations;
                                        tab.journal_error = None;
                                    }
                                    Err(error) => tab.journal_error = Some(error),
                                }
                                if let InteractionState::Ready(controller) = &mut tab.interactions {
                                    controller.mark_pending_observation_unavailable(Some(notice));
                                }
                                this.reconcile_ci_details(tab_index);
                                this.rebuild_diff(tab_index, this.wide);
                                if this.tabs[tab_index].inspector_section
                                    == InspectorSection::Checks
                                {
                                    this.scroll_selected_check_into_view(tab_index);
                                }
                                this.resume_general_read_followups(cx);
                                cx.notify();
                                return;
                            }
                        };
                        let pending = observation.snapshot;
                        let pending_absence = observation.absence;
                        this.queue_collaboration_save(
                            tab_index,
                            details.clone(),
                            cache_write,
                            cx,
                        );
                        let save = {
                            let tab = &mut this.tabs[tab_index];
                            tab.details = Some(details);
                            tab.cached_collaboration = None;
                            if let Some(details) = &tab.details {
                                tab.checks_selection.reconcile(&details.checks);
                            }
                            tab.pending_snapshot = pending.clone();
                            match journal {
                                Ok(operations) => {
                                    tab.journal_operations = operations;
                                    tab.journal_error = None;
                                }
                                Err(error) => tab.journal_error = Some(error),
                            }
                            tab.details_state = LoadState::Ready;
                            if !tab.write_in_flight
                                && let InteractionState::Ready(controller) =
                                    &mut tab.interactions
                            {
                                if let Some(details) = &tab.details
                                    && let Err(error) = controller.reconcile_details(details)
                                {
                                    controller.notice = Some(format!(
                                        "Pending-review refresh could not be reconciled: {error}"
                                    ));
                                }
                                controller.install_pending_observation(
                                    pending,
                                    pending_absence,
                                );
                                let snapshot = controller.composition().clone();
                                Some((snapshot.clone(), controller.prepared_draft_save(snapshot)))
                            } else {
                                None
                            }
                        };
                        if let Some((snapshot, save)) = save {
                            let ticket = this.issue_participation_write(&key, number);
                            let save_epoch = TabReadEpoch {
                                instance: this.tabs[tab_index].instance_generation,
                                generation: ticket.sequence(),
                            };
                            let completion_ticket = ticket.clone();
                            let task = cx.background_spawn(async move {
                                save.execute_sequenced(&ticket)
                            });
                            let saved_key = key.clone();
                            cx.spawn(async move |root, cx| {
                                let result = task.await;
                                let _ = root.update(cx, |root, cx| {
                                    let this = &mut root.review;
                                    let Some(index) = this.tabs.iter().position(|tab| {
                                        tab.repository.cache_key() == saved_key
                                            && tab.pull_request.number == number
                                            && save_epoch.matches(
                                                tab.instance_generation,
                                                completion_ticket.sequence(),
                                            )
                                            && completion_ticket.is_current()
                                    }) else {
                                        return;
                                    };
                                    match result {
                                        Ok(true) => {
                                            if let InteractionState::Ready(controller) =
                                                &mut this.tabs[index].interactions
                                            {
                                                controller.install_saved_snapshot(snapshot.clone());
                                            }
                                        }
                                        Ok(false) => {}
                                        Err(error) => {
                                            if let InteractionState::Ready(controller) =
                                                &mut this.tabs[index].interactions
                                            {
                                                controller.notice = Some(format!(
                                                    "Authoritative review refresh was not saved; no durable retirement or linkage is claimed: {error}"
                                                ));
                                            }
                                            this.status = format!(
                                                "Review recovery persistence failed; reload before retry: {error}"
                                            );
                                        }
                                    }
                                    cx.notify();
                                });
                            })
                            .detach();
                        }
                        this.reconcile_ci_details(tab_index);
                        this.rebuild_diff(tab_index, this.wide);
                        if this.tabs[tab_index].inspector_section == InspectorSection::Checks {
                            this.scroll_selected_check_into_view(tab_index);
                        }
                    }
                    Err(_) => {
                        let tab = &mut this.tabs[tab_index];
                        let notice = general_read_failure_notice(failure);
                        tab.details_state = if tab.details.is_some()
                            || tab.cached_collaboration.is_some()
                        {
                            LoadState::Cached(notice.into())
                        } else {
                            LoadState::Error(notice.into())
                        };
                        if let InteractionState::Ready(controller) = &mut tab.interactions {
                            controller.mark_pending_observation_unavailable(Some(notice.into()));
                        }
                    }
                }
                this.resume_general_read_followups(cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn rebuild_diff(&mut self, index: usize, wide: bool) {
        let requested = self.workspace.preferences.reading_mode;
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        let Some(session) = &tab.session else { return };
        let Some(file) = session.selected_file() else {
            tab.diff.clear();
            tab.stream_notice = None;
            return;
        };
        let selected_key = file_key(file);
        let resolved_mode = session.diff_mode().resolve(wide);
        let threads = tab
            .details
            .as_ref()
            .and_then(|details| {
                tab.canonical_session
                    .as_ref()
                    .map(|canonical| place_threads_with_canonical(session, canonical, details))
            })
            .unwrap_or_default();
        let composer = match &tab.interactions {
            InteractionState::Ready(controller) => controller.composer.as_ref(),
            InteractionState::Loading | InteractionState::RecoveryRequired(_) => None,
        };
        if requested == ReadingMode::Stream {
            match stream_budget(&session.comparison().files) {
                Ok(()) => {
                    let folded = tab.diff.collapsed.clone();
                    let (rows, spans, split) =
                        build_stream(session, resolved_mode, &threads, composer, &folded);
                    tab.diff.install_stream(rows, spans, split);
                    // Stream opens where File mode would have: on the file the
                    // reader last had selected.
                    tab.diff.reveal_file(&selected_key);
                    tab.stream_notice = None;
                    return;
                }
                // Too much patch text to parse in one go. Fall through to one
                // file at a time and say why, rather than rendering one file
                // and letting the reader conclude the rest were unchanged.
                Err(notice) => tab.stream_notice = Some(notice),
            }
        } else {
            tab.stream_notice = None;
        }
        let base_rows = build_rows(parse_file(file), resolved_mode);
        let rows = attach_inline_rows(base_rows, &selected_key, &threads, composer);
        let Some(session) = &tab.session else { return };
        tab.diff.install(rows, session);
    }

    fn capture_scroll(&mut self, index: usize) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        if let Some(session) = &mut tab.session {
            tab.diff.capture_into(session);
        }
    }

    fn select_file(&mut self, key: &str, wide: bool, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].write_in_flight {
            self.status =
                "File navigation is paused while this review write is being reconciled.".into();
            cx.notify();
            return;
        }
        if self.persist_active_composer_before_transition(
            index,
            "Saving the exact comment target before navigation; choose the file again after it is durable.",
            cx,
        ) {
            return;
        }
        self.capture_scroll(index);
        if self.tabs[index]
            .session
            .as_mut()
            .is_some_and(|session| session.select_file(key))
        {
            if let Some(row) = self.tabs[index].file_tree.reveal_file(key) {
                self.tabs[index]
                    .file_tree_scroll
                    .scroll_to_item(row, ScrollStrategy::Nearest);
            }
            // Streaming already holds every file, so choosing one is a scroll
            // rather than a rebuild. Rebuilding would throw away the rows the
            // reader is looking at to produce the identical vector.
            let revealed = self.tabs[index].diff.streaming()
                && self.tabs[index].diff.reveal_file(key)
                && !self.tabs[index].local_inventory;
            if !revealed {
                self.rebuild_diff(index, wide);
            }
            self.save_workspace(cx);
            if self.tabs[index].local_inventory {
                self.load_selected_local_file(index, cx);
                return;
            }
            self.persist_session(index, cx);
        }
    }

    fn navigate_file(&mut self, next: bool, window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].stack.visible {
            if self.tabs[index].stack.navigate_file(next, self.wide) {
                self.load_selected_stack_local_file(index, cx);
                cx.notify();
            }
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status =
                "File navigation is paused while this review write is being reconciled.".into();
            cx.notify();
            return;
        }
        if self.persist_active_composer_before_transition(
            index,
            "Saving the exact comment target before navigation; navigate again after it is durable.",
            cx,
        ) {
            return;
        }
        self.inspector_open = false;
        self.refresh_auto_layout(window);
        self.capture_scroll(index);
        let changed = self.tabs[index].session.as_mut().is_some_and(|session| {
            if next {
                session.next_file()
            } else {
                session.previous_file()
            }
        });
        if changed {
            let selected = self.tabs[index]
                .session
                .as_ref()
                .and_then(ReviewSession::selected_file)
                .map(file_key);
            if let Some(key) = selected.as_deref()
                && let Some(row) = self.tabs[index].file_tree.reveal_file(key)
            {
                self.tabs[index]
                    .file_tree_scroll
                    .scroll_to_item(row, ScrollStrategy::Nearest);
            }
            // Streaming already holds the file being moved to, so this is a
            // scroll. Rebuilding would discard the rows on screen to produce
            // the identical vector — and throw away every other file's
            // horizontal offset on the way.
            let revealed = self.tabs[index].diff.streaming()
                && !self.tabs[index].local_inventory
                && selected
                    .as_deref()
                    .is_some_and(|key| self.tabs[index].diff.reveal_file(key));
            if !revealed {
                self.rebuild_diff(index, self.wide);
            }
            self.save_workspace(cx);
            if self.tabs[index].local_inventory {
                self.load_selected_local_file(index, cx);
            } else {
                self.persist_session(index, cx);
            }
            cx.notify();
        }
    }

    fn next_file(&mut self, _: &NextFile, window: &mut Window, cx: &mut Context<Root>) {
        self.navigate_file(true, window, cx);
    }

    fn previous_file(&mut self, _: &PreviousFile, window: &mut Window, cx: &mut Context<Root>) {
        self.navigate_file(false, window, cx);
    }

    fn refresh_stack(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        self.refresh_stack_at(index, cx);
    }

    fn refresh_stack_at(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        let repository = tab.repository.clone();
        let token = tab.stack.begin_refresh(&repository);
        self.dispatch_stack_load(index, token, cx);
    }

    /// Explicitly compare one chosen tip. The new token supersedes every older
    /// refresh and lazy patch reply, so a previous tip cannot install its diff.
    fn select_stack_tip(
        &mut self,
        index: usize,
        tip: cibergit::stacks::StackPullRequestId,
        cx: &mut Context<Root>,
    ) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        if !tab.stack.visible {
            return;
        }
        let repository = tab.repository.clone();
        let token = tab.stack.begin_tip_selection(&repository, tip);
        self.status = "Comparing the selected stack tip path…".into();
        self.dispatch_stack_load(index, token, cx);
    }

    fn select_next_stack_tip(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if !self.tabs[index].stack.visible {
            return;
        }
        let Some(tip) = self.tabs[index].stack.next_tip_choice() else {
            return;
        };
        self.select_stack_tip(index, tip, cx);
    }

    fn dispatch_stack_load(
        &mut self,
        index: usize,
        token: stack_view::StackRequestToken,
        cx: &mut Context<Root>,
    ) {
        let tab = &self.tabs[index];
        let repository = tab.repository.clone();
        let number = tab.pull_request.number;
        let store = tab.stack.store();
        let requested_tip = tab.stack.requested_tip();
        let task = cx.background_spawn(async move {
            let provider = GithubProvider::new(repository.account.clone());
            load_stack(&provider, &repository, number, &store, requested_tip)
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let Some(tab_index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == token.repository_key()
                        && tab.pull_request.number == token.selected_pull_request()
                }) else {
                    return;
                };
                if this.tabs[tab_index].stack.accept(&token, result, this.wide) {
                    this.status = match &this.tabs[tab_index].stack.state {
                        StackLoadState::Ready => this.tabs[tab_index]
                            .stack
                            .tip_notice
                            .clone()
                            .unwrap_or_else(|| "Stack snapshot ready · read only".into()),
                        StackLoadState::Unavailable(reason) => {
                            format!("Stack unavailable · {reason}")
                        }
                        StackLoadState::Idle | StackLoadState::Loading(_) => {
                            "Reading Stack…".into()
                        }
                    };
                    this.load_selected_stack_local_file(tab_index, cx);
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn load_selected_stack_local_file(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        let Some(path) = tab.repository.local_path.clone() else {
            return;
        };
        let Some(session) = tab.stack.session.as_mut() else {
            return;
        };
        let Some(file) = session.selected_file() else {
            return;
        };
        if file.patch.is_some() {
            return;
        }
        let selected_key = file_key(file);
        let Ok(request) = session.begin_file_patch(&selected_key) else {
            return;
        };
        let revision = request.revision().clone();
        let requested_key = request.file_key().to_owned();
        let task =
            cx.background_spawn(
                async move { load_local_file(&path, &revision, &requested_key, false) },
            );
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let Some(tab_index) = this.tabs.iter().position(|tab| {
                    tab.stack
                        .session
                        .as_ref()
                        .is_some_and(|session| session.accepts_file_patch(&request))
                }) else {
                    return;
                };
                match result {
                    Ok(file) => {
                        let installed = this.tabs[tab_index]
                            .stack
                            .session
                            .as_mut()
                            .is_some_and(|session| session.accept_file_patch(&request, file).is_ok());
                        if installed {
                            this.tabs[tab_index].stack.rebuild(this.wide);
                        }
                    }
                    Err(error) => {
                        this.tabs[tab_index].stack.feedback = Some(format!(
                            "Selected local file is unavailable for this exact Stack pair: {error:#}"
                        ));
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn open_stack(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        self.tabs[index].local_visible = false;
        self.refresh_stack(cx);
    }

    fn return_to_pull_request(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        self.tabs[index].stack.capture_scroll();
        self.tabs[index].stack.close();
        self.status = "Published pull request review".into();
        cx.notify();
    }

    fn toggle_stack_relationships(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if !self.tabs[index].stack.visible {
            return;
        }
        self.tabs[index].stack.narrow_relationships_open =
            !self.tabs[index].stack.narrow_relationships_open;
        cx.notify();
    }

    fn set_stack_parent(
        &mut self,
        index: usize,
        parent: cibergit::stacks::StackPullRequestId,
        cx: &mut Context<Root>,
    ) {
        let repository = self.tabs[index].repository.clone();
        match self.tabs[index]
            .stack
            .prepare_set_selected_parent(&repository, parent)
        {
            Ok(write) => self.dispatch_stack_correction(write, cx),
            Err(error) => {
                self.status = error;
                cx.notify();
            }
        }
    }

    fn remove_stack_parent(&mut self, index: usize, cx: &mut Context<Root>) {
        let repository = self.tabs[index].repository.clone();
        match self.tabs[index]
            .stack
            .prepare_remove_selected_parent(&repository)
        {
            Ok(write) => self.dispatch_stack_correction(write, cx),
            Err(error) => {
                self.status = error;
                cx.notify();
            }
        }
    }

    fn reset_stack_relationships(&mut self, index: usize, cx: &mut Context<Root>) {
        let repository = self.tabs[index].repository.clone();
        match self.tabs[index]
            .stack
            .prepare_reset_corrections(&repository)
        {
            Ok(write) => self.dispatch_stack_correction(write, cx),
            Err(error) => {
                self.status = error;
                cx.notify();
            }
        }
    }

    fn dispatch_stack_correction(
        &mut self,
        write: stack_view::StackCorrectionWrite,
        cx: &mut Context<Root>,
    ) {
        self.status = "Saving personal relationship locally…".into();
        let task = cx.background_spawn(async move { write.execute() });
        cx.spawn(async move |root, cx| {
            let outcome = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let Some(tab_index) = this
                    .tabs
                    .iter()
                    .position(|tab| tab.stack.accepts(&outcome.token))
                else {
                    return;
                };
                if !this.tabs[tab_index]
                    .stack
                    .accept_correction(&outcome.token, &outcome.result)
                {
                    return;
                }
                match outcome.result {
                    Ok(message) => {
                        this.status = message;
                        this.refresh_stack_at(tab_index, cx);
                    }
                    Err(error) => {
                        this.status = error;
                        cx.notify();
                    }
                }
            });
        })
        .detach();
        cx.notify();
    }

    fn refresh(&mut self, _: &Refresh, _: &mut Window, cx: &mut Context<Root>) {
        if self.browser_active {
            // Re-reads from the first page. The index is ordered by activity,
            // so appending to pages read minutes ago would interleave rows
            // that have since moved.
            self.load_pr_browser(false, cx);
            return;
        }
        if self
            .active_tab
            .is_some_and(|index| self.tabs[index].stack.visible)
        {
            self.refresh_stack(cx);
            return;
        }
        self.refresh_all(cx);
        self.refresh_active(cx);
    }

    /// Closes one named tab, which is how the strip's close affordance differs
    /// from the keyboard action. Every draft and in-flight-write barrier the
    /// action enforces is written against the shared inputs, and those hold the
    /// active tab's text, so a background tab is brought forward first and then
    /// closed through the same path rather than removed behind those checks.
    fn close_tab_at(&mut self, index: usize, window: &mut Window, cx: &mut Context<Root>) {
        if index >= self.tabs.len() {
            return;
        }
        if self.active_tab != Some(index) {
            self.activate_tab(index, window, cx);
            if self.active_tab != Some(index) {
                // The transition refused and set its own status; leave the tab
                // open rather than closing one the inputs do not describe.
                return;
            }
        }
        self.close_tab(&CloseTab, window, cx);
    }

    fn close_tab(&mut self, _: &CloseTab, window: &mut Window, cx: &mut Context<Root>) {
        if let Some(index) = self.active_tab {
            if !self.restore_pending_active_tab_input_in_window(window, cx) {
                self.status = "Close refused until the exact active submitted-review input can be restored; no visible text was staged into another tab.".into();
                cx.notify();
                return;
            }
            if self.tabs[index].write_in_flight {
                self.status =
                    "Keep this tab open until the started write reaches a durable outcome.".into();
                cx.notify();
                return;
            }
            if self.persist_active_composer_before_transition(
                index,
                "Saving the exact active comment before closing this tab; close it again after the save finishes.",
                cx,
            ) { return; }
            let submitted_body = self.submitted_summary_input.read(cx).value().to_string();
            self.tabs[index]
                .submitted_summary_editor
                .store_active_body(submitted_body);
            let editor = &mut self.tabs[index].submitted_summary_editor;
            match editor.request_close() {
                SubmittedDraftCloseDisposition::WaitForOperation => {
                    self.composer_input
                        .update(cx, |input, cx| input.set_disabled(true, cx));
                    self.submitted_summary_input
                        .update(cx, |input, cx| input.set_disabled(true, cx));
                    self.status = "Waiting for the exact local submitted-review draft operation before close…".into();
                    cx.notify();
                    return;
                }
                SubmittedDraftCloseDisposition::RefuseRecovery => {
                    self.status = "Close refused: local submitted-review text is not reconciled with its bounded recovery read.".into();
                    cx.notify();
                    return;
                }
                SubmittedDraftCloseDisposition::Save => {
                    self.composer_input
                        .update(cx, |input, cx| input.set_disabled(true, cx));
                    self.submitted_summary_input
                        .update(cx, |input, cx| input.set_disabled(true, cx));
                    self.status = "Saving the latest submitted-review draft before close…".into();
                    self.start_next_submitted_draft_save(index, cx);
                    cx.notify();
                    return;
                }
                SubmittedDraftCloseDisposition::Safe => {}
            }
            self.finish_close_tab_in_window(index, window, cx);
            cx.notify();
        }
    }

    fn finish_close_tab(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(next_active) = self.remove_closed_tab(index, cx) else {
            self.save_workspace(cx);
            return;
        };
        self.activate_tab_context(next_active, false, cx);
        self.save_workspace(cx);
    }

    fn finish_close_tab_in_window(
        &mut self,
        index: usize,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) {
        let Some(next_active) = self.remove_closed_tab(index, cx) else {
            self.save_workspace(cx);
            return;
        };
        self.activate_tab_in_window(next_active, false, window, cx);
        self.save_workspace(cx);
    }

    fn remove_closed_tab(&mut self, index: usize, cx: &mut Context<Root>) -> Option<usize> {
        if index >= self.tabs.len() {
            return None;
        }
        self.record_user_navigation();
        self.closed_workspace_tabs.insert((
            self.tabs[index].repository.cache_key(),
            self.tabs[index].pull_request.number,
        ));
        self.capture_scroll(index);
        self.persist_session(index, cx);
        let previous_active = self.active_tab;
        self.tabs.remove(index);
        let next_active = match previous_active {
            Some(active) if active == index => {
                (!self.tabs.is_empty()).then(|| index.min(self.tabs.len() - 1))
            }
            Some(active) if active > index => Some(active - 1),
            other => other,
        };
        self.active_tab = None;
        self.active_tab_input_restore = None;
        next_active
    }

    fn cycle_diff(&mut self, _: &CycleDiffMode, _window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].stack.visible {
            self.tabs[index].stack.cycle_diff(self.wide);
            cx.notify();
            return;
        }
        self.capture_scroll(index);
        if let Some(session) = &mut self.tabs[index].session {
            session.set_diff_mode(match session.diff_mode() {
                DiffMode::Auto => DiffMode::Unified,
                DiffMode::Unified => DiffMode::SideBySide,
                DiffMode::SideBySide => DiffMode::Auto,
            });
            self.rebuild_diff(index, self.wide);
            self.save_workspace(cx);
            self.persist_session(index, cx);
            cx.notify();
        }
    }

    fn toggle_diff_layout(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        self.capture_scroll(index);
        if let Some(session) = &mut self.tabs[index].session {
            session.set_diff_mode(match session.diff_mode().resolve(self.wide) {
                DiffMode::SideBySide => DiffMode::Unified,
                _ => DiffMode::SideBySide,
            });
            self.rebuild_diff(index, self.wide);
            self.save_workspace(cx);
            self.persist_session(index, cx);
            cx.notify();
        }
    }

    fn toggle_viewed(&mut self, key: &str, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if let Some(session) = &mut self.tabs[index].session {
            let viewed = !session.is_viewed(key);
            if session.mark_viewed(key, viewed) {
                self.save_workspace(cx);
                self.persist_session(index, cx);
                cx.notify();
            }
        }
    }

    fn move_file_tree_cursor(&mut self, delta: isize, window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if let Some(key) = self.tabs[index].file_tree.move_cursor(delta) {
            self.select_file(&key, self.wide, cx);
        }
        if let Some(row) = self.tabs[index].file_tree.cursor_index() {
            self.tabs[index]
                .file_tree_scroll
                .scroll_to_item(row, ScrollStrategy::Nearest);
        }
        window.focus(&self.file_tree_focus, cx);
        cx.notify();
    }

    fn file_tree_left(&mut self, window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        self.tabs[index].file_tree.left();
        if let Some(row) = self.tabs[index].file_tree.cursor_index() {
            self.tabs[index]
                .file_tree_scroll
                .scroll_to_item(row, ScrollStrategy::Nearest);
        }
        window.focus(&self.file_tree_focus, cx);
        cx.notify();
    }

    fn file_tree_right(&mut self, window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if let Some(key) = self.tabs[index].file_tree.right() {
            self.select_file(&key, self.wide, cx);
        }
        if let Some(row) = self.tabs[index].file_tree.cursor_index() {
            self.tabs[index]
                .file_tree_scroll
                .scroll_to_item(row, ScrollStrategy::Nearest);
        }
        window.focus(&self.file_tree_focus, cx);
        cx.notify();
    }

    fn activate_file_tree(&mut self, window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if let Some(key) = self.tabs[index].file_tree.activate_cursor() {
            self.select_file(&key, self.wide, cx);
        }
        window.focus(&self.file_tree_focus, cx);
        cx.notify();
    }

    /// The diff pane the keyboard is addressing. History replaces the whole
    /// main section, so it wins whenever it is up; within a tab, Stack covers
    /// the review pane the same way.
    ///
    /// Before this existed, each diff action reached for the pane it wanted by
    /// hand and only two of the three were ever branched on, so History's diff
    /// answered none of them.
    fn active_diff(&self) -> Option<&diff_pane::DiffPaneState> {
        if self.history_active {
            return self.history.as_ref().map(|history| &history.diff);
        }
        let tab = self.tabs.get(self.active_tab?)?;
        Some(if tab.stack.visible {
            &tab.stack.diff
        } else {
            &tab.diff
        })
    }

    fn active_diff_mut(&mut self) -> Option<&mut diff_pane::DiffPaneState> {
        if self.history_active {
            return self.history.as_mut().map(|history| &mut history.diff);
        }
        let tab = self.tabs.get_mut(self.active_tab?)?;
        Some(if tab.stack.visible {
            &mut tab.stack.diff
        } else {
            &mut tab.diff
        })
    }

    /// Rebuild whichever diff is on screen. Folding a file, like changing the
    /// reading mode, changes what the rows are rather than where the reader is
    /// in them, so every surface goes back through its own builder.
    fn rebuild_active_diff(&mut self, cx: &mut Context<Root>) {
        let wide = self.wide;
        let mode = self.workspace.preferences.reading_mode;
        if self.history_active {
            if let Some(history) = self.history.as_mut() {
                history.rebuild(wide, mode);
            }
            cx.notify();
            return;
        }
        if let Some(index) = self.active_tab {
            self.rebuild_diff(index, wide);
        }
        cx.notify();
    }

    /// Fold or unfold one file, and leave the cursor on the header that did it
    /// so the keyboard keeps its place rather than jumping to the top.
    fn toggle_diff_file(&mut self, key: &str, _window: &mut Window, cx: &mut Context<Root>) {
        let Some(diff) = self.active_diff_mut() else {
            return;
        };
        diff.toggle_file(key);
        self.rebuild_active_diff(cx);
        if let Some(diff) = self.active_diff_mut()
            && let Some(start) = diff.span_for_key(key).map(|span| span.rows.start)
        {
            diff.cursor = Some(start);
            diff.vertical.scroll_to_reveal_item(start);
        }
        cx.notify();
    }

    /// Fold the whole comparison, or open it again. One control rather than
    /// two: a mixed scroll folds first, and only an entirely folded one offers
    /// to open, so the button always does the thing its label says.
    fn toggle_all_diff_files(&mut self, cx: &mut Context<Root>) {
        let Some(diff) = self.active_diff_mut() else {
            return;
        };
        let collapse = !diff.all_collapsed();
        diff.set_all_collapsed(collapse);
        self.rebuild_active_diff(cx);
        cx.notify();
    }

    fn move_diff_cursor(&mut self, delta: isize, cx: &mut Context<Root>) {
        if self
            .active_diff_mut()
            .is_some_and(|diff| diff.move_cursor(delta))
        {
            cx.notify();
        }
    }

    fn jump_diff_cursor(
        &mut self,
        forward: bool,
        accept: fn(&DiffRow) -> bool,
        cx: &mut Context<Root>,
    ) {
        if self
            .active_diff_mut()
            .is_some_and(|diff| diff.jump(forward, accept))
        {
            cx.notify();
        }
    }

    /// Mark the open file viewed and move to the next one that is not. The
    /// pair is one action because marking without advancing leaves the reader
    /// on a file they have just finished with, and every reviewer then reaches
    /// for the next-file key anyway.
    ///
    /// Only the review pane keeps viewed state; History and Stack are
    /// read-only, so there the action does nothing rather than advancing a
    /// selection the reader did not ask to move.
    fn mark_viewed_and_advance(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.history_active || self.tabs[index].stack.visible {
            return;
        }
        let Some(session) = self.tabs[index].session.as_ref() else {
            return;
        };
        let Some(current) = session.selected_file().map(file_key) else {
            return;
        };
        // The next unviewed file after this one, wrapping once so finishing
        // the last file lands on whatever is still outstanding above it.
        let files = session.comparison().files.clone();
        let position = files.iter().position(|file| file_key(file) == current);
        let next = position.and_then(|position| {
            files
                .iter()
                .cycle()
                .skip(position + 1)
                .take(files.len().saturating_sub(1))
                .map(file_key)
                .find(|key| {
                    self.tabs[index]
                        .session
                        .as_ref()
                        .is_some_and(|session| !session.is_viewed(key))
                })
        });
        if let Some(session) = self.tabs[index].session.as_mut()
            && session.mark_viewed(&current, true)
        {
            self.save_workspace(cx);
            self.persist_session(index, cx);
        }
        match next {
            Some(key) => self.select_file(&key, self.wide, cx),
            // Nothing left unviewed: stay put and say so rather than moving.
            None => self.status = "Every changed file is marked viewed".into(),
        }
        cx.notify();
    }

    fn scroll_diff_horizontally(&mut self, amount: Option<f32>, cx: &mut Context<Root>) {
        // Streaming gives every file its own offset, so "scroll the diff
        // sideways" means the file the cursor is in, not the whole scroll.
        let Some(handle) = self
            .active_diff()
            .map(|diff| diff.scroll_context(diff.cursor.unwrap_or(0)).0)
        else {
            return;
        };
        let current = handle.offset();
        let maximum = handle.max_offset().x.as_f32();
        let target = match amount {
            Some(amount) => (current.x.as_f32() - amount).clamp(-maximum, 0.),
            None => -maximum,
        };
        handle.set_offset(point(px(target), px(0.)));
        cx.notify();
    }

    fn apply_filter(&mut self, personal: PersonalFilter, cx: &mut Context<Root>) {
        self.sidebar_search_generation += 1;
        self.sidebar_scroll.scroll_to_item(0, ScrollStrategy::Top);
        let mut view = self.workspace.view();
        view.filter.search = self.query.read(cx).value().trim().to_owned();
        view.filter.personal = personal;
        self.workspace.views[self.workspace.selected_view] = view;
        self.save_workspace(cx);
        cx.notify();
    }

    fn open_view_editor(&mut self, window: &mut Window, cx: &mut Context<Root>) {
        let view = self.workspace.view();
        self.view_editor.begin(&self.workspace);
        self.view_editor_scroll.set_offset(point(px(0.), px(0.)));
        self.view_inputs.set_view(&view, window, cx);
        self.command_palette = false;
        self.view_inputs
            .name
            .read(cx)
            .focus_handle(cx)
            .focus(window, cx);
        cx.notify();
    }

    fn sync_view_editor_inputs(&mut self, cx: &Context<Root>) {
        let Some(draft) = self.view_editor.draft() else {
            return;
        };
        let filter = self.view_inputs.filter(&draft.filter, cx);
        let prefix = ViewEditorInputs::value(&self.view_inputs.source_prefix, cx);
        let source_index = draft
            .groups
            .iter()
            .position(|group| matches!(group, GroupBy::SourceBranch | GroupBy::SourcePrefix(_)));
        self.view_editor.replace_filter(filter);
        if let Some(index) = source_index {
            let uses_prefix = self
                .view_editor
                .draft()
                .and_then(|view| view.groups.get(index))
                .is_some_and(|group| matches!(group, GroupBy::SourcePrefix(_)));
            if uses_prefix {
                self.view_editor
                    .set_source_group_prefix(index, Some(&prefix));
            }
        }
    }

    fn commit_view_editor(&mut self, save_as: bool, window: &mut Window, cx: &mut Context<Root>) {
        let old_state = self.workspace.view().filter.state;
        self.sync_view_editor_inputs(cx);
        let name = ViewEditorInputs::value(&self.view_inputs.name, cx);
        let result = if save_as {
            self.view_editor.save_as(&mut self.workspace, &name)
        } else {
            self.view_editor.apply(&mut self.workspace, &name)
        };
        match result {
            Ok(()) => {
                let view = self.workspace.view();
                self.query.update(cx, |query, cx| {
                    query.set_value(view.filter.search.clone(), window, cx)
                });
                self.save_workspace(cx);
                if old_state != view.filter.state {
                    self.refresh_all(cx);
                }
                self.status = if save_as {
                    format!("Saved view “{}”", view.name)
                } else {
                    format!("Applied view “{}”", view.name)
                };
                self.focus.focus(window, cx);
            }
            Err(error) => {
                self.status = error;
            }
        }
        cx.notify();
    }

    fn cancel_view_editor(&mut self, window: &mut Window, cx: &mut Context<Root>) {
        self.view_editor.cancel();
        self.status = "View changes cancelled".into();
        self.focus.focus(window, cx);
        cx.notify();
    }

    fn delete_current_view(&mut self, window: &mut Window, cx: &mut Context<Root>) {
        let old_state = self.workspace.view().filter.state;
        self.view_editor.delete_selected(&mut self.workspace);
        let view = self.workspace.view();
        self.query.update(cx, |query, cx| {
            query.set_value(view.filter.search.clone(), window, cx)
        });
        self.save_workspace(cx);
        if old_state != view.filter.state {
            self.refresh_all(cx);
        }
        self.status = "Deleted saved view; a usable view remains selected".into();
        self.focus.focus(window, cx);
        cx.notify();
    }

    fn select_view(&mut self, index: usize, window: &mut Window, cx: &mut Context<Root>) {
        self.sidebar_search_generation += 1;
        if index >= self.workspace.views.len() {
            return;
        }
        self.workspace.selected_view = index;
        self.sidebar_scroll.scroll_to_item(0, ScrollStrategy::Top);
        self.view_editor.cancel();
        let search = self.workspace.view().filter.search;
        self.query
            .update(cx, |query, cx| query.set_value(search, window, cx));
        self.save_workspace(cx);
        self.refresh_all(cx);
        cx.notify();
    }

    fn advance_revision(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        let revision = self.tabs[index]
            .canonical_session
            .as_ref()
            .and_then(|session| session.available_revision().cloned());
        if let Some(revision) = revision {
            self.load_comparison(index, revision, true, cx);
        }
    }

    fn render(&mut self, window: &mut Window, cx: &mut Context<Root>) -> impl IntoElement {
        let colors = palette(is_dark(window));
        div()
            .id("review-workspace")
            .track_focus(&self.focus)
            .on_action(
                cx.listener(|root, _: &local_checkout::OpenLocalChanges, window, cx| {
                    let this = &mut root.review;
                    this.open_local_changes(window, cx);
                }),
            )
            .on_action(
                cx.listener(|root, _: &local_checkout::ReturnToReview, _, cx| {
                    let this = &mut root.review;
                    if let Some(index) = this.active_tab {
                        this.tabs[index].local_visible = false;
                    }
                    cx.notify();
                }),
            )
            .on_action(cx.listener(|root, action: &Refresh, window, cx| {
                let this = &mut root.review;
                this.refresh(action, window, cx)
            }))
            .on_action(cx.listener(|root, _: &OpenStackView, _, cx| {
                let this = &mut root.review;
                this.open_stack(cx);
            }))
            .on_action(cx.listener(|root, _: &RefreshStackView, _, cx| {
                let this = &mut root.review;
                this.refresh_stack(cx);
            }))
            .on_action(cx.listener(|root, _: &SelectNextStackTip, _, cx| {
                let this = &mut root.review;
                this.select_next_stack_tip(cx);
            }))
            .on_action(cx.listener(|root, _: &ToggleStackRelationships, _, cx| {
                let this = &mut root.review;
                this.toggle_stack_relationships(cx);
            }))
            .on_action(cx.listener(|root, _: &ReturnToPullRequest, _, cx| {
                let this = &mut root.review;
                this.return_to_pull_request(cx);
            }))
            .on_action(cx.listener(|root, action: &NextFile, window, cx| {
                let this = &mut root.review;
                this.next_file(action, window, cx)
            }))
            .on_action(cx.listener(|root, action: &PreviousFile, window, cx| {
                let this = &mut root.review;
                this.previous_file(action, window, cx)
            }))
            .on_action(cx.listener(|root, action: &CloseTab, window, cx| {
                let this = &mut root.review;
                this.close_tab(action, window, cx)
            }))
            .on_action(cx.listener(|root, _: &Save, window, cx| {
                let this = &mut root.review;
                if this.view_editor.is_open() {
                    this.commit_view_editor(false, window, cx);
                }
            }))
            .on_action(cx.listener(|root, _: &TogglePalette, _, cx| {
                let this = &mut root.review;
                this.command_palette = !this.command_palette;
                cx.notify();
            }))
            .on_action(cx.listener(|root, _: &ToggleComparisonPicker, window, cx| {
                let this = &mut root.review;
                if let Some(index) = this.active_tab {
                    this.inspector_open = true;
                    this.tabs[index].inspector_section = InspectorSection::Commits;
                    this.tabs[index].comparison_picker.expanded = true;
                    this.refresh_auto_layout(window);
                    cx.notify();
                }
            }))
            .on_action(cx.listener(|root, _: &SelectFullComparison, _, cx| {
                let this = &mut root.review;
                if let Some(index) = this.active_tab {
                    this.restore_full_comparison(index, cx);
                }
            }))
            .on_action(cx.listener(|root, _: &SelectSinceLastReview, _, cx| {
                let this = &mut root.review;
                if let Some(index) = this.active_tab {
                    this.select_since_last_review(index, cx);
                }
            }))
            .on_action(
                cx.listener(|root, _: &SelectPreviousComparisonCommit, _, cx| {
                    let this = &mut root.review;
                    this.step_comparison_commit(-1, cx);
                }),
            )
            .on_action(cx.listener(|root, _: &SelectNextComparisonCommit, _, cx| {
                let this = &mut root.review;
                this.step_comparison_commit(1, cx);
            }))
            .on_action(cx.listener(|root, _: &ToggleInspector, window, cx| {
                let this = &mut root.review;
                this.inspector_open = !this.inspector_open;
                this.refresh_auto_layout(window);
                cx.notify();
            }))
            .on_action(cx.listener(|root, _: &OpenChecks, window, cx| {
                let this = &mut root.review;
                this.open_checks(window, cx);
            }))
            .on_action(cx.listener(|root, _: &PreviousCheck, window, cx| {
                let this = &mut root.review;
                this.move_check_selection(-1, window, cx);
            }))
            .on_action(cx.listener(|root, _: &NextCheck, window, cx| {
                let this = &mut root.review;
                this.move_check_selection(1, window, cx);
            }))
            .on_action(cx.listener(|root, _: &PreviousCheckPage, window, cx| {
                let this = &mut root.review;
                this.move_checks_page(-1, window, cx);
            }))
            .on_action(cx.listener(|root, _: &NextCheckPage, window, cx| {
                let this = &mut root.review;
                this.move_checks_page(1, window, cx);
            }))
            // Enter is bound to this pane-level shortcut in the ChecksPane
            // context, so every focusable control inside the pane inherits the
            // binding and GPUI stops propagation before the control's own
            // Enter/Space activation can arm. The shortcut belongs to the pane
            // only while the pane itself holds focus; once focus moves onto a
            // control, Enter is that control's to answer.
            .on_action(cx.listener(|root, _: &ToggleCheckIdentity, window, cx| {
                let this = &mut root.review;
                if !this.checks_focus.is_focused(window) {
                    cx.propagate();
                    return;
                }
                this.toggle_selected_check(cx);
            }))
            .on_action(cx.listener(|root, _: &OpenSelectedCheckJobs, window, cx| {
                let this = &mut root.review;
                if let Some(index) = this.active_tab
                    && this.start_actions_jobs(index, cx)
                {
                    this.focus_current_ci_pane(index, window, cx);
                }
            }))
            .on_action(
                cx.listener(|root, _: &RefreshSelectedCheckJobs, window, cx| {
                    let this = &mut root.review;
                    if let Some(index) = this.active_tab
                        && this.start_actions_jobs(index, cx)
                    {
                        this.focus_current_ci_pane(index, window, cx);
                    }
                }),
            )
            .on_action(cx.listener(|root, _: &PreviousJob, window, cx| {
                let this = &mut root.review;
                this.move_job_selection(-1, window, cx);
            }))
            .on_action(cx.listener(|root, _: &NextJob, window, cx| {
                let this = &mut root.review;
                this.move_job_selection(1, window, cx);
            }))
            .on_action(cx.listener(|root, _: &PreviousJobPage, window, cx| {
                let this = &mut root.review;
                this.move_jobs_page(-1, window, cx);
            }))
            .on_action(cx.listener(|root, _: &NextJobPage, window, cx| {
                let this = &mut root.review;
                this.move_jobs_page(1, window, cx);
            }))
            // Enter is bound to this pane-level shortcut in the ChecksJobsPane
            // context, and a key binding matches against the focused node's
            // whole context stack. Without this guard a focused job row would
            // never answer its own Enter: the pane shortcut would load the
            // already-selected job's log instead of selecting the focused row.
            .on_action(cx.listener(|root, _: &LoadSelectedJobLog, window, cx| {
                let this = &mut root.review;
                if !this.jobs_focus.is_focused(window) {
                    cx.propagate();
                    return;
                }
                if let Some(index) = this.active_tab
                    && this.start_actions_log(index, cx)
                {
                    this.focus_current_ci_pane(index, window, cx);
                }
            }))
            .on_action(cx.listener(|root, _: &ReturnToChecks, window, cx| {
                let this = &mut root.review;
                if let Some(index) = this.active_tab {
                    this.tabs[index].ci_read.pane = CiPane::Checks;
                    this.focus_current_ci_pane(index, window, cx);
                    cx.notify();
                }
            }))
            .on_action(cx.listener(|root, _: &ReturnToJobs, window, cx| {
                let this = &mut root.review;
                if let Some(index) = this.active_tab {
                    this.tabs[index].ci_read.pane = CiPane::Jobs;
                    this.focus_current_ci_pane(index, window, cx);
                    cx.notify();
                }
            }))
            .on_action(cx.listener(|root, action: &CycleDiffMode, window, cx| {
                let this = &mut root.review;
                this.cycle_diff(action, window, cx)
            }))
            .on_action(cx.listener(|root, _: &OpenRepositorySetup, window, cx| {
                let this = &mut root.review;
                this.open_repository_picker(window, cx);
            }))
            .on_action(cx.listener(|root, _: &OpenSettings, _, cx| {
                let this = &mut root.review;
                this.open_settings(cx);
            }))
            .on_action(cx.listener(|root, _: &OpenHistory, _, cx| {
                let this = &mut root.review;
                this.open_history(None, cx);
            }))
            .on_action(cx.listener(|root, _: &OpenPullRequestBrowser, _, cx| {
                let this = &mut root.review;
                this.open_pr_browser(None, cx);
            }))
            .on_action(
                cx.listener(|root, _: &OpenPullRequestCreation, window, cx| {
                    let this = &mut root.review;
                    this.open_creation_dialog(window, cx);
                }),
            )
            .on_action(cx.listener(|root, _: &ComposeInlineComment, window, cx| {
                let this = &mut root.review;
                this.compose_first_selectable(window, cx);
            }))
            .on_action(cx.listener(|root, _: &SaveReviewDraft, _, cx| {
                let this = &mut root.review;
                this.persist_composer(cx);
            }))
            .on_action(cx.listener(|root, _: &AddPendingComment, _, cx| {
                let this = &mut root.review;
                this.start_comment_write(false, cx);
            }))
            .on_action(cx.listener(|root, _: &PostImmediateComment, _, cx| {
                let this = &mut root.review;
                this.start_comment_write(true, cx);
            }))
            .on_action(cx.listener(|root, _: &SubmitReview, _, cx| {
                let this = &mut root.review;
                this.open_submit_confirmation(cx);
            }))
            .on_action(cx.listener(|root, _: &MergePullRequest, _, cx| {
                let this = &mut root.review;
                this.prepare_merge_confirmation(cx);
            }))
            .on_action(cx.listener(|root, _: &EditPrMetadata, window, cx| {
                let this = &mut root.review;
                this.begin_metadata_edit(window, cx);
            }))
            .on_action(cx.listener(|root, _: &ApplyPrMetadata, _, cx| {
                let this = &mut root.review;
                this.apply_metadata_edit(cx);
            }))
            .on_action(cx.listener(|root, _: &NewPrDiscussion, window, cx| {
                let this = &mut root.review;
                this.begin_comment_create(window, cx);
            }))
            .on_action(cx.listener(|root, _: &ApplyPrDiscussion, _, cx| {
                let this = &mut root.review;
                this.apply_discussion(cx);
            }))
            .on_action(cx.listener(|root, _: &ConfirmPrMutation, _, cx| {
                let this = &mut root.review;
                this.confirm_lifecycle_mutation(cx);
            }))
            .on_action(cx.listener(|root, _: &CancelPrMutation, _, cx| {
                let this = &mut root.review;
                if let Some(index) = this.active_tab
                    && !this.tabs[index].write_in_flight
                {
                    if this.tabs[index].lifecycle.confirmation.is_some() {
                        this.tabs[index].lifecycle.cancel_confirmation();
                    } else if this.tabs[index].lifecycle.discussion_form.is_some() {
                        this.tabs[index].lifecycle.cancel_discussion();
                    } else {
                        this.tabs[index].lifecycle.cancel_metadata();
                    }
                    this.status = "Lifecycle edit cancelled; zero writes sent.".into();
                    cx.notify();
                }
            }))
            .on_action(cx.listener(|root, _: &FileTreeUp, window, cx| {
                let this = &mut root.review;
                this.move_file_tree_cursor(-1, window, cx);
            }))
            .on_action(cx.listener(|root, _: &FileTreeDown, window, cx| {
                let this = &mut root.review;
                this.move_file_tree_cursor(1, window, cx);
            }))
            .on_action(cx.listener(|root, _: &FileTreeLeft, window, cx| {
                let this = &mut root.review;
                this.file_tree_left(window, cx);
            }))
            .on_action(cx.listener(|root, _: &FileTreeRight, window, cx| {
                let this = &mut root.review;
                this.file_tree_right(window, cx);
            }))
            .on_action(cx.listener(|root, _: &FileTreeActivate, window, cx| {
                let this = &mut root.review;
                this.activate_file_tree(window, cx);
            }))
            .on_action(cx.listener(|root, _: &ToggleSidebar, window, cx| {
                let this = &mut root.review;
                this.panel_layout.sidebar_collapsed = !this.panel_layout.sidebar_collapsed;
                this.refresh_auto_layout(window);
                cx.notify();
            }))
            .on_action(cx.listener(|root, _: &ToggleFileTree, window, cx| {
                let this = &mut root.review;
                this.panel_layout.file_tree_collapsed = !this.panel_layout.file_tree_collapsed;
                this.refresh_auto_layout(window);
                cx.notify();
            }))
            .on_action(cx.listener(|root, _: &SidebarNarrower, window, cx| {
                let this = &mut root.review;
                this.adjust_panel(PanelKind::Sidebar, -PANEL_KEYBOARD_STEP, window, cx);
            }))
            .on_action(cx.listener(|root, _: &SidebarWider, window, cx| {
                let this = &mut root.review;
                this.adjust_panel(PanelKind::Sidebar, PANEL_KEYBOARD_STEP, window, cx);
            }))
            .on_action(cx.listener(|root, _: &FileTreeNarrower, window, cx| {
                let this = &mut root.review;
                this.adjust_panel(PanelKind::FileTree, -PANEL_KEYBOARD_STEP, window, cx);
            }))
            .on_action(cx.listener(|root, _: &FileTreeWider, window, cx| {
                let this = &mut root.review;
                this.adjust_panel(PanelKind::FileTree, PANEL_KEYBOARD_STEP, window, cx);
            }))
            .on_action(cx.listener(|root, _: &DetailsNarrower, window, cx| {
                let this = &mut root.review;
                this.adjust_panel(PanelKind::Details, -PANEL_KEYBOARD_STEP, window, cx);
            }))
            .on_action(cx.listener(|root, _: &DetailsWider, window, cx| {
                let this = &mut root.review;
                this.adjust_panel(PanelKind::Details, PANEL_KEYBOARD_STEP, window, cx);
            }))
            .on_action(cx.listener(|root, _: &ResetLayout, window, cx| {
                let this = &mut root.review;
                this.reset_layout(window, cx);
            }))
            .on_action(cx.listener(|root, _: &DiffScrollLeft, _, cx| {
                let this = &mut root.review;
                this.scroll_diff_horizontally(Some(-96.), cx);
            }))
            .on_action(cx.listener(|root, _: &DiffScrollRight, _, cx| {
                let this = &mut root.review;
                this.scroll_diff_horizontally(Some(96.), cx);
            }))
            .on_action(cx.listener(|root, _: &DiffScrollHome, _, cx| {
                let this = &mut root.review;
                if let Some(diff) = this.active_diff() {
                    let (handle, _) = diff.scroll_context(diff.cursor.unwrap_or(0));
                    handle.set_offset(point(px(0.), px(0.)));
                    cx.notify();
                }
            }))
            .on_action(cx.listener(|root, _: &DiffScrollEnd, _, cx| {
                let this = &mut root.review;
                this.scroll_diff_horizontally(None, cx);
            }))
            .on_action(cx.listener(|root, _: &DiffCursorDown, _, cx| {
                root.review.move_diff_cursor(1, cx);
            }))
            .on_action(cx.listener(|root, _: &DiffCursorUp, _, cx| {
                root.review.move_diff_cursor(-1, cx);
            }))
            .on_action(cx.listener(|root, _: &DiffNextHunk, _, cx| {
                root.review.jump_diff_cursor(true, is_hunk_row, cx);
            }))
            .on_action(cx.listener(|root, _: &DiffPreviousHunk, _, cx| {
                root.review.jump_diff_cursor(false, is_hunk_row, cx);
            }))
            .on_action(cx.listener(|root, _: &DiffNextThread, _, cx| {
                root.review.jump_diff_cursor(true, is_thread_row, cx);
            }))
            .on_action(cx.listener(|root, _: &DiffPreviousThread, _, cx| {
                root.review.jump_diff_cursor(false, is_thread_row, cx);
            }))
            .on_action(cx.listener(|root, _: &DiffCursorToStart, _, cx| {
                let this = &mut root.review;
                if this
                    .active_diff_mut()
                    .is_some_and(|diff| diff.cursor_to_start())
                {
                    cx.notify();
                }
            }))
            .on_action(cx.listener(|root, _: &DiffCursorToEnd, _, cx| {
                let this = &mut root.review;
                if this
                    .active_diff_mut()
                    .is_some_and(|diff| diff.cursor_to_end())
                {
                    cx.notify();
                }
            }))
            .on_action(cx.listener(|root, _: &MarkViewedAndAdvance, _, cx| {
                root.review.mark_viewed_and_advance(cx);
            }))
            .on_action(cx.listener(|root, _: &ToggleAllFileSections, _, cx| {
                root.review.toggle_all_diff_files(cx);
            }))
            .on_key_down(cx.listener(|root, event: &KeyDownEvent, window, cx| {
                let this = &mut root.review;
                if this.view_editor.is_open() && event.keystroke.key == "escape" {
                    this.cancel_view_editor(window, cx);
                    cx.stop_propagation();
                }
            }))
            .size_full()
            .flex()
            .font_family(ui::TEXT_FONT)
            .ui_text(TextRole::Body)
            .text_color(colors.text)
            .bg(rgba(0x00000000))
            .child(self.render_sidebar(colors, window, cx))
            .child(self.render_splitter(PanelKind::Sidebar, colors, window, cx))
            .child(self.render_main(colors, window, cx))
            .when(self.command_palette, |root| {
                root.child(self.render_palette(colors, cx))
            })
            .when(self.view_editor.is_open(), |root| {
                root.child(self.render_view_editor(colors, cx))
            })
            .when(self.notifications.is_open(), |root| {
                root.child(self.notifications.render(colors, cx))
            })
            .when_some(self.creation_dialog.clone(), |root, dialog| {
                root.child(dialog)
            })
    }

    fn render_splitter(
        &self,
        panel: PanelKind,
        colors: Palette,
        window: &Window,
        cx: &mut Context<Root>,
    ) -> impl IntoElement {
        let (sidebar, tree, details) = self.resolved_panel_widths(window);
        let start_width = match panel {
            PanelKind::Sidebar => sidebar,
            PanelKind::FileTree => tree,
            PanelKind::Details => details,
            PanelKind::HistoryCommits => self
                .history
                .as_ref()
                .map(|history| history.commit_width)
                .unwrap_or(HISTORY_COMMIT_COLUMN),
        };
        let drag = PanelResizeDrag {
            panel,
            start_width,
            start_x: Rc::new(Cell::new(None)),
        };
        div().w(px(0.)).h_full().flex_none().relative().child(
            div()
                .id(SharedString::from(format!("splitter-{panel:?}")))
                .absolute()
                .top_0()
                .bottom_0()
                .left(px(-SPLITTER_WIDTH / 2.))
                .w(px(SPLITTER_WIDTH))
                .cursor(gpui::CursorStyle::ResizeLeftRight)
                .hover(|splitter| splitter.bg(colors.selected))
                .debug_selector(move || format!("splitter-{panel:?}"))
                .on_drag(drag, |drag, _, window, cx| {
                    // GPUI supplies a local preview offset here, not a window position.
                    drag.start_x.set(Some(window.mouse_position().x.as_f32()));
                    cx.new(|_| SplitterDragPreview)
                })
                .on_drag_move(cx.listener(
                    |root, event: &DragMoveEvent<PanelResizeDrag>, window, cx| {
                        let this = &mut root.review;
                        let drag = event.drag(cx);
                        let Some(start_x) = drag.start_x.get() else {
                            return;
                        };
                        let mut delta = event.event.position.x.as_f32() - start_x;
                        if drag.panel == PanelKind::Details {
                            delta = -delta;
                        }
                        let width = (drag.start_width + delta).clamp(
                            match drag.panel {
                                PanelKind::Sidebar => MIN_SIDEBAR_WIDTH,
                                PanelKind::FileTree => MIN_FILE_TREE_WIDTH,
                                PanelKind::Details => MIN_DETAILS_WIDTH,
                                PanelKind::HistoryCommits => MIN_HISTORY_COMMIT_COLUMN,
                            },
                            MAX_PANEL_WIDTH,
                        );
                        match drag.panel {
                            PanelKind::Sidebar => {
                                this.panel_layout.sidebar_width = width;
                                this.panel_layout.sidebar_collapsed = false;
                            }
                            PanelKind::FileTree => {
                                this.panel_layout.file_tree_width = width;
                                this.panel_layout.file_tree_collapsed = false;
                            }
                            PanelKind::Details => {
                                this.panel_layout.details_width = width;
                                this.inspector_open = true;
                            }
                            PanelKind::HistoryCommits => {
                                if let Some(history) = this.history.as_mut() {
                                    history.commit_width = width;
                                    history.commits_collapsed = false;
                                }
                            }
                        }
                        this.refresh_auto_layout(window);
                        cx.notify();
                    },
                )),
        )
    }

    fn render_sidebar_row(
        &self,
        row: &SidebarRow,
        colors: Palette,
        root: Entity<Root>,
    ) -> AnyElement {
        #[cfg(feature = "ui-smoke")]
        self.sidebar_materializations
            .set(self.sidebar_materializations.get() + 1);
        match row {
            SidebarRow::Group { depth, label } => div()
                .h(px(ui::ROW_HEIGHT))
                .pl(px(16. + *depth as f32 * 14.))
                .pr(px(ui::CELL_INSET))
                .flex()
                .items_center()
                .gap(px(ui::GAP_ICON))
                .text_color(colors.muted)
                .child(sidebar_icon(
                    if *depth == 0 { "folder" } else { "branch" },
                    colors.muted,
                ))
                .child(
                    div()
                        .min_w_0()
                        .overflow_hidden()
                        .text_ellipsis()
                        .whitespace_nowrap()
                        .child(label.clone()),
                )
                .into_any_element(),
            SidebarRow::Pull {
                repository_index,
                repository_key,
                pull_request,
            } => {
                let pull_request = pull_request.as_ref();
                let repository_index = *repository_index;
                let selected = self
                    .active_tab
                    .and_then(|index| self.tabs.get(index))
                    .is_some_and(|tab| {
                        tab.repository.cache_key() == *repository_key
                            && tab.pull_request.number == pull_request.number
                    });
                let number = pull_request.number;
                let Some(runtime) = self
                    .repositories
                    .get(repository_index)
                    .filter(|runtime| runtime.repository.cache_key() == *repository_key)
                else {
                    return div().h(px(ui::ROW_HEIGHT)).into_any_element();
                };
                let click_repository = runtime.repository.clone();
                let unread = self.notifications.unread_for(
                    &self.repositories[repository_index].repository.account,
                    &self.repositories[repository_index].repository.owner,
                    &self.repositories[repository_index].repository.name,
                    number,
                );
                div()
                    .w_full()
                    .h(px(ui::ROW_HEIGHT))
                    .px(px(ui::CELL_INSET))
                    .py_0()
                    .child(
                        Button::new(format!("pr-{repository_index}-{number}"))
                            .control()
                            .ui_text(TextRole::Body)
                            .debug_selector(move || format!("sidebar-pr-{number}"))
                            .w_full()
                            .min_w_0()
                            .h(px(ui::ROW_HEIGHT))
                            .pl(px(30.))
                            .pr(px(ui::CELL_INSET))
                            .rounded(px(ui::CONTROL_RADIUS))
                            .flex()
                            .items_center()
                            .gap(px(ui::GAP_ICON))
                            .selected(selected)
                            .text_color(colors.muted)
                            .when(selected, |row| {
                                row.bg(colors.selected).text_color(colors.text)
                            })
                            .hover(|row| row.bg(colors.selected))
                            .accessibility_label(format!(
                                "{} · #{number} by {}{}",
                                pull_request.title,
                                pull_request.author,
                                if unread > 0 {
                                    ", unread notifications"
                                } else {
                                    ""
                                }
                            ))
                            .child(
                                div()
                                    .flex_1()
                                    .min_w_0()
                                    .overflow_hidden()
                                    .text_ellipsis()
                                    .whitespace_nowrap()
                                    .debug_selector(move || format!("sidebar-pr-{number}-title"))
                                    .child(pull_request.title.clone()),
                            )
                            .child(
                                div()
                                    .flex_none()
                                    .ui_text(TextRole::Caption)
                                    .text_color(if unread > 0 {
                                        colors.accent
                                    } else {
                                        colors.faint
                                    })
                                    .child(format!("#{number}")),
                            )
                            .on_click(move |_, window, cx| {
                                root.update(cx, |root, cx| {
                                    let this = &mut root.review;
                                    if this.repositories.get(repository_index).is_some_and(
                                        |runtime| runtime.repository == click_repository,
                                    ) {
                                        this.open_pr_in_window(
                                            repository_index,
                                            number,
                                            window,
                                            cx,
                                        );
                                    }
                                });
                            }),
                    )
                    .into_any_element()
            }
        }
    }

    /// The material is composited behind the Metal layer, so any surface that
    /// wants it has to stay unpainted for it to show, and `render_to_image`
    /// cannot contain it either way. The smoke harness therefore takes the solid
    /// fill, whose evidence its captures can actually carry.
    fn window_material(&self) -> SidebarMaterial {
        if cfg!(feature = "ui-smoke") {
            SidebarMaterial::Solid
        } else {
            self.workspace.preferences.sidebar_material
        }
    }

    fn render_sidebar(&self, colors: Palette, window: &Window, cx: &mut Context<Root>) -> Div {
        let (sidebar_width, _, _) = self.resolved_panel_widths(window);
        let glass = glass::sync_window(window, self.window_material());
        if self.panel_layout.sidebar_collapsed {
            return div()
                .w(px(sidebar_width))
                .h_full()
                .flex()
                .flex_col()
                .items_center()
                .when(!glass, |sidebar| sidebar.bg(colors.sidebar))
                .child(
                    div()
                        .id("restore-sidebar")
                        .mt(px(ui::GAP_PAGE))
                        .control()
                        .cursor_pointer()
                        .text_color(colors.accent)
                        .child("›")
                        .on_click(cx.listener(|root, _, window, cx| {
                            let this = &mut root.review;
                            this.panel_layout.sidebar_collapsed = false;
                            this.refresh_auto_layout(window);
                            cx.notify();
                        })),
                );
        }
        let view = self.workspace.view();
        let saved_views = self
            .workspace
            .views
            .iter()
            .enumerate()
            .map(|(index, saved)| {
                sidebar_nav_button(
                    format!("saved-view-{index}"),
                    &saved.name,
                    self.workspace.selected_view == index,
                    colors,
                )
                .on_click(cx.listener(move |root, _, window, cx| {
                    let this = &mut root.review;
                    this.select_view(index, window, cx)
                }))
            });
        let inventories = self
            .repositories
            .iter()
            .map(|runtime| (runtime.repository.clone(), runtime.pull_requests.clone()))
            .collect::<Vec<_>>();
        let mut cache = self.sidebar_cache.borrow_mut();
        let sidebar_rows = cache.rows_for(&inventories, &view);
        let participating_incomplete = cache.participating_incomplete;
        drop(cache);
        let mut rows = Vec::new();
        if sidebar_rows.is_empty() {
            rows.push(
                layout::lines()
                    .px(px(ui::PANEL_GUTTER)).py(px(ui::PANEL_GUTTER))
                    .child(div().ui_text(TextRole::Subtitle).font_weight(ui::WEIGHT_EMPHASIS).text_color(colors.muted)
                        .child(if self.repositories.is_empty() { "No repositories yet" } else { "No pull requests" }))
                    .child(div().ui_text(TextRole::Caption).text_color(colors.muted).line_height(px(18.))
                        .child(if self.repositories.is_empty() { "Add a repository to start reviewing." } else { "Nothing matches these filters. Try another view or clear your search." }))
                    .into_any_element(),
            );
        }
        for runtime in &self.repositories {
            if let Some(notice) = runtime.state.notice() {
                rows.push(
                    div()
                        .px(px(ui::PANEL_GUTTER))
                        .py(px(ui::GAP_ICON))
                        .ui_text(TextRole::Caption)
                        .text_color(colors.faint)
                        .child(notice)
                        .into_any_element(),
                );
            }
        }
        let filters = [
            ("filter-all", "Pull requests", PersonalFilter::All),
            (
                "filter-review",
                "Needs review",
                PersonalFilter::ReviewRequested,
            ),
            ("filter-mine", "Created by me", PersonalFilter::Own),
            (
                "filter-participating",
                "Participating",
                PersonalFilter::Participating,
            ),
        ]
        .into_iter()
        .map(|(id, label, personal)| {
            sidebar_nav_button(
                id.to_owned(),
                label,
                view.filter.personal == personal,
                colors,
            )
            .on_click(cx.listener(move |root, _, _, cx| {
                let this = &mut root.review;
                this.apply_filter(personal.clone(), cx);
            }))
        });
        let unread = self.notifications.unread_count();
        let account = self
            .active_tab
            .and_then(|index| self.tabs.get(index))
            .map(|tab| &tab.repository.account)
            .or_else(|| {
                self.repositories
                    .first()
                    .map(|repo| &repo.repository.account)
            })
            .or_else(|| self.accounts.first());
        let account_label = account
            .map(|account| account.login.as_str())
            .unwrap_or("No account connected");
        let initial = account
            .map(|account| {
                account
                    .login
                    .chars()
                    .next()
                    .unwrap_or('?')
                    .to_uppercase()
                    .to_string()
            })
            .unwrap_or_else(|| "?".into());
        div()
            .w(px(sidebar_width))
            .min_w(px(sidebar_width))
            .h_full()
            .flex()
            .flex_col()
            .when(!glass, |sidebar| sidebar.bg(colors.sidebar))
            .child(
                div()
                    .id("sidebar-titlebar")
                    .h(px(48.))
                    .flex_none()
                    .pl(px(WINDOW_CONTROLS_INSET))
                    .pr(px(ui::CONTROL_INSET))
                    .flex()
                    .items_center()
                    // Right-aligned so the toggle stacks directly above the
                    // notifications bell rather than trailing the traffic lights.
                    .justify_end()
                    .child(
                        sidebar_icon_button(
                            "collapse-sidebar",
                            "Collapse sidebar",
                            "panel",
                            colors,
                        )
                        .on_click(cx.listener(|root, _, window, cx| {
                            let this = &mut root.review;
                            this.panel_layout.sidebar_collapsed = true;
                            this.refresh_auto_layout(window);
                            cx.notify();
                        })),
                    ),
            )
            .child(
                div()
                    .px(px(ui::CONTROL_INSET))
                    .mt(px(ui::GAP_GROUP))
                    .h(px(ui::DESKTOP_HIT))
                    .flex_none()
                    .flex()
                    .items_center()
                    .gap(px(ui::GAP_ICON))
                    .child(
                        div()
                            .flex_1()
                            .pl(px(ui::GAP_ICON))
                            .ui_text(TextRole::Title)
                            .font_weight(ui::WEIGHT_EMPHASIS)
                            .child("cibergit"),
                    )
                    .child(
                        sidebar_icon_button(
                            "sidebar-search",
                            "Search pull requests",
                            "search",
                            colors,
                        )
                        .on_click(cx.listener(|root, _, window, cx| {
                            let this = &mut root.review;
                            this.sidebar_search_open = !this.sidebar_search_open;
                            if this.sidebar_search_open {
                                this.query.update(cx, |input, cx| input.focus(window, cx));
                            } else {
                                window.focus(&this.focus, cx);
                            }
                            cx.notify();
                        })),
                    )
                    .child(
                        sidebar_icon_button(
                            "open-notifications",
                            &format!("Inbox, {unread} unread notifications"),
                            "bell",
                            colors,
                        )
                        .relative()
                        .when(unread > 0, |button| {
                            button.child(
                                div()
                                    .absolute()
                                    .top(px(3.))
                                    .right(px(3.))
                                    .size(px(5.))
                                    .rounded_full()
                                    .bg(colors.accent),
                            )
                        })
                        .on_click(cx.listener(|root, _, _, cx| {
                            let this = &mut root.review;
                            this.notifications.toggle_open();
                            cx.notify();
                        })),
                    ),
            )
            .when(
                self.sidebar_search_open || !view.filter.search.is_empty(),
                |sidebar| {
                    sidebar.child(
                        ui::text_field(colors.selected, colors.border)
                            .mx(px(ui::CELL_INSET))
                            .mb(px(ui::GAP_GROUP))
                            .child(Input::new(&self.query)),
                    )
                },
            )
            .child(
                div()
                    .px(px(ui::CELL_INSET))
                    .flex_none()
                    .flex()
                    .flex_col()
                    .child(
                        sidebar_nav_button(
                            "open-pr-creation".into(),
                            "New pull request",
                            false,
                            colors,
                        )
                        .on_click(cx.listener(|root, _, window, cx| {
                            let this = &mut root.review;
                            this.open_creation_dialog(window, cx);
                        })),
                    )
                    .children(filters)
                    .child(
                        // The filters above narrow the working set, which is
                        // open pull requests. This leaves it, which is why it
                        // sits after them rather than reading as a fifth.
                        sidebar_nav_button(
                            "open-pr-browser".into(),
                            "Browse all pull requests",
                            self.browser_active,
                            colors,
                        )
                        .on_click(cx.listener(|root, _, _, cx| {
                            let this = &mut root.review;
                            this.open_pr_browser(None, cx);
                        })),
                    ),
            )
            .when(self.workspace.views.len() > 1, |sidebar| {
                sidebar.child(
                    div()
                        .px(px(ui::CELL_INSET))
                        .pt(px(ui::GAP_PAGE))
                        .flex()
                        .flex_col()
                        .child(
                            div()
                                .px(px(ui::CELL_INSET))
                                .pb(px(ui::GAP_GROUP))
                                .text_color(colors.faint)
                                .child("Saved views"),
                        )
                        .children(saved_views),
                )
            })
            .child(
                div()
                    .px(px(ui::CONTROL_INSET))
                    .pt(px(ui::GAP_PAGE))
                    .pb(px(ui::GAP_ICON))
                    .flex_none()
                    .flex()
                    .items_center()
                    .gap(px(ui::GAP_ICON))
                    .child(
                        div()
                            .pl(px(ui::GAP_ICON))
                            .flex_1()
                            .text_color(colors.muted)
                            .child("Repositories"),
                    )
                    .child(
                        sidebar_icon_button(
                            "edit-view",
                            "Edit filters and grouping",
                            "more",
                            colors,
                        )
                        .on_click(cx.listener(|root, _, window, cx| {
                            let this = &mut root.review;
                            this.open_view_editor(window, cx);
                        })),
                    )
                    .child(
                        // The fallback glyph is already a branch-and-merge
                        // shape, which is exactly what this opens.
                        sidebar_icon_button("open-history", "Commit history", "graph", colors)
                            .on_click(cx.listener(|root, _, _, cx| {
                                let this = &mut root.review;
                                this.open_history(None, cx);
                            })),
                    )
                    .child(
                        sidebar_icon_button("add-repository", "Add repository", "plus", colors)
                            .on_click(cx.listener(|root, _, window, cx| {
                                let this = &mut root.review;
                                this.open_repository_picker(window, cx);
                            })),
                    ),
            )
            .when(
                view.groups != vec![GroupBy::Repository]
                    || !matches!(view.filter.state.as_str(), "" | "open"),
                |sidebar| {
                    sidebar.child(
                        div()
                            .px(px(ui::PANEL_GUTTER))
                            .pb(px(ui::GAP_GROUP))
                            .ui_text(TextRole::Caption)
                            .text_color(colors.muted)
                            .child(view_summary(&view)),
                    )
                },
            )
            .when(participating_incomplete, |sidebar| {
                sidebar.child(
                    div()
                        .px(px(ui::PANEL_GUTTER))
                        .pb(px(ui::GAP_GROUP))
                        .ui_text(TextRole::Caption)
                        .text_color(colors.amber)
                        .child("Some participant information is unavailable."),
                )
            })
            .child(
                div()
                    .flex_1()
                    .min_h_0()
                    .flex()
                    .flex_col()
                    .when(!sidebar_rows.is_empty(), |panel| {
                        let root = cx.entity();
                        panel.child(
                            div()
                                .flex_1()
                                .min_h_0()
                                .relative()
                                .child(
                                    uniform_list(
                                        "sidebar-scroll",
                                        sidebar_rows.len(),
                                        move |range: Range<usize>, _, cx| {
                                            root.read_with(cx, |workspace, _| {
                                                let this = &workspace.review;
                                                range
                                                    .map(|index| {
                                                        this.render_sidebar_row(
                                                            &sidebar_rows[index],
                                                            colors,
                                                            root.clone(),
                                                        )
                                                    })
                                                    .collect::<Vec<_>>()
                                            })
                                        },
                                    )
                                    .track_scroll(&self.sidebar_scroll)
                                    .h_full()
                                    .w_full(),
                                )
                                .child(
                                    div().absolute().inset_0().child(
                                        Scrollbar::vertical(&self.sidebar_scroll)
                                            .id("sidebar-scrollbar")
                                            .viewport_from_layout(),
                                    ),
                                ),
                        )
                    })
                    .children(rows),
            )
            .child(
                // The account footer is where a person looks for their own
                // settings, so it is the control that opens them rather than a
                // label sitting next to one.
                Button::new("open-settings")
                    .debug_selector(|| "open-settings".into())
                    .h(px(48.))
                    .px(px(ui::PANEL_GUTTER))
                    .flex_none()
                    .flex()
                    .items_center()
                    .gap(px(ui::GAP_GROUP))
                    .cursor_pointer()
                    .border_1()
                    .border_color(rgba(0x00000000))
                    .focus_ring(colors.accent, colors.selected)
                    .hover(|footer| footer.bg(colors.selected))
                    .accessibility_label(format!("Settings, signed in as {account_label}"))
                    .child(
                        div()
                            .size(px(22.))
                            .flex_none()
                            .rounded_full()
                            .flex()
                            .items_center()
                            .justify_center()
                            .bg(rgba(0x9165b5ff))
                            .text_color(rgba(0xffffffff))
                            .ui_text(TextRole::Caption)
                            .font_weight(ui::WEIGHT_EMPHASIS)
                            .child(initial),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .flex_1()
                            .overflow_hidden()
                            .text_ellipsis()
                            .text_color(colors.muted)
                            .child(account_label.to_owned()),
                    )
                    .on_click(cx.listener(|root, _, _, cx| {
                        let this = &mut root.review;
                        this.open_settings(cx);
                    })),
            )
    }

    fn render_view_editor(&self, colors: Palette, cx: &mut Context<Root>) -> impl IntoElement {
        let draft = self.view_editor.draft().cloned().unwrap_or_default();
        let prefix = ViewEditorInputs::value(&self.view_inputs.source_prefix, cx);
        let groups = draft
            .groups
            .iter()
            .enumerate()
            .map(|(index, group)| {
                let is_source = matches!(group, GroupBy::SourceBranch | GroupBy::SourcePrefix(_));
                let uses_prefix = matches!(group, GroupBy::SourcePrefix(_));
                div()
                    .id(SharedString::from(format!("view-group-{index}")))
                    .py(px(ui::GAP_GROUP))
                    .border_b_1()
                    .border_color(colors.border)
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap(px(ui::GAP_GROUP))
                            .child(
                                div()
                                    .w(px(22.))
                                    .ui_text(TextRole::Caption)
                                    .text_color(colors.faint)
                                    .child(format!("{}", index + 1)),
                            )
                            .child(
                                div()
                                    .flex_1()
                                    .min_w_0()
                                    .overflow_hidden()
                                    .text_ellipsis()
                                    .ui_text(TextRole::Label)
                                    .child(group_label(Some(group))),
                            )
                            .child(
                                small_action(
                                    SharedString::from(format!("change-view-group-{index}")),
                                    "Change",
                                    "Change grouping level",
                                    colors,
                                )
                                .on_click(cx.listener(
                                    move |root, _, _, cx| {
                                        let this = &mut root.review;
                                        let prefix = ViewEditorInputs::value(
                                            &this.view_inputs.source_prefix,
                                            cx,
                                        );
                                        this.view_editor.cycle_group(index, &prefix);
                                        cx.notify();
                                    },
                                )),
                            )
                            .child(
                                small_action(
                                    SharedString::from(format!("move-up-view-group-{index}")),
                                    "↑",
                                    "Move grouping level up",
                                    colors,
                                )
                                .on_click(cx.listener(
                                    move |root, _, _, cx| {
                                        let this = &mut root.review;
                                        this.view_editor.move_group(index, -1);
                                        cx.notify();
                                    },
                                )),
                            )
                            .child(
                                small_action(
                                    SharedString::from(format!("move-down-view-group-{index}")),
                                    "↓",
                                    "Move grouping level down",
                                    colors,
                                )
                                .on_click(cx.listener(
                                    move |root, _, _, cx| {
                                        let this = &mut root.review;
                                        this.view_editor.move_group(index, 1);
                                        cx.notify();
                                    },
                                )),
                            )
                            .child(
                                small_action(
                                    SharedString::from(format!("remove-view-group-{index}")),
                                    "Remove",
                                    "Remove grouping level",
                                    colors,
                                )
                                .on_click(cx.listener(
                                    move |root, _, _, cx| {
                                        let this = &mut root.review;
                                        this.view_editor.remove_group(index);
                                        cx.notify();
                                    },
                                )),
                            ),
                    )
                    .when(is_source, |row| {
                        row.child(
                            div()
                                .ml(px(30.))
                                .mt(px(ui::GAP_GROUP))
                                .flex()
                                .items_center()
                                .gap(px(ui::GAP_GROUP))
                                .child(
                                    side_control("Exact", !uses_prefix, colors)
                                        .id(SharedString::from(format!(
                                            "source-group-exact-{index}"
                                        )))
                                        .on_click(cx.listener(move |root, _, _, cx| {
                                            let this = &mut root.review;
                                            this.view_editor.set_source_group_prefix(index, None);
                                            cx.notify();
                                        })),
                                )
                                .child(
                                    side_control("Prefix", uses_prefix, colors)
                                        .id(SharedString::from(format!(
                                            "source-group-prefix-{index}"
                                        )))
                                        .on_click(cx.listener(move |root, _, _, cx| {
                                            let this = &mut root.review;
                                            let prefix = ViewEditorInputs::value(
                                                &this.view_inputs.source_prefix,
                                                cx,
                                            );
                                            this.view_editor
                                                .set_source_group_prefix(index, Some(&prefix));
                                            cx.notify();
                                        })),
                                )
                                .child(
                                    layout::text_field(colors)
                                        .flex_1()
                                        .child(Input::new(&self.view_inputs.source_prefix)),
                                ),
                        )
                    })
            })
            .collect::<Vec<_>>();

        let state = if draft.filter.state.is_empty() {
            "open"
        } else {
            draft.filter.state.as_str()
        };
        div()
            .absolute()
            .inset_0()
            .flex()
            .items_center()
            .justify_center()
            .p(px(ui::PANEL_GUTTER))
            .bg(rgba(0x00000066))
            .child(
                div()
                    .id("view-editor")
                    .w(px(760.))
                    .max_h_full()
                    .flex()
                    .flex_col()
                    .rounded(px(ui::WINDOW_RADIUS))
                    .border_1()
                    .border_color(colors.border)
                    .bg(colors.surface)
                    .shadow_lg()
                    .child(
                        div()
                            .px(px(ui::PANEL_GUTTER))
                            .py(px(ui::PANEL_GUTTER))
                            .border_b_1()
                            .border_color(colors.border)
                            .flex()
                            .flex_col()
                            .gap(px(ui::GAP_ICON))
                            .child(
                                div()
                                    .ui_text(TextRole::Title)
                                    .font_weight(ui::WEIGHT_EMPHASIS)
                                    .child("Edit sidebar view"),
                            )
                            .child(
                                div()
                                    .ui_text(TextRole::Caption)
                                    .text_color(colors.muted)
                                    .child(
                                        "Changes stay in this editor until you apply or save them.",
                                    ),
                            ),
                    )
                    .child(
                        div()
                            .id("view-editor-scroll")
                            .track_scroll(&self.view_editor_scroll)
                            .flex_1()
                            .min_h_0()
                            .overflow_y_scroll()
                            .px(px(ui::PANEL_GUTTER))
                            .py(px(ui::PANEL_GUTTER))
                            .flex()
                            .flex_col()
                            .gap(px(ui::GAP_COLUMNS))
                            .child(editor_field("View name", &self.view_inputs.name, colors))
                            .child(section_label("FILTERS", colors))
                            .child(
                                div()
                                    .flex()
                                    .gap(px(ui::GAP_COLUMNS))
                                    .child(editor_field("Search", &self.view_inputs.search, colors))
                                    .child(editor_field(
                                        "Author",
                                        &self.view_inputs.author,
                                        colors,
                                    )),
                            )
                            .child(
                                div()
                                    .flex()
                                    .gap(px(ui::GAP_COLUMNS))
                                    .child(editor_field(
                                        "Requested reviewer",
                                        &self.view_inputs.reviewer,
                                        colors,
                                    ))
                                    .child(editor_field(
                                        "Assignee",
                                        &self.view_inputs.assignee,
                                        colors,
                                    )),
                            )
                            .child(
                                div()
                                    .flex()
                                    .gap(px(ui::GAP_COLUMNS))
                                    .child(editor_field("Label", &self.view_inputs.label, colors))
                                    .child(editor_field(
                                        "Review status",
                                        &self.view_inputs.review_status,
                                        colors,
                                    )),
                            )
                            .child(
                                div()
                                    .flex()
                                    .gap(px(ui::GAP_COLUMNS))
                                    .child(editor_field(
                                        "Checks",
                                        &self.view_inputs.check_status,
                                        colors,
                                    ))
                                    .child(editor_field(
                                        "Target branch",
                                        &self.view_inputs.target_branch,
                                        colors,
                                    )),
                            )
                            .child(editor_field(
                                "Exact source branch",
                                &self.view_inputs.source_branch,
                                colors,
                            ))
                            .child(choice_row(
                                "Pull request state",
                                &[
                                    ("Open", state.eq_ignore_ascii_case("open")),
                                    ("Closed", state.eq_ignore_ascii_case("closed")),
                                    ("Merged", state.eq_ignore_ascii_case("merged")),
                                    ("All", state.eq_ignore_ascii_case("all")),
                                ],
                                colors,
                                cx,
                                |this, index| {
                                    this.view_editor
                                        .set_pr_state(["open", "closed", "merged", "all"][index]);
                                },
                            ))
                            .child(choice_row(
                                "Draft status",
                                &[
                                    ("All", draft.filter.draft.is_none()),
                                    ("Draft", draft.filter.draft == Some(true)),
                                    ("Ready", draft.filter.draft == Some(false)),
                                ],
                                colors,
                                cx,
                                |this, index| {
                                    this.view_editor
                                        .set_draft_state([None, Some(true), Some(false)][index]);
                                },
                            ))
                            .child(choice_row(
                                "Relationship",
                                &[
                                    ("All", draft.filter.personal == PersonalFilter::All),
                                    (
                                        "Needs review",
                                        draft.filter.personal == PersonalFilter::ReviewRequested,
                                    ),
                                    ("Mine", draft.filter.personal == PersonalFilter::Own),
                                    (
                                        "Participating",
                                        draft.filter.personal == PersonalFilter::Participating,
                                    ),
                                ],
                                colors,
                                cx,
                                |this, index| {
                                    this.view_editor.set_personal(
                                        [
                                            PersonalFilter::All,
                                            PersonalFilter::ReviewRequested,
                                            PersonalFilter::Own,
                                            PersonalFilter::Participating,
                                        ][index]
                                            .clone(),
                                    );
                                },
                            ))
                            .child(section_label("GROUPING ORDER", colors))
                            .children(groups)
                            .child(
                                small_action(
                                    "add-view-group",
                                    "＋ Add grouping level",
                                    "Add grouping level",
                                    colors,
                                )
                                .on_click(cx.listener(
                                    |root, _, _, cx| {
                                        let this = &mut root.review;
                                        this.view_editor.add_group();
                                        cx.notify();
                                    },
                                )),
                            )
                            .child(
                                div()
                                    .ui_text(TextRole::Caption)
                                    .text_color(colors.muted)
                                    .child(format!(
                                        "Source prefix preview: {}",
                                        if prefix.is_empty() {
                                            "not set"
                                        } else {
                                            &prefix
                                        }
                                    )),
                            ),
                    )
                    .child(
                        div()
                            .px(px(ui::PANEL_GUTTER))
                            .py(px(ui::GAP_COLUMNS))
                            .flex()
                            .items_center()
                            .justify_between()
                            .border_t_1()
                            .border_color(colors.border)
                            .child(
                                modal_button("delete-view", "Delete view", false, colors).on_click(
                                    cx.listener(|root, _, window, cx| {
                                        let this = &mut root.review;
                                        this.delete_current_view(window, cx);
                                    }),
                                ),
                            )
                            .child(
                                div()
                                    .flex()
                                    .gap(px(ui::GAP_GROUP))
                                    .child(
                                        modal_button("cancel-view-editor", "Cancel", false, colors)
                                            .on_click(cx.listener(|root, _, window, cx| {
                                                let this = &mut root.review;
                                                this.cancel_view_editor(window, cx);
                                            })),
                                    )
                                    .child(
                                        modal_button("save-new-view", "Save as new", false, colors)
                                            .on_click(cx.listener(|root, _, window, cx| {
                                                let this = &mut root.review;
                                                this.commit_view_editor(true, window, cx);
                                            })),
                                    )
                                    .child(
                                        modal_button(
                                            "apply-view-editor",
                                            "Apply  ⌘S",
                                            true,
                                            colors,
                                        )
                                        .on_click(
                                            cx.listener(|root, _, window, cx| {
                                                let this = &mut root.review;
                                                this.commit_view_editor(false, window, cx);
                                            }),
                                        ),
                                    ),
                            ),
                    ),
            )
    }

    fn render_main(
        &self,
        colors: Palette,
        window: &Window,
        cx: &mut Context<Root>,
    ) -> impl IntoElement {
        // Idempotent, and the sidebar asks the same question, so neither has to
        // run first for both to agree.
        let glass = glass::sync_window(window, self.window_material());
        div()
            .flex_1()
            .min_w_0()
            .h_full()
            .flex()
            .flex_col()
            // Nothing here paints over the window material except the frame
            // below, so the sidebar, this margin, the tab strip and the status
            // line are all one surface, as in the reference design.
            .when(!glass, |main| main.bg(colors.canvas))
            .child(self.render_tabs(colors, glass, cx))
            .child(
                // One container holds the whole main section, inset so the
                // canvas frames it on every side. The tab strip above and the
                // status line below sit on that canvas rather than inside the
                // frame, which is what gives the content a top and bottom edge
                // instead of letting it run into the window. Everything within
                // shares this one fill; structure comes from hairlines, never
                // from a second tone.
                //
                // This is a flex row, so every screen below sets `min_w_0`.
                // Without it a screen's automatic minimum size is its
                // content's, and narrowing the window stops narrowing the
                // screen: it keeps its width and paints its right-hand side
                // past the frame, where this `overflow_hidden` clips it and the
                // pointer can no longer reach it.
                div()
                    .flex_1()
                    .min_h_0()
                    .flex()
                    .mx(px(ui::GAP_GROUP))
                    .mb(px(ui::GAP_GROUP))
                    .overflow_hidden()
                    .rounded(px(ui::WINDOW_RADIUS))
                    // A content mask in this GPUI is a plain rectangle, so a
                    // rounded container cannot clip what it holds: anything that
                    // reaches the bottom edge paints straight over the two corner
                    // arcs and squares them off. Keeping the arcs' own band clear
                    // is what lets the radius survive contact with a scrolled list.
                    .pb(px(ui::WINDOW_RADIUS))
                    .border_1()
                    .border_color(colors.border)
                    .bg(colors.surface)
                    .child(if self.settings_active {
                        self.render_settings(colors, cx).into_any_element()
                    } else if self.history_active {
                        self.render_history(colors, window, cx).into_any_element()
                    } else if self.browser_active {
                        self.render_pr_browser(colors, cx).into_any_element()
                    } else if self.setup_open {
                        self.render_setup(colors, cx).into_any_element()
                    } else if let Some(index) = self.active_tab {
                        self.render_review(index, colors, window, cx)
                            .into_any_element()
                    } else {
                        self.render_empty(colors, cx).into_any_element()
                    }),
            )
            .child(self.render_status(colors, glass))
    }

    fn render_tabs(
        &self,
        colors: Palette,
        glass: bool,
        cx: &mut Context<Root>,
    ) -> impl IntoElement {
        let tabs = self.tabs.iter().enumerate().map(|(index, tab)| {
            let active = self.active_tab == Some(index);
            let id = SharedString::from(format!("tab-{index}"));
            let close_id = SharedString::from(format!("close-tab-{index}"));
            let close_label = format!("Close {} #{}", tab.repository.name, tab.pull_request.number);
            // Open PRs read as rounded chips on the canvas. Dividers between
            // them and a rule under the strip would repeat what the active
            // chip's own fill already says. The chip is painted at control
            // height inside a full-strip target, so the pointer area does not
            // shrink with it.
            div()
                .id(id.clone())
                .debug_selector({
                    let id = id.clone();
                    move || id.to_string()
                })
                .group(id.clone())
                .h_full()
                .flex_none()
                .flex()
                .items_center()
                .cursor_pointer()
                .child(
                    div()
                        .h(px(ui::CONTROL_HEIGHT))
                        .pl(px(ui::CONTROL_INSET))
                        // The close target carries its own inset, so the chip
                        // keeps an optical right edge without doubling it.
                        .pr(px(ui::GAP_ICON))
                        .flex()
                        .items_center()
                        .gap(px(ui::GAP_ICON))
                        .rounded(px(ui::CONTROL_RADIUS))
                        .text_color(if active { colors.text } else { colors.muted })
                        .when(active, |tab| tab.bg(colors.surface))
                        .when(!active, |tab| {
                            tab.group_hover(id, |tab| tab.bg(colors.selected))
                        })
                        .child(
                            div()
                                .max_w(px(220.))
                                .overflow_hidden()
                                .text_ellipsis()
                                .child(format!(
                                    "{}  #{}",
                                    tab.repository.name, tab.pull_request.number
                                )),
                        )
                        .child(
                            // The close affordance stays painted rather than
                            // hover-revealed: a hidden target still answers the
                            // pointer, and a tab has to be closable by pointer
                            // without first being read.
                            Button::new(close_id.clone())
                                .debug_selector({
                                    let close_id = close_id.clone();
                                    move || close_id.to_string()
                                })
                                .group(close_id.clone())
                                .size(px(ui::BADGE_HEIGHT))
                                .flex_none()
                                .p_0()
                                .rounded(px(ui::BADGE_RADIUS))
                                .border_1()
                                .border_color(rgba(0x00000000))
                                .focus_ring(colors.accent, colors.selected)
                                .cursor_pointer()
                                .hover(|close| close.bg(colors.elevated))
                                .accessibility_label(close_label)
                                .child(
                                    sidebar_icon(
                                        "close",
                                        if active { colors.muted } else { colors.faint },
                                    )
                                    .size(px(ui::ICON_SIZE - 2.))
                                    .group_hover(close_id, |icon| icon.text_color(colors.text)),
                                )
                                // The chip behind this target activates the tab.
                                // Without stopping the press, closing a tab would
                                // also select it on the way out.
                                .on_mouse_down(MouseButton::Left, |_, _, cx| {
                                    cx.stop_propagation();
                                })
                                .on_click(cx.listener(move |root, _, window, cx| {
                                    let this = &mut root.review;
                                    this.close_tab_at(index, window, cx);
                                })),
                        ),
                )
                .on_click(cx.listener(move |root, _, window, cx| {
                    let this = &mut root.review;
                    this.activate_tab(index, window, cx);
                }))
        });
        let settings_active = self.settings_active;
        let history_active = self.history_active;
        let browser_active = self.browser_active;
        div()
            .id("tab-strip")
            .debug_selector(|| "tab-strip".to_owned())
            .h(px(ui::DESKTOP_HIT))
            // Keep the scroll viewport beyond the macOS window controls;
            // padding inside it would let scrolled tabs pass beneath them.
            .when(self.panel_layout.sidebar_collapsed, |strip| {
                strip.ml(px(WINDOW_CONTROLS_INSET - COLLAPSED_PANEL_WIDTH))
            })
            .px(px(ui::GAP_FIELD))
            .flex()
            .items_center()
            .gap(px(ui::GAP_ICON))
            // Tabs keep their own width rather than shrinking towards
            // illegibility, so once they outrun the strip the strip scrolls.
            // `activate_tab` reveals whatever it selected, which is what keeps
            // the keyboard and the close shortcut usable past the edge.
            .min_w_0()
            .overflow_x_scroll()
            .restrict_scroll_to_axis()
            .track_scroll(&self.tab_strip_scroll)
            .when(!glass, |strip| strip.bg(colors.canvas))
            .children(tabs)
            // Settings and History keep chips of their own rather than
            // replacing the open pull requests. Both are places you go back and
            // forth from while reading a pull request — Settings because its
            // choices change how the window looks, which can only be judged by
            // returning to real content, and History because it is the other
            // half of the question a diff is asking.
            .when(self.settings_open, |strip| {
                strip.child(utility_tab(
                    "settings",
                    "Settings",
                    settings_active,
                    colors,
                    cx,
                    |this, cx| this.open_settings(cx),
                    |this, cx| this.close_settings(cx),
                ))
            })
            .when(self.history_open, |strip| {
                strip.child(utility_tab(
                    "history",
                    "History",
                    history_active,
                    colors,
                    cx,
                    |this, cx| this.open_history(None, cx),
                    |this, cx| this.close_history(cx),
                ))
            })
            .when(self.browser_open, |strip| {
                strip.child(utility_tab(
                    "browser",
                    "Pull requests",
                    browser_active,
                    colors,
                    cx,
                    |this, cx| this.open_pr_browser(None, cx),
                    |this, cx| this.close_pr_browser(cx),
                ))
            })
    }

    /// The repository a page opens against: the active pull request's, else the
    /// first one configured. This is the same resolution the sidebar's account
    /// footer uses, so a page opens on what the window is already about.
    fn default_page_repository(&self) -> Option<Repository> {
        self.active_tab
            .and_then(|index| self.tabs.get(index))
            .map(|tab| tab.repository.clone())
            .or_else(|| {
                self.repositories
                    .first()
                    .map(|runtime| runtime.repository.clone())
            })
    }

    /// History opens as a page in the tab strip rather than as a sheet, for the
    /// same reason Settings does: it is a place you go back and forth from
    /// while reading a pull request, not something to dismiss before working.
    fn open_history(&mut self, repository: Option<Repository>, cx: &mut Context<Root>) {
        let Some(repository) = repository.or_else(|| self.default_page_repository()) else {
            self.status = "Add a repository before opening its history.".into();
            cx.notify();
            return;
        };
        self.record_user_navigation();
        let key = repository.cache_key();
        let account = repository.account.clone();
        let fresh = match self.history.as_mut() {
            Some(history) => history.retarget(key.clone(), account.clone()),
            None => {
                self.history = Some(HistoryController::new(key.clone(), account.clone()));
                true
            }
        };
        self.history_open = true;
        self.history_active = true;
        self.settings_active = false;
        self.setup_open = false;
        self.command_palette = false;
        if fresh {
            self.load_history(cx);
        }
        cx.notify();
    }

    fn close_history(&mut self, cx: &mut Context<Root>) {
        self.history_open = false;
        self.history_active = false;
        // Dropping the controller releases the loaded commits and the diff
        // rows with them; reopening reads afresh rather than showing a history
        // that has since moved.
        self.history = None;
        self.setup_open =
            !self.settings_active && self.tabs.is_empty() && self.startup_pr.is_none();
        cx.notify();
    }

    /// The pull-request index opens as a page in the tab strip for the same
    /// reason History does: it is a place you go back and forth from while
    /// reading a pull request, not something to dismiss before working.
    fn open_pr_browser(&mut self, repository: Option<Repository>, cx: &mut Context<Root>) {
        let Some(repository) = repository.or_else(|| self.default_page_repository()) else {
            self.status = "Add a repository before browsing its pull requests.".into();
            cx.notify();
            return;
        };
        self.record_user_navigation();
        let key = repository.cache_key();
        let account = repository.account.clone();
        let fresh = match self.browser.as_mut() {
            Some(browser) => browser.retarget(key.clone(), account.clone()),
            None => {
                self.browser = Some(pr_browser::PullRequestBrowser::new(key, account));
                true
            }
        };
        self.browser_open = true;
        self.browser_active = true;
        self.settings_active = false;
        self.history_active = false;
        self.setup_open = false;
        self.command_palette = false;
        // A new controller starts with no filter while the box keeps whatever
        // was typed into it. Adopting the visible text is what keeps the two
        // from disagreeing about which rows the reader asked for.
        self.apply_pr_browser_filter(cx);
        if fresh {
            self.browser_scroll.scroll_to_item(0, ScrollStrategy::Top);
            self.load_pr_browser(false, cx);
        }
        cx.notify();
    }

    fn close_pr_browser(&mut self, cx: &mut Context<Root>) {
        self.browser_open = false;
        self.browser_active = false;
        // Dropping the controller drops its loaded pages; reopening reads
        // afresh rather than showing an index that stopped being true while
        // the page was closed.
        self.browser = None;
        self.setup_open = !self.settings_active
            && !self.history_active
            && self.tabs.is_empty()
            && self.startup_pr.is_none();
        cx.notify();
    }

    fn browser_repository_index(&self) -> Option<usize> {
        let key = self.browser.as_ref()?.repository_key();
        self.repositories
            .iter()
            .position(|runtime| runtime.repository.cache_key() == key)
    }

    fn browser_repository(&self) -> Option<Repository> {
        let index = self.browser_repository_index()?;
        Some(self.repositories[index].repository.clone())
    }

    /// Read one page of the index.
    ///
    /// This deliberately does not pass through `read_sync::GeneralReadController`.
    /// That admission serializes the polled reads keeping the sidebar and the
    /// open tabs fresh, and refusing a Load more press with `ReadDeferral::Busy`
    /// behind a sidebar poll would make the control look broken. A page here is
    /// explicit, bounded to one request, read-only, and only ever happens
    /// because someone asked for it.
    fn load_pr_browser(&mut self, append: bool, cx: &mut Context<Root>) {
        let Some(repository) = self.browser_repository() else {
            if let Some(browser) = self.browser.as_mut() {
                browser.fail("This repository is no longer configured.".into());
            }
            cx.notify();
            return;
        };
        let Some(browser) = self.browser.as_mut() else {
            return;
        };
        if append && (!browser.has_more || browser.appending) {
            return;
        }
        let token = browser.begin_read(append);
        let state = token.state().query();
        let page = token.page();
        let task = cx.background_spawn(async move {
            GithubProvider::new(repository.account.clone())
                .list_pull_request_summaries(&repository, state, page)
                .map_err(|error| format!("{error:#}"))
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let Some(browser) = this.browser.as_mut().filter(|it| it.accepts(&token)) else {
                    return;
                };
                match result {
                    Ok(page) => browser.install(page),
                    Err(error) => browser.fail(format!("Pull requests unavailable: {error}")),
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn set_pr_browser_state(&mut self, state: pr_browser::BrowseState, cx: &mut Context<Root>) {
        let changed = self
            .browser
            .as_mut()
            .is_some_and(|browser| browser.set_state(state));
        if changed {
            self.browser_scroll.scroll_to_item(0, ScrollStrategy::Top);
            self.load_pr_browser(false, cx);
        }
        cx.notify();
    }

    fn set_pr_browser_repository(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(repository) = self
            .repositories
            .get(index)
            .map(|runtime| runtime.repository.clone())
        else {
            return;
        };
        self.open_pr_browser(Some(repository), cx);
    }

    fn apply_pr_browser_filter(&mut self, cx: &mut Context<Root>) {
        let filter = self.browser_filter_input.read(cx).value().to_string();
        let changed = self
            .browser
            .as_mut()
            .is_some_and(|browser| browser.set_filter(filter));
        if changed {
            self.browser_scroll.scroll_to_item(0, ScrollStrategy::Top);
            cx.notify();
        }
    }

    fn history_repository(&self) -> Option<Repository> {
        let history = self.history.as_ref()?;
        let key = history.repository_key();
        self.repositories
            .iter()
            .map(|runtime| &runtime.repository)
            .chain(self.tabs.iter().map(|tab| &tab.repository))
            .find(|repository| repository.cache_key() == key)
            .cloned()
    }

    /// Read the repository's history. Local when there is a checkout — it is
    /// faster, works offline, and is the only source that can show every
    /// branch at once — and GitHub otherwise.
    fn load_history(&mut self, cx: &mut Context<Root>) {
        let generation = self.issue_request_generation();
        let Some(repository) = self.history_repository() else {
            if let Some(history) = self.history.as_mut() {
                history.fail("This repository is no longer configured.".into());
            }
            cx.notify();
            return;
        };
        let Some(history) = self.history.as_mut() else {
            return;
        };
        #[cfg(feature = "ui-smoke")]
        if self.provider_reads_disabled && repository.local_path.is_none() {
            // A synthetic scene installs its own graph. Reaching the provider
            // here would replace it with a transport failure.
            return;
        }
        let token = history.begin_read(generation);
        let scope = history.scope.clone();
        let task = cx.background_spawn(async move {
            if let Some(path) = repository.local_path.as_deref() {
                return local_history(path, &scope).map_err(|error| format!("{error:#}"));
            }
            GithubProvider::new(repository.account.clone())
                .repository_history(&repository, &scope)
                .map_err(|error| format!("{error:#}"))
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let Some(history) = this.history.as_mut().filter(|it| it.accepts(&token)) else {
                    return;
                };
                match result {
                    Ok(read) => history.install(read),
                    Err(error) => history.fail(format!("History unavailable: {error}")),
                }
                // A history whose selection survived still has its diff; one
                // that lost it has nothing to load.
                if this
                    .history
                    .as_ref()
                    .is_some_and(|history| history.selected.is_some())
                {
                    this.load_commit_diff(cx);
                }
                cx.notify();
            });
        })
        .detach();
        cx.notify();
    }

    fn select_history_commit(&mut self, sha: &str, cx: &mut Context<Root>) {
        let Some(history) = self.history.as_mut() else {
            return;
        };
        if !history.select(sha) {
            return;
        }
        self.load_commit_diff(cx);
        cx.notify();
    }

    fn set_history_scope(&mut self, scope: HistoryScope, cx: &mut Context<Root>) {
        let changed = self
            .history
            .as_mut()
            .is_some_and(|history| history.set_scope(scope));
        if changed {
            self.load_history(cx);
        }
    }

    /// Load the selected commit's changes.
    ///
    /// A commit's diff is the comparison between its first parent and itself,
    /// which is the pair GitHub's own commit page shows for a merge too. A root
    /// commit has no parent, so it is compared against the empty tree and reads
    /// as the addition of everything in it.
    fn load_commit_diff(&mut self, cx: &mut Context<Root>) {
        let generation = self.issue_request_generation();
        let Some(repository) = self.history_repository() else {
            return;
        };
        let Some(history) = self.history.as_mut() else {
            return;
        };
        let Some(commit) = history.selected_commit().cloned() else {
            return;
        };
        #[cfg(feature = "ui-smoke")]
        if self.provider_reads_disabled && repository.local_path.is_none() {
            return;
        }
        let Some(token) = history.begin_diff(generation) else {
            return;
        };
        let task = cx.background_spawn(async move {
            let parent = commit.first_parent().map(str::to_owned);
            match repository.local_path.as_deref() {
                Some(path) => {
                    let base = match parent {
                        Some(parent) => parent,
                        None => empty_tree_oid(path).map_err(|error| format!("{error:#}"))?,
                    };
                    let revision = Revision {
                        base_sha: base,
                        head_sha: commit.sha.clone(),
                    };
                    // The metadata-only enumeration: patches load per file as
                    // they are selected, so opening a thousand-file commit does
                    // not read a thousand patches first.
                    local_inventory(path, &revision).map_err(|error| format!("{error:#}"))
                }
                None => {
                    let parent = parent.ok_or_else(|| {
                        "GitHub cannot compare a root commit against its absent parent. Clone this repository locally to read its first commit."
                            .to_owned()
                    })?;
                    let revision = Revision {
                        base_sha: parent,
                        head_sha: commit.sha.clone(),
                    };
                    GithubProvider::new(repository.account.clone())
                        .direct_comparison(&repository, &revision)
                        .map_err(|error| format!("{error:#}"))
                }
            }
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let wide = this.wide;
                let mode = this.workspace.preferences.reading_mode;
                let Some(history) = this.history.as_mut().filter(|it| it.accepts_diff(&token))
                else {
                    return;
                };
                match result {
                    Ok(comparison) => {
                        history.install_diff(ReviewSession::new(comparison), wide, mode)
                    }
                    Err(error) => {
                        history.fail_diff(format!("This commit's changes are unavailable: {error}"))
                    }
                }
                this.load_selected_history_file(cx);
                cx.notify();
            });
        })
        .detach();
        cx.notify();
    }

    /// Hydrate the selected file's patch, which the enumeration left out.
    /// `full_pr: false` keeps the exact revision pair: this is a commit's own
    /// diff, not a pull request's, so there is no merge-base to rewrite to.
    fn load_selected_history_file(&mut self, cx: &mut Context<Root>) {
        let Some(repository) = self.history_repository() else {
            return;
        };
        let Some(path) = repository.local_path.clone() else {
            return;
        };
        let Some(history) = self.history.as_mut() else {
            return;
        };
        let Some(session) = history.session.as_mut() else {
            return;
        };
        let Some(file) = session.selected_file() else {
            return;
        };
        if file.patch.is_some() {
            return;
        }
        let selected_key = file_key(file);
        let Ok(request) = session.begin_file_patch(&selected_key) else {
            return;
        };
        let revision = request.revision().clone();
        let requested_key = request.file_key().to_owned();
        let task =
            cx.background_spawn(
                async move { load_local_file(&path, &revision, &requested_key, false) },
            );
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let this = &mut root.review;
                let wide = this.wide;
                let mode = this.workspace.preferences.reading_mode;
                let Some(history) = this.history.as_mut() else {
                    return;
                };
                if !history
                    .session
                    .as_ref()
                    .is_some_and(|session| session.accepts_file_patch(&request))
                {
                    return;
                }
                match result {
                    Ok(file) => {
                        let installed = history.session.as_mut().is_some_and(|session| {
                            session.accept_file_patch(&request, file).is_ok()
                        });
                        if installed {
                            history.rebuild(wide, mode);
                        }
                    }
                    Err(error) => {
                        history.feedback =
                            Some(format!("This file's patch is unavailable: {error:#}"));
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    /// Settings open as a page in the tab strip rather than as a sheet. What
    /// they change is the window itself, and a modal covering the window is the
    /// one place from which that cannot be judged.
    fn open_settings(&mut self, cx: &mut Context<Root>) {
        self.record_user_navigation();
        self.settings_open = true;
        self.settings_active = true;
        self.history_active = false;
        self.setup_open = false;
        self.command_palette = false;
        cx.notify();
    }

    fn close_settings(&mut self, cx: &mut Context<Root>) {
        self.settings_open = false;
        self.settings_active = false;
        self.setup_open = !self.history_active && self.tabs.is_empty() && self.startup_pr.is_none();
        cx.notify();
    }

    /// The material is installed on the next render, so the choice shows itself
    /// immediately behind the page that made it.
    fn set_sidebar_material(&mut self, material: SidebarMaterial, cx: &mut Context<Root>) {
        if self.workspace.preferences.sidebar_material == material {
            return;
        }
        self.workspace.preferences.sidebar_material = material;
        self.save_workspace(cx);
        cx.notify();
    }

    /// The History page: one repository's commit graph, and the changes made by
    /// whichever commit is selected.
    fn render_history(&self, colors: Palette, window: &Window, cx: &mut Context<Root>) -> Div {
        let dark = is_dark(window);
        div()
            .flex_1()
            .min_w_0()
            .h_full()
            .flex()
            .flex_col()
            .child(self.render_history_header(colors, cx))
            .child(layout::rule(colors))
            .child(
                // Without `min_w_0` a flex row's minimum is its content's, so
                // narrowing the window would stop narrowing this row and its
                // right-hand side would paint past the frame that clips it.
                div()
                    .flex_1()
                    .min_h_0()
                    .min_w_0()
                    .flex()
                    .child(self.render_history_commits(colors, dark, cx))
                    .child(self.render_splitter(PanelKind::HistoryCommits, colors, window, cx))
                    .child(self.render_history_commit(colors, cx)),
            )
    }

    fn render_history_header(&self, colors: Palette, cx: &mut Context<Root>) -> Div {
        let repository = self.history_repository();
        let title = repository
            .as_ref()
            .map(Repository::full_name)
            .unwrap_or_else(|| "No repository".into());
        let scope = self
            .history
            .as_ref()
            .map(|history| history.scope.clone())
            .unwrap_or(HistoryScope::AllRefs);
        let choices = self
            .history
            .as_ref()
            .map(HistoryController::scope_choices)
            .unwrap_or_default();
        let overflowed = self
            .history
            .as_ref()
            .is_some_and(|history| history.overflowed);
        let notice = self
            .history
            .as_ref()
            .and_then(|history| history.state.notice());
        let error = self
            .history
            .as_ref()
            .is_some_and(|history| matches!(history.state, LoadState::Error(_)));
        // Every repository in the window can be reached from here, so History
        // is not tied to whichever pull request happened to be open.
        let repositories: Vec<_> = self
            .repositories
            .iter()
            .map(|runtime| runtime.repository.clone())
            .collect();
        let current_key = self
            .history
            .as_ref()
            .map(|history| history.repository_key().to_owned());

        div()
            .flex_none()
            .px(px(ui::PANEL_GUTTER))
            .pt(px(ui::GAP_GROUP))
            .flex()
            .flex_col()
            .child(
                div()
                    .h(px(ui::DESKTOP_HIT))
                    .flex()
                    .items_center()
                    .gap(px(ui::GAP_GROUP))
                    .child(
                        div()
                            .ui_text(TextRole::Title)
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .child(title),
                    )
                    .child(div().flex_1())
                    .children(self.render_fold_all_control(colors, cx))
                    .child(
                        Button::new("history-refresh")
                            .debug_selector(|| "history-refresh".to_owned())
                            .control()
                            .bg(colors.elevated)
                            .border_1()
                            .border_color(rgba(0x00000000))
                            .focus_ring(colors.accent, colors.selected)
                            .cursor_pointer()
                            .accessibility_label("Refresh history")
                            .child("Refresh")
                            .on_click(cx.listener(|root, _, _, cx| {
                                let this = &mut root.review;
                                this.load_history(cx);
                            })),
                    ),
            )
            .when(repositories.len() > 1, |header| {
                header.child(layout::chip_row().children(repositories.into_iter().map(
                    |repository| {
                        let key = repository.cache_key();
                        let selected = current_key.as_deref() == Some(key.as_str());
                        layout::chip(
                            "history-repository",
                            &repository.full_name(),
                            None,
                            selected,
                            colors,
                        )
                        .on_click(cx.listener(move |root, _, _, cx| {
                            let this = &mut root.review;
                            this.open_history(Some(repository.clone()), cx);
                        }))
                    },
                )))
            })
            .child(
                layout::chip_row()
                    .child(
                        layout::chip(
                            "history-scope-all",
                            "All branches",
                            None,
                            scope == HistoryScope::AllRefs,
                            colors,
                        )
                        .on_click(cx.listener(|root, _, _, cx| {
                            let this = &mut root.review;
                            this.set_history_scope(HistoryScope::AllRefs, cx);
                        })),
                    )
                    .children(choices.into_iter().map(|name| {
                        let selected = scope == HistoryScope::Ref(name.clone());
                        let chosen = name.clone();
                        layout::chip("history-scope", &name, None, selected, colors).on_click(
                            cx.listener(move |root, _, _, cx| {
                                let this = &mut root.review;
                                this.set_history_scope(HistoryScope::Ref(chosen.clone()), cx);
                            }),
                        )
                    })),
            )
            .when_some(notice, |header, notice| {
                header.child(
                    div()
                        .pb(px(ui::GAP_GROUP))
                        .ui_text(TextRole::Caption)
                        .text_color(if error { colors.red } else { colors.muted })
                        .child(notice),
                )
            })
            .when(overflowed, |header| {
                header.child(
                    div()
                        .pb(px(ui::GAP_GROUP))
                        .ui_text(TextRole::Caption)
                        .text_color(colors.amber)
                        .child(
                            "More branches are active than the graph has columns; \
                             the rightmost ones share a column. Narrow to one branch to \
                             read them apart.",
                        ),
                )
            })
    }

    /// The commit list, with the graph drawn in its gutter.
    fn render_history_commits(&self, colors: Palette, dark: bool, cx: &mut Context<Root>) -> Div {
        let Some(history) = self.history.as_ref() else {
            return div();
        };
        // Pointer copies, not a copy of the history: the list closure is built
        // on every frame and the commits can number five hundred.
        let commits = history.commits().clone();
        let rows = history.rows().clone();
        let lane_count = history.lane_count;
        let selected = history.selected.clone();
        let count = commits.len().min(rows.len());
        let scroll = history.commit_scroll.clone();
        let root = cx.entity();
        let loading = matches!(history.state, LoadState::Loading(_));

        // Collapsed, the column keeps its job and loses its names: one dot per
        // commit in its lane's colour, at the pitch the full rows use, so the
        // position of what you are reading is still on screen and still
        // answers a click.
        if history.commits_collapsed {
            let rail_commits = commits.clone();
            let rail_rows = rows.clone();
            let rail_selected = selected.clone();
            let rail_root = root.clone();
            return div()
                .w(px(COLLAPSED_PANEL_WIDTH))
                .flex_none()
                .h_full()
                .flex()
                .flex_col()
                .border_r_1()
                .border_color(colors.border)
                .child(
                    div()
                        .id("restore-history-commits")
                        .debug_selector(|| "restore-history-commits".to_owned())
                        .h(px(ui::DESKTOP_HIT))
                        .flex_none()
                        .flex()
                        .items_center()
                        .justify_center()
                        .cursor_pointer()
                        .text_color(colors.accent)
                        .aria_label("Show the commit graph")
                        .border_b_1()
                        .border_color(colors.border)
                        .child("\u{203a}")
                        .on_click(cx.listener(|root, _, _, cx| {
                            if let Some(history) = root.review.history.as_mut() {
                                history.commits_collapsed = false;
                            }
                            cx.notify();
                        })),
                )
                .child(
                    uniform_list(
                        "history-commit-rail",
                        count,
                        move |range: Range<usize>, _, _| {
                            range
                                .map(|index| {
                                    let commit = &rail_commits[index];
                                    let row = &rail_rows[index];
                                    let chosen =
                                        rail_selected.as_deref() == Some(commit.sha.as_str());
                                    let sha = commit.sha.clone();
                                    let click_root = rail_root.clone();
                                    let color = lane_color(row.node_color, dark);
                                    div()
                                        .id(SharedString::from(format!("history-rail-{index}")))
                                        .h(px(ui::TWO_LINE_ROW))
                                        .w_full()
                                        .flex()
                                        .items_center()
                                        .justify_center()
                                        .cursor_pointer()
                                        .when(chosen, |row| row.bg(colors.selected))
                                        .when(!chosen, |row| {
                                            row.hover(|row| row.bg(colors.selected))
                                        })
                                        .child(
                                            div()
                                                .size(px(8.))
                                                .rounded(px(4.))
                                                .when(row.merge, |dot| {
                                                    dot.border_1().border_color(color)
                                                })
                                                .when(!row.merge, |dot| dot.bg(color)),
                                        )
                                        .on_click(move |_, _, cx| {
                                            let sha = sha.clone();
                                            click_root.update(cx, |root, cx| {
                                                root.review.select_history_commit(&sha, cx);
                                            });
                                        })
                                })
                                .collect::<Vec<_>>()
                        },
                    )
                    .track_scroll(&history.commit_scroll)
                    .w_full()
                    .flex_1(),
                );
        }

        div()
            .w(px(history.commit_width))
            .min_w(px(MIN_HISTORY_COMMIT_COLUMN))
            .flex_none()
            .h_full()
            .flex()
            .flex_col()
            .border_r_1()
            .border_color(colors.border)
            .child(
                div()
                    .h(px(ui::DESKTOP_HIT))
                    .px(px(ui::CONTROL_INSET))
                    .flex_none()
                    .flex()
                    .items_center()
                    .justify_between()
                    .border_b_1()
                    .border_color(colors.border)
                    .child(format!("Commits  {count}"))
                    .child(
                        div()
                            .id("collapse-history-commits")
                            .debug_selector(|| "collapse-history-commits".to_owned())
                            .cursor_pointer()
                            .text_color(colors.accent)
                            .aria_label("Collapse the commit graph")
                            .child("\u{2039}")
                            .on_click(cx.listener(|root, _, _, cx| {
                                if let Some(history) = root.review.history.as_mut() {
                                    history.commits_collapsed = true;
                                }
                                cx.notify();
                            })),
                    ),
            )
            .child(if count == 0 {
                div()
                    .flex_1()
                    .min_w_0()
                    .overflow_hidden()
                    .flex()
                    .items_center()
                    .justify_center()
                    .px(px(ui::PANEL_GUTTER))
                    .text_center()
                    .text_color(colors.muted)
                    .child(if loading {
                        "Reading this repository's history…"
                    } else {
                        "No commits to show."
                    })
                    .into_any_element()
            } else {
                div()
                    .flex_1()
                    .min_h_0()
                    .relative()
                    .child(
                        uniform_list(
                            "history-commits",
                            count,
                            move |range: Range<usize>, _, _| {
                                range
                                    .map(|index| {
                                        let commit = &commits[index];
                                        let row = &rows[index];
                                        let chosen =
                                            selected.as_deref() == Some(commit.sha.as_str());
                                        let sha = commit.sha.clone();
                                        let click_root = root.clone();
                                        div()
                                            .id(SharedString::from(format!(
                                                "history-commit-{index}"
                                            )))
                                            .debug_selector(move || {
                                                format!("history-commit-{index}")
                                            })
                                            .h(px(ui::TWO_LINE_ROW))
                                            .w_full()
                                            .px(px(ui::CONTROL_INSET))
                                            .flex()
                                            .items_center()
                                            .gap(px(ui::GAP_FIELD))
                                            .cursor_pointer()
                                            .when(chosen, |row| row.bg(colors.selected))
                                            .when(!chosen, |row| {
                                                row.hover(|row| row.bg(colors.selected))
                                            })
                                            .child(history_graph_cell(
                                                row,
                                                lane_count,
                                                ui::TWO_LINE_ROW,
                                                dark,
                                                colors,
                                            ))
                                            .child(
                                                layout::lines()
                                                    .flex_1()
                                                    .min_w_0()
                                                    .child(
                                                        div()
                                                            .flex()
                                                            .items_center()
                                                            .gap(px(ui::GAP_ICON))
                                                            .child(
                                                                div()
                                                                    .min_w_0()
                                                                    .flex_1()
                                                                    .overflow_hidden()
                                                                    .whitespace_nowrap()
                                                                    .text_ellipsis()
                                                                    .text_color(colors.text)
                                                                    .child(
                                                                        commit
                                                                            .message_headline
                                                                            .clone(),
                                                                    ),
                                                            )
                                                            .children(commit.refs.iter().map(
                                                                |label| {
                                                                    history_ref_chip(label, colors)
                                                                },
                                                            )),
                                                    )
                                                    .child(
                                                        div()
                                                            .flex()
                                                            .items_center()
                                                            .gap(px(ui::GAP_FIELD))
                                                            .ui_text(TextRole::Caption)
                                                            .text_color(colors.faint)
                                                            .child(
                                                                div().font_family(CODE_FONT).child(
                                                                    commit.short_sha().to_owned(),
                                                                ),
                                                            )
                                                            .child(
                                                                div()
                                                                    .min_w_0()
                                                                    .overflow_hidden()
                                                                    .whitespace_nowrap()
                                                                    .text_ellipsis()
                                                                    .child(
                                                                        commit.author_name.clone(),
                                                                    ),
                                                            )
                                                            .child(div().child(history_day(
                                                                &commit.authored_at,
                                                            ))),
                                                    ),
                                            )
                                            .on_click(move |_, _, cx| {
                                                let sha = sha.clone();
                                                click_root.update(cx, |root, cx| {
                                                    root.review.select_history_commit(&sha, cx);
                                                });
                                            })
                                    })
                                    .collect::<Vec<_>>()
                            },
                        )
                        .track_scroll(&scroll)
                        .w_full()
                        .h_full(),
                    )
                    .child(
                        div().absolute().inset_0().child(
                            Scrollbar::vertical(&scroll)
                                .id("history-commits-scrollbar")
                                .viewport_from_layout(),
                        ),
                    )
                    .into_any_element()
            })
    }

    /// The selected commit: what it says, who made it, and what it changed.
    fn render_history_commit(&self, colors: Palette, cx: &mut Context<Root>) -> Div {
        let Some(history) = self.history.as_ref() else {
            return div().flex_1().min_w_0();
        };
        let Some(commit) = history.selected_commit() else {
            return div()
                .flex_1()
                .min_w_0()
                .flex()
                .items_center()
                .justify_center()
                .text_color(colors.muted)
                .child("Select a commit to read what it changed.");
        };
        let parents = commit.parent_shas.clone();
        let diff_notice = history.diff_state.notice();
        let diff_error = matches!(history.diff_state, LoadState::Error(_));
        let feedback = history.feedback.clone();

        div()
            .flex_1()
            // What this pane needs is its file list plus a readable diff. With
            // `min_w_0` here instead, flexbox would happily squeeze the pane
            // below that and let its two columns paint over the frame, because
            // a zero minimum says the content has no width of its own.
            .min_w(px(440.))
            .h_full()
            .flex()
            .flex_col()
            .child(
                div()
                    .flex_none()
                    .min_w_0()
                    .px(px(ui::PANEL_GUTTER))
                    .py(px(ui::GAP_GROUP))
                    .flex()
                    .flex_col()
                    .gap(px(ui::GAP_FIELD))
                    .child(
                        div()
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .ui_text(TextRole::Subtitle)
                            .child(commit.message_headline.clone()),
                    )
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .flex_wrap()
                            .gap(px(ui::GAP_FIELD))
                            .ui_text(TextRole::Caption)
                            .text_color(colors.muted)
                            .child(
                                // A full object ID is 40 unbreakable
                                // characters. It shrinks rather than holding
                                // the whole pane open at its own width.
                                div()
                                    .min_w_0()
                                    .overflow_hidden()
                                    .text_ellipsis()
                                    .font_family(CODE_FONT)
                                    .text_color(colors.text)
                                    .child(commit.sha.clone()),
                            )
                            .child(div().child(format!(
                                "{} committed {}",
                                if commit.author_name.is_empty() {
                                    "Someone".to_owned()
                                } else {
                                    commit.author_name.clone()
                                },
                                history_day(&commit.committed_at)
                            )))
                            .when_some(commit.author_login.clone(), |line, login| {
                                line.child(div().child(format!("@{login}")))
                            })
                            .children(
                                commit
                                    .refs
                                    .iter()
                                    .map(|label| history_ref_chip(label, colors)),
                            ),
                    )
                    .child(
                        div()
                            .ui_text(TextRole::Caption)
                            .text_color(colors.faint)
                            .child(match parents.len() {
                                0 => "Root commit · compared against an empty tree".to_owned(),
                                1 => format!("Parent {}", short_sha(&parents[0])),
                                _ => format!(
                                    "Merge · shown against its first parent {} · also {}",
                                    short_sha(&parents[0]),
                                    parents[1..]
                                        .iter()
                                        .map(|parent| short_sha(parent).to_owned())
                                        .collect::<Vec<_>>()
                                        .join(", ")
                                ),
                            }),
                    )
                    .when_some(diff_notice, |block, notice| {
                        block.child(
                            div()
                                .ui_text(TextRole::Caption)
                                .text_color(if diff_error { colors.red } else { colors.muted })
                                .child(notice),
                        )
                    })
                    .when_some(feedback, |block, feedback| {
                        block.child(
                            div()
                                .ui_text(TextRole::Caption)
                                .text_color(colors.amber)
                                .child(feedback),
                        )
                    }),
            )
            .child(layout::rule(colors))
            .child(
                div()
                    .flex_1()
                    .min_h_0()
                    .min_w_0()
                    .flex()
                    .child(self.render_history_files(colors, cx))
                    .child(self.render_history_diff(colors, cx)),
            )
    }

    fn render_history_files(&self, colors: Palette, cx: &mut Context<Root>) -> Div {
        let Some(history) = self.history.as_ref() else {
            return div();
        };
        let comparison = history
            .session
            .as_ref()
            .map(ReviewSession::shared_comparison);
        let selected = history
            .session
            .as_ref()
            .and_then(ReviewSession::selected_file)
            .map(file_key);
        let count = comparison
            .as_ref()
            .map_or(0, |comparison| comparison.files.len());
        let scroll = history.file_scroll.clone();
        let root = cx.entity();
        div()
            .w(px(220.))
            .min_w(px(160.))
            .h_full()
            .flex()
            .flex_col()
            .border_r_1()
            .border_color(colors.border)
            .child(
                div()
                    .h(px(ui::DESKTOP_HIT))
                    .px(px(ui::CONTROL_INSET))
                    .flex_none()
                    .flex()
                    .items_center()
                    .border_b_1()
                    .border_color(colors.border)
                    .child(format!("Changed files  {count}")),
            )
            .child(
                div()
                    .flex_1()
                    .min_h_0()
                    .relative()
                    .child(
                        uniform_list("history-files", count, move |range: Range<usize>, _, _| {
                            let Some(comparison) = comparison.as_ref() else {
                                return Vec::new();
                            };
                            range
                                .map(|row| {
                                    let file = &comparison.files[row];
                                    let key = file_key(file);
                                    let click_key = key.clone();
                                    let click_root = root.clone();
                                    div()
                                        .id(SharedString::from(format!("history-file-{row}")))
                                        .debug_selector(move || format!("history-file-{row}"))
                                        .h(px(ui::TWO_LINE_ROW))
                                        .px(px(ui::CONTROL_INSET))
                                        .flex()
                                        .flex_col()
                                        .justify_center()
                                        .gap(px(ui::GAP_ICON))
                                        .cursor_pointer()
                                        .when(selected.as_deref() == Some(key.as_str()), |row| {
                                            row.bg(colors.selected)
                                        })
                                        .child(
                                            div()
                                                .overflow_hidden()
                                                .whitespace_nowrap()
                                                .text_ellipsis()
                                                .child(file.path.clone()),
                                        )
                                        .child(
                                            div()
                                                .ui_text(TextRole::Caption)
                                                .text_color(if file.patch.is_some() {
                                                    colors.muted
                                                } else {
                                                    colors.faint
                                                })
                                                .child(if file.patch.is_some() {
                                                    format!(
                                                        "+{} −{}",
                                                        file.additions, file.deletions
                                                    )
                                                } else {
                                                    "Metadata only · select to load".into()
                                                }),
                                        )
                                        .on_click(move |_, _, cx| {
                                            let click_key = click_key.clone();
                                            click_root.update(cx, |root, cx| {
                                                let this = &mut root.review;
                                                let wide = this.wide;
                                                let mode = this.workspace.preferences.reading_mode;
                                                let changed =
                                                    this.history.as_mut().is_some_and(|history| {
                                                        history.select_file(&click_key, wide, mode)
                                                    });
                                                if changed {
                                                    this.load_selected_history_file(cx);
                                                    cx.notify();
                                                }
                                            });
                                        })
                                })
                                .collect::<Vec<_>>()
                        })
                        .track_scroll(&scroll)
                        .w_full()
                        .h_full(),
                    )
                    .child(
                        div().absolute().inset_0().child(
                            Scrollbar::vertical(&scroll)
                                .id("history-files-scrollbar")
                                .viewport_from_layout(),
                        ),
                    ),
            )
    }

    /// The selected file's patch, through the same read-only row renderer the
    /// Stack view uses. There are no threads and no composer here, so the two
    /// interactive row variants are never built and never rendered.
    /// The selected file's patch, through the same read-only pane the Stack
    /// view uses. There are no threads and no composer here, so the two
    /// interactive row variants are never built and never rendered.
    fn render_history_diff(&self, colors: Palette, cx: &mut Context<Root>) -> Div {
        let Some(history) = self.history.as_ref() else {
            return div().flex_1().min_w_0();
        };
        let selected = history
            .session
            .as_ref()
            .and_then(ReviewSession::selected_file);
        let changed_files = history
            .session
            .as_ref()
            .map(|session| session.comparison().files.len())
            .unwrap_or_default();
        let empty = if history.selected.is_none() {
            "Select a commit to read what it changed."
        } else if matches!(history.diff_state, LoadState::Loading(_)) {
            "Loading this commit's changes…"
        } else if changed_files == 0 {
            "This commit changed no files."
        } else {
            "No text patch is available. Binary and media content is never loaded."
        };
        render_read_only_diff_pane(
            &history.diff,
            selected_file_header(selected),
            empty,
            SharedString::from("history-diff-horizontal"),
            20_000,
            // The diff is the only flexible column of History's three, so it
            // declares what it needs and the commit and file lists yield.
            260.,
            &self.diff_focus,
            render_diff_ruler(&history.diff, colors, &cx.entity()),
            &cx.entity(),
            colors,
        )
    }

    /// The pull-request index: one repository's pull requests, open and closed,
    /// newest activity first. Clicking a row opens it as an ordinary review tab
    /// whatever its state — a merged pull request reads exactly like an open
    /// one, minus the write actions the provider refuses.
    fn render_pr_browser(&self, colors: Palette, cx: &mut Context<Root>) -> Div {
        let Some(browser) = self.browser.as_ref() else {
            return div().flex_1().min_w_0();
        };
        // Positions, not summaries: this list re-renders on every frame, and
        // the row renderer looks each one up rather than carrying a copy.
        let rows = Rc::new(browser.visible_indices());
        let count = rows.len();
        let root = cx.entity();
        div()
            .flex_1()
            .min_w_0()
            .h_full()
            .flex()
            .flex_col()
            .child(self.render_pr_browser_header(colors, cx))
            .child(layout::rule(colors))
            .child(
                div()
                    .flex_1()
                    .min_h_0()
                    .min_w_0()
                    .relative()
                    .when(count == 0, |list| {
                        list.child(
                            div()
                                .px(px(ui::PANEL_GUTTER))
                                .py(px(ui::GAP_PAGE))
                                .ui_text(TextRole::Caption)
                                .text_color(colors.muted)
                                .child(if matches!(browser.load, LoadState::Loading(_)) {
                                    "Loading…"
                                } else if browser.summaries.is_empty() {
                                    "No pull requests in this state."
                                } else {
                                    "Nothing loaded matches this filter."
                                }),
                        )
                    })
                    .when(count > 0, |list| {
                        list.child(
                            uniform_list(
                                "browse-rows",
                                count,
                                move |range: Range<usize>, _, cx| {
                                    let rows = rows.clone();
                                    let root = root.clone();
                                    root.read_with(cx, |workspace, _| {
                                        let this = &workspace.review;
                                        range
                                            .map(|row| {
                                                this.render_browse_row(
                                                    rows.get(row).copied(),
                                                    colors,
                                                    root.clone(),
                                                )
                                            })
                                            .collect::<Vec<_>>()
                                    })
                                },
                            )
                            .track_scroll(&self.browser_scroll)
                            .h_full()
                            .w_full(),
                        )
                        .child(
                            div().absolute().inset_0().child(
                                Scrollbar::vertical(&self.browser_scroll)
                                    .id("browse-scrollbar")
                                    .viewport_from_layout(),
                            ),
                        )
                    }),
            )
            .child(self.render_pr_browser_footer(colors, cx))
    }

    fn render_pr_browser_header(&self, colors: Palette, cx: &mut Context<Root>) -> Div {
        let Some(browser) = self.browser.as_ref() else {
            return div().flex_none();
        };
        let title = self
            .browser_repository()
            .as_ref()
            .map(Repository::full_name)
            .unwrap_or_else(|| "No repository".into());
        let loaded = browser.summaries.len();
        let shown = browser.visible_indices().len();
        let filtering = !browser.filter.trim().is_empty();
        let summary = if filtering {
            format!("{shown} of {loaded} loaded match this filter")
        } else if browser.has_more {
            format!("{loaded} loaded, more available")
        } else {
            format!("{loaded} loaded")
        };
        let notice = browser.load.notice();
        let error = matches!(browser.load, LoadState::Error(_));
        let state = browser.state;
        let current_key = browser.repository_key().to_owned();
        // Every repository in the window can be reached from here, the way
        // History's header does it, so the index is not tied to whichever pull
        // request happened to be open.
        let repositories: Vec<_> = self
            .repositories
            .iter()
            .map(|runtime| runtime.repository.clone())
            .collect();
        div()
            .flex_none()
            .px(px(ui::PANEL_GUTTER))
            .pt(px(ui::GAP_GROUP))
            .flex()
            .flex_col()
            .child(
                div()
                    .h(px(ui::DESKTOP_HIT))
                    .flex()
                    .items_center()
                    .gap(px(ui::GAP_GROUP))
                    .child(
                        div()
                            .ui_text(TextRole::Title)
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .child(title),
                    )
                    .child(div().flex_1())
                    .child(
                        layout::text_field(colors)
                            .w(px(260.))
                            .child(Input::new(&self.browser_filter_input)),
                    ),
            )
            .when(repositories.len() > 1, |header| {
                header.child(layout::chip_row().children(repositories.into_iter().map(
                    |repository| {
                        let selected = repository.cache_key() == current_key;
                        let index = self
                            .repositories
                            .iter()
                            .position(|runtime| runtime.repository == repository);
                        layout::chip(
                            SharedString::from(format!(
                                "browse-repository-{}",
                                repository.cache_key()
                            )),
                            &repository.full_name(),
                            None,
                            selected,
                            colors,
                        )
                        .on_click(cx.listener(move |root, _, _, cx| {
                            let this = &mut root.review;
                            if let Some(index) = index {
                                this.set_pr_browser_repository(index, cx);
                            }
                        }))
                    },
                )))
            })
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(ui::GAP_GROUP))
                    .child(layout::chip_row().children(
                        pr_browser::BrowseState::ALL.into_iter().map(|choice| {
                            layout::chip(
                                choice.element_id(),
                                choice.label(),
                                None,
                                choice == state,
                                colors,
                            )
                            .on_click(cx.listener(
                                move |root, _, _, cx| {
                                    let this = &mut root.review;
                                    this.set_pr_browser_state(choice, cx);
                                },
                            ))
                        }),
                    ))
                    .child(div().flex_1())
                    .child(
                        div()
                            .flex_none()
                            .ui_text(TextRole::Caption)
                            .text_color(colors.faint)
                            .debug_selector(|| "browse-count".to_owned())
                            .child(summary),
                    ),
            )
            .when_some(notice, |header, notice| {
                header.child(
                    div()
                        .pb(px(ui::GAP_GROUP))
                        .ui_text(TextRole::Caption)
                        .text_color(if error { colors.red } else { colors.muted })
                        .child(notice),
                )
            })
    }

    /// Paging is a press rather than a scroll trigger: a read that starts
    /// because the list happened to reach its end is a read nobody asked for.
    fn render_pr_browser_footer(&self, colors: Palette, cx: &mut Context<Root>) -> Div {
        let Some(browser) = self.browser.as_ref() else {
            return div().flex_none();
        };
        div()
            .flex_none()
            .h(px(ui::DESKTOP_HIT))
            .px(px(ui::PANEL_GUTTER))
            .flex()
            .items_center()
            .justify_center()
            .child(if browser.appending {
                div()
                    .ui_text(TextRole::Caption)
                    .text_color(colors.muted)
                    .child("Loading…")
                    .into_any_element()
            } else if browser.has_more {
                Button::new("browse-load-more")
                    .debug_selector(|| "browse-load-more".to_owned())
                    .control()
                    .bg(colors.elevated)
                    .border_1()
                    .border_color(rgba(0x00000000))
                    .focus_ring(colors.accent, colors.selected)
                    .cursor_pointer()
                    .accessibility_label("Load more pull requests")
                    .child("Load more")
                    .on_click(cx.listener(|root, _, _, cx| {
                        let this = &mut root.review;
                        this.load_pr_browser(true, cx);
                    }))
                    .into_any_element()
            } else {
                div()
                    .ui_text(TextRole::Caption)
                    .text_color(colors.faint)
                    .child(if browser.summaries.is_empty() {
                        ""
                    } else {
                        "End of list"
                    })
                    .into_any_element()
            })
    }

    /// One index row: what the pull request is on the first line, and where it
    /// came from on the second. Two lines rather than one because a closed pull
    /// request is identified by its branches and its age as much as its title.
    fn render_browse_row(
        &self,
        row: Option<usize>,
        colors: Palette,
        root: Entity<Root>,
    ) -> AnyElement {
        // A list can be asked to paint a row that a reply has since removed.
        // Reserving its height keeps the list from jumping while it settles.
        let Some(summary) = row.and_then(|row| self.browser.as_ref()?.summary(row)) else {
            return div().h(px(ui::TWO_LINE_ROW)).into_any_element();
        };
        let Some(repository_index) = self.browser_repository_index() else {
            return div().h(px(ui::TWO_LINE_ROW)).into_any_element();
        };
        let number = summary.number;
        let repository_key = self.repositories[repository_index].repository.cache_key();
        let open = self.tabs.iter().any(|tab| {
            tab.repository.cache_key() == repository_key && tab.pull_request.number == number
        });
        let labels = summary
            .labels
            .iter()
            .take(3)
            .map(|label| {
                div()
                    .badge()
                    .flex_none()
                    .w_auto()
                    .bg(colors.elevated)
                    .text_color(colors.muted)
                    .child(label.clone())
            })
            .collect::<Vec<_>>();
        let age = iso8601_unix_ms(&summary.updated_at)
            .map(|observed| format!("updated {}", collaboration_age_label(observed)))
            .unwrap_or_else(|| "updated at an unreported time".to_owned());
        div()
            .w_full()
            .h(px(ui::TWO_LINE_ROW))
            .px(px(ui::PANEL_GUTTER))
            .child(
                Button::new(format!("browse-pr-{number}"))
                    .debug_selector(move || format!("browse-pr-{number}"))
                    .w_full()
                    .min_w_0()
                    .h(px(ui::TWO_LINE_ROW))
                    .px(px(ui::CELL_INSET))
                    .py_0()
                    .rounded(px(ui::CONTROL_RADIUS))
                    .border_1()
                    .border_color(rgba(0x00000000))
                    .focus_ring(colors.accent, colors.selected)
                    .flex()
                    .flex_col()
                    .justify_center()
                    // The control centres its children; a column of two text
                    // lines has to start at the left edge like every other row.
                    .items_start()
                    .gap(px(1.))
                    .cursor_pointer()
                    .selected(open)
                    .when(open, |row| row.bg(colors.selected))
                    .hover(|row| row.bg(colors.selected))
                    .accessibility_label(format!(
                        "{} · #{number} · {} · by {} · {age}",
                        summary.title, summary.state, summary.author
                    ))
                    .child(
                        div()
                            .w_full()
                            .min_w_0()
                            .flex()
                            .items_center()
                            .gap(px(ui::GAP_ICON))
                            .child(state_pill(&summary.state, summary.draft, colors))
                            .child(
                                div()
                                    .flex_1()
                                    .min_w_0()
                                    .overflow_hidden()
                                    .text_ellipsis()
                                    .whitespace_nowrap()
                                    .ui_text(TextRole::Body)
                                    .text_color(colors.text)
                                    .child(summary.title.clone()),
                            )
                            .children(labels),
                    )
                    .child(
                        div()
                            .w_full()
                            .min_w_0()
                            .overflow_hidden()
                            .text_ellipsis()
                            .whitespace_nowrap()
                            .ui_text(TextRole::Caption)
                            .text_color(colors.faint)
                            .child(format!(
                                "#{number} · {} · {} → {} · {age}",
                                summary.author, summary.source_branch, summary.target_branch
                            )),
                    )
                    .on_click(move |_, window, cx| {
                        root.update(cx, |root, cx| {
                            let this = &mut root.review;
                            // Opening reads the full pull request by number, so
                            // a merged or closed one arrives exactly as an open
                            // one does.
                            this.open_pr_in_window(repository_index, number, window, cx);
                        });
                    }),
            )
            .into_any_element()
    }

    fn render_settings(&self, colors: Palette, cx: &mut Context<Root>) -> impl IntoElement {
        let selected = self.workspace.preferences.sidebar_material;
        let choices = SIDEBAR_MATERIAL_CHOICES
            .iter()
            .map(|(material, label, detail)| {
                let material = *material;
                let chosen = selected == material;
                Button::new(SharedString::from(format!("sidebar-material-{label}")))
                    .debug_selector(move || format!("sidebar-material-{label}"))
                    .w_full()
                    .px(px(ui::CELL_INSET))
                    .py(px(ui::GAP_GROUP))
                    .rounded(px(ui::CONTROL_RADIUS))
                    .border_1()
                    .border_color(rgba(0x00000000))
                    .focus_ring(colors.accent, colors.selected)
                    .cursor_pointer()
                    .flex()
                    .flex_col()
                    .items_start()
                    .gap(px(ui::GAP_ICON))
                    .selected(chosen)
                    .when(chosen, |row| row.bg(colors.selected))
                    .when(!chosen, |row| row.hover(|row| row.bg(colors.selected)))
                    .accessibility_label(format!(
                        "{label}{}",
                        if chosen { ", selected" } else { "" }
                    ))
                    .child(
                        div()
                            .ui_text(TextRole::Label)
                            .text_color(if chosen { colors.text } else { colors.muted })
                            .child(*label),
                    )
                    .child(
                        div()
                            .ui_text(TextRole::Caption)
                            .text_color(colors.faint)
                            .child(*detail),
                    )
                    .on_click(cx.listener(move |root, _, _, cx| {
                        let this = &mut root.review;
                        this.set_sidebar_material(material, cx);
                    }))
            });
        layout::page()
            .id("settings-page")
            .flex_1()
            .min_h_0()
            .min_w_0()
            .overflow_y_scroll()
            .child(
                div()
                    .w(px(SETTINGS_PAGE_WIDTH))
                    .max_w_full()
                    .flex()
                    .flex_col()
                    .gap(px(ui::GAP_PAGE))
                    .child(
                        layout::lines()
                            .child(div().ui_text(TextRole::Display).child("Settings"))
                            .child(
                                div()
                                    .ui_text(TextRole::Body)
                                    .text_color(colors.muted)
                                    .child("These choices are yours, not a repository's. They are saved with the workspace."),
                            ),
                    )
                    .child(
                        layout::section("Appearance", colors)
                            .child(
                                layout::field("Sidebar material", colors).child(
                                    div()
                                        .flex()
                                        .flex_col()
                                        .gap(px(ui::GAP_ICON))
                                        .children(choices),
                                ),
                            )
                            .child(
                                div()
                                    .ui_text(TextRole::Caption)
                                    .text_color(colors.faint)
                                    .child(SIDEBAR_MATERIAL_LIMIT),
                            ),
                    ),
            )
    }

    fn render_setup(&self, colors: Palette, cx: &mut Context<Root>) -> impl IntoElement {
        let accounts = self.accounts.iter().enumerate().map(|(index, account)| {
            side_control(&account.login, self.selected_account == index, colors)
                .id(SharedString::from(format!("account-{index}")))
                .on_click(cx.listener(move |root, _, _, cx| {
                    let this = &mut root.review;
                    if !matches!(this.repository_setup_state, LoadState::Loading(_)) {
                        this.selected_account = index;
                        cx.notify();
                    }
                }))
        });
        let account_status = self
            .accounts_state
            .notice()
            .unwrap_or_else(|| "Choose the gh identity used only for this repository".into());
        div()
            .flex_1()
            .min_w_0()
            .flex()
            .items_center()
            .justify_center()
            .p(px(ui::PANEL_GUTTER))
            .child(
                div()
                    .w(px(SETUP_CARD_WIDTH))
                    .max_w_full()
                    .flex()
                    .flex_col()
                    .gap(px(ui::GAP_PAGE))
                    .child(
                        layout::lines()
                            .child(div().ui_text(TextRole::Title).child("Add a repository"))
                            .child(
                                div()
                                    .ui_text(TextRole::Body)
                                    .text_color(colors.muted)
                                    .child(
                                        "Review without cloning. Existing local folders work too.",
                                    ),
                            ),
                    )
                    .child(
                        layout::field("Repository", colors)
                            .child(input_box(&self.repository_input, colors))
                            .child(
                                Button::new("browse-repository")
                                    .control()
                                    .debug_selector(|| "browse-repository".into())
                                    .px(px(ui::CONTROL_INSET))
                                    .py_0()
                                    .rounded(px(ui::CONTROL_RADIUS))
                                    .bg(colors.elevated)
                                    .disabled_presentation()
                                    .disabled(
                                        self.repository_picker_open
                                            || matches!(
                                                self.repository_setup_state,
                                                LoadState::Loading(_)
                                            ),
                                    )
                                    .accessibility_label("Choose a local repository folder")
                                    .child("Choose folder…")
                                    .on_click(cx.listener(|root, _, window, cx| {
                                        let this = &mut root.review;
                                        this.open_repository_picker(window, cx);
                                    })),
                            ),
                    )
                    .child(
                        layout::field("GitHub account", colors)
                            .child(
                                div()
                                    .flex()
                                    .flex_wrap()
                                    .gap(px(ui::GAP_GROUP))
                                    .children(accounts),
                            )
                            .child(
                                div()
                                    .ui_text(TextRole::Caption)
                                    .text_color(colors.faint)
                                    .child(account_status),
                            )
                            .child(
                                Button::new("refresh-repository-accounts")
                                    .control()
                                    .bg(colors.elevated)
                                    .disabled_presentation()
                                    .disabled(
                                        matches!(self.accounts_state, LoadState::Loading(_))
                                            || matches!(
                                                self.repository_setup_state,
                                                LoadState::Loading(_)
                                            ),
                                    )
                                    .accessibility_label("Refresh GitHub accounts")
                                    .child("Refresh accounts")
                                    .on_click(cx.listener(|root, _, _, cx| {
                                        let this = &mut root.review;
                                        this.accounts_state = LoadState::Loading(
                                            "Discovering GitHub accounts…".into(),
                                        );
                                        this.discover_accounts(None, cx);
                                        cx.notify();
                                    })),
                            ),
                    )
                    .child(
                        layout::field("Open PR number · optional", colors)
                            .child(div().w(px(160.)).child(input_box(&self.pr_input, colors))),
                    )
                    .when_some(self.repository_setup_state.notice(), |card, notice| {
                        card.child(
                            div()
                                .id("repository-setup-notice")
                                .debug_selector(|| "repository-setup-notice".into())
                                .ui_text(TextRole::Body)
                                .text_color(
                                    if matches!(self.repository_setup_state, LoadState::Error(_)) {
                                        colors.red
                                    } else {
                                        colors.muted
                                    },
                                )
                                .child(notice),
                        )
                    })
                    .child(
                        div()
                            .flex()
                            .justify_end()
                            .gap(px(ui::GAP_GROUP))
                            .child(
                                Button::new("cancel-setup")
                                    .control()
                                    .px(px(ui::PANEL_GUTTER))
                                    .py_0()
                                    .rounded(px(ui::CONTROL_RADIUS))
                                    .cursor_pointer()
                                    .child("Cancel")
                                    .on_click(cx.listener(|root, _, _, cx| {
                                        let this = &mut root.review;
                                        this.cancel_repository_setup(cx);
                                    })),
                            )
                            .child(
                                Button::new("confirm-add-repository")
                                    .control()
                                    .debug_selector(|| "confirm-add-repository".into())
                                    .disabled_presentation()
                                    .disabled(
                                        self.repository_picker_open
                                            || matches!(
                                                self.repository_setup_state,
                                                LoadState::Loading(_)
                                            ),
                                    )
                                    .accessibility_label("Add selected repository")
                                    .px(px(ui::PANEL_GUTTER))
                                    .py_0()
                                    .rounded(px(ui::CONTROL_RADIUS))
                                    .bg(colors.text)
                                    .text_color(colors.canvas)
                                    .cursor_pointer()
                                    .child(
                                        if matches!(
                                            self.repository_setup_state,
                                            LoadState::Loading(_)
                                        ) {
                                            "Adding…"
                                        } else {
                                            "Add repository"
                                        },
                                    )
                                    .on_click(cx.listener(|root, _, _, cx| {
                                        let this = &mut root.review;
                                        this.submit_repository_setup(cx);
                                    })),
                            ),
                    ),
            )
    }

