    fn saved_participant_avatar_loads_once_and_is_offered_to_the_next_render(
        cx: &mut gpui::TestAppContext,
    ) {
        /// A 1x1 RGBA PNG: the smallest thing GPUI would actually paint.
        const ONE_PIXEL_PNG: [u8; 70] = [
            0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00, 0x00, 0x00, 0x0d, 0x49, 0x48,
            0x44, 0x52, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x06, 0x00, 0x00,
            0x00, 0x1f, 0x15, 0xc4, 0x89, 0x00, 0x00, 0x00, 0x0d, 0x49, 0x44, 0x41, 0x54, 0x78,
            0x9c, 0x63, 0xf8, 0xcf, 0xc0, 0xf0, 0x1f, 0x00, 0x05, 0x00, 0x01, 0xff, 0x89, 0x99,
            0x3d, 0x1d, 0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82,
        ];
        const AVATAR_URL: &str = "https://avatars.githubusercontent.com/in/347564?s=64";

        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, _) = submitted_review_fixture();
        let pull = transition_pull_request(7);
        root.update(cx, |root, cx| {
            let this = &mut root.review;
            this.install_tab_with_restore(
                repository.clone(),
                pull,
                None,
                InstallTabOptions {
                    activate: true,
                    window: None,
                    start_background_work: false,
                },
                cx,
            );
            let mut details = details_with_reviews(Vec::new());
            details
                .participant_avatars
                .insert("coderabbitai".into(), AVATAR_URL.into());
            this.tabs[0].details = Some(details);
            this.tabs[0].details_state = LoadState::Ready;
            let path = this.avatars.borrow().path_for(AVATAR_URL);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, ONE_PIXEL_PNG).unwrap();
            // The pass that discovers the picture has nothing to show yet; it
            // only claims the work, and the puck keeps its letter.
            let details = this.tabs[0].details.clone();
            assert!(this.claim_avatars(details.as_ref(), cx).is_empty());
        });
        cx.run_until_parked();
        root.update(cx, |root, cx| {
            let this = &root.review;
            let details = this.tabs[0].details.clone();
            let ready = this.claim_avatars(details.as_ref(), cx);
            let image = ready
                .get("coderabbitai")
                .expect("the saved picture must be offered to the next render");
            assert_eq!(image.bytes, ONE_PIXEL_PNG.to_vec());
            assert!(
                !this.avatars.borrow_mut().claim("coderabbitai"),
                "a participant whose picture is in hand is never fetched again"
            );
        });
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn actions_root_apply_preserves_selected_refresh_and_fences_stale_ok_err(
        cx: &mut gpui::TestAppContext,
    ) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, _) = submitted_review_fixture();
        let pull = transition_pull_request(7);
        root.update(cx, |root, cx| {
            let this = &mut root.review;
            this.install_tab_with_restore(
                repository.clone(),
                pull,
                None,
                InstallTabOptions {
                    activate: true,
                    window: None,
                    start_background_work: false,
                },
                cx,
            );
            let details = actions_details_fixture(&repository);
            this.tabs[0].checks_selection.reconcile(&details.checks);
            this.tabs[0].details = Some(details);
            this.tabs[0].details_state = LoadState::Ready;
            let (_, locator, _, selected_check_id) = this.selected_actions_locator(0).unwrap();

            let initial = this.tabs[0].ci_read.begin_jobs(locator.clone());
            assert!(
                this.tabs[0]
                    .ci_read
                    .finish_jobs(&initial, Ok(actions_snapshot(&locator, 10, &[11, 12])),)
            );
            this.tabs[0].ci_read.select_job(Some(12));

            let refresh = this.tabs[0].ci_read.begin_jobs(locator.clone());
            let refresh_token = CiCompletionToken {
                workspace_instance: this.workspace_instance,
                tab_instance: this.tabs[0].instance_generation,
                repository_key: repository.cache_key(),
                pull_request: 7,
                details_generation: this.tabs[0].details_generation,
                selected_check_id: selected_check_id.clone(),
                locator: locator.clone(),
                selected_job_id: this.tabs[0].ci_read.selected_job_id,
                jobs_observation_id: None,
                operation: refresh,
            };
            assert_eq!(refresh_token.selected_job_id, Some(12));
            assert!(this.apply_actions_jobs_completion(
                &refresh_token,
                Ok(actions_snapshot(&locator, 11, &[11, 12])),
            ));
            assert_eq!(this.tabs[0].ci_read.selected_job_id, Some(12));
            assert!(matches!(
                &this.tabs[0].ci_read.jobs,
                MemoryRead::Fresh(snapshot) if snapshot.observation_id == 11
            ));

            let exact_jobs = this.tabs[0].ci_read.jobs.visible().unwrap().clone();
            let (log_operation, _, selected_job_id) = this.tabs[0].ci_read.begin_log().unwrap();
            let log_token = CiCompletionToken {
                jobs_observation_id: Some(exact_jobs.observation_id),
                operation: log_operation,
                ..refresh_token.clone()
            };
            assert_eq!(selected_job_id, 12);
            this.tabs[0].ci_read.select_job(Some(11));
            assert!(
                !this.apply_actions_log_completion(&log_token, Ok(actions_log(&exact_jobs, 12)),)
            );
            assert!(!matches!(&this.tabs[0].ci_read.log, MemoryRead::Fresh(_)));
            this.tabs[0].ci_read.select_job(Some(12));

            let stale_operation = this.tabs[0].ci_read.begin_jobs(locator.clone());
            let stale_token = CiCompletionToken {
                operation: stale_operation,
                ..refresh_token.clone()
            };
            let mut locator_b = locator.clone();
            locator_b.workflow_run.run_attempt = 3;
            let current = this.tabs[0].ci_read.begin_jobs(locator_b.clone());
            assert!(!this.apply_actions_jobs_completion(
                &stale_token,
                Ok(actions_snapshot(&locator, 12, &[11, 12])),
            ));
            assert!(!this.apply_actions_jobs_completion(
                &stale_token,
                Err(ActionsReadError::closed(
                    ActionsReadErrorCategory::Unavailable,
                )),
            ));
            assert!(this.tabs[0].ci_read.owns(&current));
            assert_eq!(
                this.tabs[0].ci_read.frozen_locator.as_ref(),
                Some(&locator_b)
            );
            assert!(matches!(
                &this.tabs[0].ci_read.jobs,
                MemoryRead::Loading { operation_id, .. }
                    if *operation_id == current.operation_id
            ));

            let stale_same_lifetime = this.tabs[0].ci_read.begin_jobs(locator.clone());
            let stale_same_lifetime_token = CiCompletionToken {
                operation: stale_same_lifetime,
                selected_job_id: this.tabs[0].ci_read.selected_job_id,
                ..refresh_token.clone()
            };
            this.tabs[0].details_generation = this.tabs[0].details_generation.saturating_add(1);
            assert!(!this.apply_actions_jobs_completion(
                &stale_same_lifetime_token,
                Err(ActionsReadError::closed(
                    ActionsReadErrorCategory::Cancelled,
                )),
            ));
            assert!(matches!(
                &this.tabs[0].ci_read.jobs,
                MemoryRead::Unavailable { .. }
            ));

            let replacement_operation = this.tabs[0].ci_read.begin_jobs(locator.clone());
            let replacement_token = CiCompletionToken {
                workspace_instance: this.workspace_instance,
                details_generation: this.tabs[0].details_generation,
                operation: replacement_operation.clone(),
                ..refresh_token
            };
            this.workspace_instance = this.workspace_instance.saturating_add(1);
            assert!(!this.apply_actions_jobs_completion(
                &replacement_token,
                Err(ActionsReadError::closed(
                    ActionsReadErrorCategory::Unavailable,
                )),
            ));
            assert!(this.tabs[0].ci_read.owns(&replacement_operation));
            assert!(matches!(
                &this.tabs[0].ci_read.jobs,
                MemoryRead::Loading { operation_id, .. }
                    if *operation_id == replacement_operation.operation_id
            ));
        });
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn actions_focus_tracks_preserved_pane_on_refusal_and_reopen(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, _) = submitted_review_fixture();
        let pull = transition_pull_request(7);
        let busy_token = cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.install_tab_with_restore(
                    repository.clone(),
                    pull,
                    None,
                    InstallTabOptions {
                        activate: true,
                        window: Some(window),
                        start_background_work: false,
                    },
                    cx,
                );
                let details = actions_details_fixture(&repository);
                this.tabs[0].checks_selection.reconcile(&details.checks);
                this.tabs[0].details = Some(details);
                this.tabs[0].details_state = LoadState::Ready;
                this.open_checks(window, cx);
                this.general_reads
                    .begin(&repository.account)
                    .unwrap()
                    .into_parts()
                    .0
            })
        });
        cx.update(|window, cx| window.draw(cx).clear(cx));

        cx.dispatch_action(OpenSelectedCheckJobs);
        cx.update(|window, cx| {
            root.read_with(cx, |root, _| {
                let this = &root.review;
                assert_eq!(this.tabs[0].ci_read.pane, CiPane::Checks);
                assert!(this.checks_focus.is_focused(window));
                assert!(!this.jobs_focus.is_focused(window));
            });
        });

        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                let disposition = this.general_reads.complete(
                    &busy_token,
                    &GeneralReadDirective::default(),
                    None,
                    false,
                );
                assert!(disposition.matching_operation_released);

                let (_, locator, _, _) = this.selected_actions_locator(0).unwrap();
                let operation = this.tabs[0].ci_read.begin_jobs(locator.clone());
                assert!(
                    this.tabs[0]
                        .ci_read
                        .finish_jobs(&operation, Ok(actions_snapshot(&locator, 20, &[11, 12])),)
                );
                this.tabs[0].inspector_section = InspectorSection::Overview;
                this.focus.focus(window, cx);
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });

        cx.dispatch_action(OpenChecks);
        cx.update(|window, cx| {
            root.read_with(cx, |root, _| {
                let this = &root.review;
                assert!(matches!(
                    this.tabs[0].inspector_section,
                    InspectorSection::Checks
                ));
                assert_eq!(this.tabs[0].ci_read.pane, CiPane::Jobs);
                assert!(this.jobs_focus.is_focused(window));
                assert!(!this.checks_focus.is_focused(window));
            });
        });

        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                let snapshot = this.tabs[0].ci_read.jobs.visible().unwrap().clone();
                let (operation, _, selected_job_id) = this.tabs[0].ci_read.begin_log().unwrap();
                assert!(
                    this.tabs[0]
                        .ci_read
                        .finish_log(&operation, Ok(actions_log(&snapshot, selected_job_id)),)
                );
                this.tabs[0].inspector_section = InspectorSection::Overview;
                this.focus.focus(window, cx);
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });
        let checks_section = cx.debug_bounds("pr-tab-checks").unwrap();
        cx.simulate_click(checks_section.center(), Modifiers::default());
        cx.update(|window, cx| {
            root.read_with(cx, |root, _| {
                let this = &root.review;
                assert!(matches!(
                    this.tabs[0].inspector_section,
                    InspectorSection::Checks
                ));
                assert_eq!(this.tabs[0].ci_read.pane, CiPane::Log);
                assert!(this.log_focus.is_focused(window));
                assert!(!this.checks_focus.is_focused(window));
            });
        });

        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                let now = Instant::now();
                let (token, _) = this
                    .general_reads
                    .begin_at(&repository.account, now)
                    .unwrap()
                    .into_parts();
                let disposition = this.general_reads.complete_at(
                    &token,
                    &GeneralReadDirective {
                        x_poll_interval: None,
                        rate_limit: Some(GeneralReadDelay::Suspend),
                    },
                    None,
                    false,
                    now,
                    UNIX_EPOCH,
                );
                assert!(disposition.matching_operation_released);
                this.tabs[0].ci_read.pane = CiPane::Jobs;
                this.focus_current_ci_pane(0, window, cx);
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });
        let load_log = cx.debug_bounds("actions-load-selected-log").unwrap();
        cx.simulate_click(load_log.center(), Modifiers::default());
        cx.update(|window, cx| {
            root.read_with(cx, |root, app| {
                let this = &root.review;
                assert_eq!(this.tabs[0].ci_read.pane, CiPane::Jobs);
                assert!(this.jobs_focus.contains_focused(window, app));
                assert!(!this.log_focus.contains_focused(window, app));
                assert_eq!(this.status, super::read_sync::RATE_SUSPENDED_NOTICE);
            });
        });
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn actions_native_jobs_and_large_log_render_at_the_final_row(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        let (mut repository, _) = submitted_review_fixture();
        repository.owner = "cli".into();
        repository.name = "cli".into();
        let pull = transition_pull_request(7);
        let jobs_dispatches = Arc::new(AtomicU64::new(0));
        let log_dispatches = Arc::new(AtomicU64::new(0));
        let maximum_rendered_log_rows = Arc::new(AtomicU64::new(0));
        let final_log_row_materializations = Arc::new(AtomicU64::new(0));
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.install_tab_with_restore(
                    repository.clone(),
                    pull,
                    None,
                    InstallTabOptions {
                        activate: true,
                        window: Some(window),
                        start_background_work: false,
                    },
                    cx,
                );
                let details = actions_details_fixture(&repository);
                this.tabs[0].checks_selection.reconcile(&details.checks);
                this.tabs[0].details = Some(details);
                this.tabs[0].details_state = LoadState::Ready;
                this.tabs[0].inspector_section = InspectorSection::Checks;
                this.inspector_open = true;
                let (_, locator, _, _) = this.selected_actions_locator(0).unwrap();
                let ids = (1..=80).collect::<Vec<_>>();
                let snapshot = actions_snapshot(&locator, 50, &ids);
                let mut log = actions_log(&snapshot, snapshot.selected_check_job_id);
                log.sanitized_text = (0..200_000)
                    .map(|index| {
                        if index == 199_999 {
                            format!(
                                "SYNTHETIC-FINAL-ROW-LEFT {} SYNTHETIC-HORIZONTAL-END-RIGHT",
                                "0123456789abcdef".repeat(512)
                            )
                        } else {
                            format!("synthetic-line-{index}")
                        }
                    })
                    .collect::<Vec<_>>()
                    .join("\n");
                log.raw_byte_count = log.sanitized_text.len();
                log.line_count = 200_000;
                this.actions_read_fixture = Some(Arc::new(ActionsReadFixture {
                    jobs: snapshot,
                    log,
                    jobs_dispatches: jobs_dispatches.clone(),
                    log_dispatches: log_dispatches.clone(),
                    maximum_rendered_log_rows: maximum_rendered_log_rows.clone(),
                    final_log_row_materializations: final_log_row_materializations.clone(),
                }));
                assert!(this.start_actions_jobs(0, cx));
                assert!(matches!(
                    this.tabs[0].ci_read.jobs,
                    MemoryRead::Loading { .. }
                ));
                this.focus_current_ci_pane(0, window, cx);
            });
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                assert!(matches!(this.tabs[0].ci_read.jobs, MemoryRead::Fresh(_)));
                assert_eq!(jobs_dispatches.load(Ordering::Relaxed), 1);
                assert!(
                    this.general_reads
                        .selected_account_readiness_at(&repository.account, Instant::now())
                        .is_ok()
                );
                this.status = "Synthetic Actions jobs sink · actual Root admission, controller completion, and strict apply fence · no credentials or provider calls".into();
                window.resize(size(px(1440.), px(900.)));
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });

        cx.update(|_, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                assert!(this.start_actions_log(0, cx));
                assert!(matches!(
                    this.tabs[0].ci_read.log,
                    MemoryRead::Loading { .. }
                ));
            });
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                assert!(matches!(this.tabs[0].ci_read.log, MemoryRead::Fresh(_)));
                assert_eq!(log_dispatches.load(Ordering::Relaxed), 1);
                assert!(
                    this.general_reads
                        .selected_account_readiness_at(&repository.account, Instant::now())
                        .is_ok()
                );
                this.tabs[0]
                    .log_scroll
                    .scroll_to_item(199_999, gpui::ScrollStrategy::Center);
                this.status = "Synthetic maximum-line Actions log sink · final row and horizontal sentinels · actual Root admission/controller completion · no credentials, provider, or storage calls".into();
                this.focus_current_ci_pane(0, window, cx);
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });
        assert!(
            cx.debug_bounds("actions-log-row-200000").is_some(),
            "the native list must materialize the final displayed row"
        );
        root.read_with(cx, |root, _| {
            let this = &root.review;
            let log = this.tabs[0].ci_read.log.visible().unwrap();
            assert_eq!(log.line_count, 200_000);
            assert!(
                log.sanitized_text
                    .ends_with("SYNTHETIC-HORIZONTAL-END-RIGHT")
            );
            assert_eq!(
                bounded_log_render_range(0..200_000, log.line_count).len(),
                super::MAX_RENDERED_LOG_ROWS,
            );
        });

        let horizontal_maximum = cx.update(|_, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                let maximum = this.tabs[0].log_horizontal.max_offset().x.as_f32();
                assert!(maximum > 1_000.);
                this.tabs[0]
                    .log_horizontal
                    .set_offset(point(px(-maximum), px(0.)));
                cx.notify();
                maximum
            })
        });
        assert!(horizontal_maximum > 1_000.);
        cx.update(|window, cx| window.draw(cx).clear(cx));
        assert!(cx.debug_bounds("actions-log-row-200000").is_some());
        assert!(final_log_row_materializations.load(Ordering::Relaxed) > 0);
        assert!(
            maximum_rendered_log_rows.load(Ordering::Relaxed)
                <= super::MAX_RENDERED_LOG_ROWS as u64
        );
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn ci_async_completion_preserves_created_review_checkpoint_and_local_stop(
        cx: &mut gpui::TestAppContext,
    ) {
        use super::review_interactions::PendingReviewStartJournal;
        use cibergit::domain::{ChangedFile, Comparison};

        fn preserved(this: &super::ReviewWorkspace, cx: &gpui::App) -> serde_json::Value {
            let tab = &this.tabs[0];
            let InteractionState::Ready(controller) = &tab.interactions else {
                panic!("missing controller")
            };
            serde_json::json!({
                "session": tab.session,
                "canonical": tab.canonical_session,
                "pin": tab.canonical_full_revision,
                "composition": controller.composition(),
                "durable": controller.durable_composition(),
                "submitted": format!("{:?}", tab.submitted_summary_editor.current_snapshot()),
                "dismissal": format!("{:?}", tab.dismissal_editor),
                "journal": format!("{:?}", tab.journal_operations),
                "shared": [this.composer_input.read(cx).value().to_string(),
                    this.submitted_summary_input.read(cx).value().to_string(),
                    this.review_summary_input.read(cx).value().to_string(),
                    this.dismissal_reason_input.read(cx).value().to_string()],
                "restore": format!("{:?}", this.active_tab_input_restore),
            })
        }

        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        let (repository, submitted_review) = submitted_review_fixture();
        let (checkpoint, before) = cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                let mut pull = transition_pull_request(7);
                pull.base_sha = "1".repeat(40);
                pull.head_sha = "2".repeat(40);
                this.install_tab_with_restore(
                    repository.clone(),
                    pull,
                    None,
                    InstallTabOptions {
                        activate: true,
                        window: Some(window),
                        start_background_work: false,
                    },
                    cx,
                );
                let session = super::ReviewSession::new(Comparison {
                    revision: super::Revision {
                        base_sha: "1".repeat(40),
                        head_sha: "2".repeat(40),
                    },
                    files: vec![ChangedFile {
                        path: "src/lib.rs".into(),
                        previous_path: None,
                        raw_path: None,
                        raw_previous_path: None,
                        status: "modified".into(),
                        additions: 1,
                        deletions: 1,
                        patch: Some("@@ -1 +1 @@\n-old\n+new\n".into()),
                        patch_complete: true,
                    }],
                    complete: true,
                    notice: None,
                });
                let mut controller = match super::ReviewInteractionController::load(
                    &this.interaction_root,
                    &repository,
                    7,
                    &session,
                )
                .unwrap()
                {
                    super::ControllerLoad::Ready(controller) => controller,
                    super::ControllerLoad::RecoveryRequired(reason) => panic!("{reason}"),
                };
                controller
                    .select_line_with_canonical(
                        &session,
                        &session,
                        super::LineSelection::single(super::DiffSide::New, 1),
                    )
                    .unwrap();
                let saved = controller
                    .stage_composer_text("retained LINE rationale".into())
                    .unwrap();
                controller.store_for_test().save(&saved).unwrap();
                let line_id = controller
                    .composer
                    .as_ref()
                    .unwrap()
                    .draft_id
                    .clone()
                    .unwrap();
                controller.finish_composer_save(
                    &saved,
                    &line_id,
                    "retained LINE rationale",
                    Ok(()),
                );
                controller
                    .select_file_with_canonical(&session, &session)
                    .unwrap();
                let saved = controller
                    .stage_composer_text("retained FILE rationale".into())
                    .unwrap();
                controller.store_for_test().save(&saved).unwrap();
                let file_id = controller
                    .file_composer
                    .as_ref()
                    .unwrap()
                    .draft_id
                    .clone()
                    .unwrap();
                controller.finish_composer_save(
                    &saved,
                    &file_id,
                    "retained FILE rationale",
                    Ok(()),
                );
                let absence = PendingFileReviewAbsence {
                    viewer_login: repository.account.login.clone(),
                    repository: repository.clone(),
                    pull_request: ProviderCoordinates {
                        provider: "github".into(),
                        host: repository.host.clone(),
                        owner: repository.owner.clone(),
                        repository: repository.name.clone(),
                        pull_request: 7,
                        remote_id: "PR_node".into(),
                    },
                    pull_request_url: "https://github.com/octo/repo/pull/7".into(),
                    pull_request_state: "OPEN".into(),
                    current_base_sha: "1".repeat(40),
                    current_head_sha: "2".repeat(40),
                };
                let intent = controller
                    .prepare_pending_file_review_start(
                        &absence,
                        "combined-flow".into(),
                        "combined-create".into(),
                        "combined-file".into(),
                    )
                    .unwrap();
                let mut record = super::PendingReviewStartRecord::new(intent.clone()).unwrap();
                record
                    .mark_create_in_flight("synthetic-created-attempt".into())
                    .unwrap();
                record
                    .mark_review_created(PendingReviewCreationAcknowledgement {
                        operation_id: intent.create_operation_id.clone(),
                        review: ProviderCoordinates {
                            remote_id: "SYNTHETIC_CREATED_REVIEW".into(),
                            ..intent.pull_request.clone()
                        },
                        review_author: repository.account.login.clone(),
                        review_commit_sha: "2".repeat(40),
                        pull_request: intent.pull_request.clone(),
                        repository_name_with_owner: repository.full_name(),
                    })
                    .unwrap();
                PendingReviewStartJournal::open(&this.interaction_root, intent.key.clone())
                    .unwrap()
                    .seed_created_fixture(&record)
                    .unwrap();
                assert!(
                    controller
                        .authority_for_test()
                        .execute_if_current(
                            controller.store_for_test(),
                            controller.durable_composition(),
                            || ()
                        )
                        .is_err()
                );
                controller.pending_review_start = Some(record.clone());
                assert!(!controller.composition().drafts.is_empty());
                assert!(!controller.composition().file_drafts.is_empty());
                this.tabs[0].interactions = InteractionState::Ready(controller);
                this.tabs[0].session = Some(session.clone());
                this.tabs[0].canonical_session = Some(session);
                this.tabs[0]
                    .submitted_summary_editor
                    .begin(submitted_review.clone());
                this.tabs[0]
                    .submitted_summary_editor
                    .store_active_body("retained submitted text".into());
                this.tabs[0]
                    .dismissal_editor
                    .begin(submitted_review.coordinates.clone());
                this.tabs[0]
                    .dismissal_editor
                    .store_active_reason("retained dismissal reason".into());
                this.tabs[0].journal_operations.push(JournalOperation {
                    request: JournalRequest::Auxiliary(Box::new(ReviewAuxiliaryRequest {
                        operation_id: "synthetic-unrelated-journal".into(),
                        attempt_id: "synthetic-unrelated-attempt".into(),
                        action: ReviewAuxiliaryAction::Reply {
                            thread: submitted_review.coordinates.clone(),
                            pending_review: None,
                            body: "retained unrelated journal text".into(),
                        },
                    })),
                    status: JournalStatus::Uncertain {
                        reason: "synthetic history, no transport".into(),
                    },
                });
                this.composer_input.update(cx, |input, cx| {
                    input.set_value("retained FILE rationale", window, cx)
                });
                this.submitted_summary_input.update(cx, |input, cx| {
                    input.set_value("retained submitted text", window, cx)
                });
                this.review_summary_input.update(cx, |input, cx| {
                    input.set_value("retained pending summary", window, cx)
                });
                this.replace_dismissal_reason_input(
                    "retained dismissal reason".into(),
                    false,
                    super::DismissalReasonInputOwner::for_tab(
                        this.workspace_instance,
                        &this.tabs[0],
                    ),
                    cx.entity().downgrade(),
                    window,
                    cx,
                );
                let details = actions_details_fixture(&repository);
                this.tabs[0].checks_selection.reconcile(&details.checks);
                this.tabs[0].details = Some(details);
                this.tabs[0].details_state = LoadState::Ready;
                let (_, locator, _, _) = this.selected_actions_locator(0).unwrap();
                let mut jobs = actions_snapshot(&locator, 42, &[1]);
                jobs.jobs[0].check_run_database_id = locator.check_database_id;
                jobs.jobs[0].check_run_url = format!(
                    "https://api.github.com/repos/{}/check-runs/{}",
                    repository.full_name(),
                    locator.check_database_id
                );
                let log = actions_log(&jobs, 1);
                this.actions_read_fixture = Some(Arc::new(ActionsReadFixture {
                    jobs,
                    log,
                    jobs_dispatches: Arc::new(AtomicU64::new(0)),
                    log_dispatches: Arc::new(AtomicU64::new(0)),
                    maximum_rendered_log_rows: Arc::new(AtomicU64::new(0)),
                    final_log_row_materializations: Arc::new(AtomicU64::new(0)),
                }));
                let before = preserved(this, cx);
                assert!(this.start_actions_jobs(0, cx));
                (record, before)
            })
        });
        cx.run_until_parked();
        cx.update(|_, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                assert_eq!(preserved(this, cx), before);
                assert!(matches!(this.tabs[0].ci_read.jobs, MemoryRead::Fresh(_)));
                assert!(
                    this.general_reads
                        .selected_account_readiness_at(&repository.account, Instant::now())
                        .is_ok()
                );
                let InteractionState::Ready(controller) = &this.tabs[0].interactions else {
                    unreachable!()
                };
                assert_eq!(controller.pending_review_start.as_ref(), Some(&checkpoint));
                assert_eq!(
                    PendingReviewStartJournal::open(
                        &this.interaction_root,
                        checkpoint.intent.key.clone()
                    )
                    .unwrap()
                    .record()
                    .unwrap()
                    .as_ref(),
                    Some(&checkpoint)
                );
                assert!(this.start_actions_log(0, cx));
                // The explicit local stop overlaps the admitted read. It sends no provider request.
                this.stop_pending_review_start(&checkpoint.intent.flow_id, cx);
            })
        });
        cx.run_until_parked();
        root.read_with(cx, |root, cx| {
            let this = &root.review;
            assert_eq!(preserved(this, cx), before);
            assert!(matches!(this.tabs[0].ci_read.log, MemoryRead::Fresh(_)));
            assert!(!this.tabs[0].write_in_flight);
            assert!(
                this.general_reads
                    .selected_account_readiness_at(&repository.account, Instant::now())
                    .is_ok()
            );
            let fixture = this.actions_read_fixture.as_ref().unwrap();
            assert_eq!(fixture.jobs_dispatches.load(Ordering::Relaxed), 1);
            assert_eq!(fixture.log_dispatches.load(Ordering::Relaxed), 1);
            let InteractionState::Ready(controller) = &this.tabs[0].interactions else {
                unreachable!()
            };
            let stopped = controller.pending_review_start.as_ref().unwrap();
            assert!(matches!(
                stopped.stage,
                super::PendingReviewStartStage::StoppedAfterReviewCreated { .. }
            ));
            assert_eq!(stopped.creation(), checkpoint.creation());
            assert_eq!(
                PendingReviewStartJournal::open(
                    &this.interaction_root,
                    checkpoint.intent.key.clone()
                )
                .unwrap()
                .record()
                .unwrap()
                .as_ref(),
                Some(stopped)
            );
            controller
                .authority_for_test()
                .execute_if_current(
                    controller.store_for_test(),
                    controller.durable_composition(),
                    || (),
                )
                .unwrap();
        });
    }

    #[test]
    fn submitted_edit_freezes_fresh_capability_and_old_cached_data_fails_closed() {
        let (repository, review) = submitted_review_fixture();
        let action = submitted_review_edit_action(&repository, 7, &review, String::new()).unwrap();
        let ReviewAuxiliaryAction::UpdateSubmittedSummary {
            review: target,
            selected_author,
            submitted_state,
            submitted_commit_sha,
            expected_body,
            body,
        } = action
        else {
            panic!("submitted edit must use its distinct action")
        };
        assert_eq!(target, review.coordinates);
        assert_eq!(selected_author, "alice");
        assert_eq!(submitted_state, "COMMENTED");
        assert_eq!(submitted_commit_sha, "1".repeat(40));
        assert_eq!(expected_body, "before");
        assert!(body.is_empty(), "upstream-compatible empty body is allowed");

        let cached_json = serde_json::to_value(&review).unwrap();
        assert!(
            cached_json.get("edit_summary_capability").is_none(),
            "viewer-relative edit capability must never persist into collaboration cache data"
        );
        let cached: PullRequestReview = serde_json::from_value(cached_json).unwrap();
        assert!(cached.edit_summary_capability.is_none());
        assert!(
            submitted_review_edit_action(&repository, 7, &cached, "after".into())
                .unwrap_err()
                .contains("complete fresh")
        );
    }

    #[test]
    fn submitted_editor_retains_per_review_text_and_rebases_only_the_fresh_source() {
        let (_, review_a) = submitted_review_fixture();
        let mut review_b = review_a.clone();
        review_b.coordinates.remote_id = "REVIEW_second".into();
        review_b.body = "second before".into();
        let mut editor = SubmittedSummaryEditor::default();

        assert_eq!(
            editor.begin(review_a.clone()),
            ("before".into(), false, false)
        );
        editor.store_active_body("typed A".into());
        assert_eq!(
            editor.begin(review_a.clone()),
            ("typed A".into(), false, true)
        );

        assert_eq!(
            editor.begin(review_b.clone()),
            ("second before".into(), false, false)
        );
        editor.store_active_body("typed B".into());
        assert_eq!(
            editor.begin(review_a.clone()),
            ("typed A".into(), false, true)
        );
        assert_eq!(editor.begin(review_b), ("typed B".into(), false, true));

        let mut changed_a = review_a;
        changed_a.body = "remote changed".into();
        assert_eq!(editor.begin(changed_a), ("typed A".into(), true, true));
        let active = editor.active_draft().expect("A draft remains active");
        assert_eq!(active.body, "typed A");
        assert_eq!(active.review.body, "remote changed");
        assert_eq!(editor.drafts().len(), 2);
    }

    #[test]
    fn submitted_editor_case_alias_resumes_without_duplicate_or_text_replacement() {
        let (_, mut saved_review) = submitted_review_fixture();
        saved_review.coordinates.host = "github.com".into();
        saved_review.coordinates.owner = "octo".into();
        saved_review.coordinates.repository = "repo".into();
        saved_review.edit_summary_capability = None;
        let saved = SubmittedSummaryDraft {
            review: saved_review,
            body: "typed under canonical storage identity".into(),
        };
        let disk = SubmittedDraftStoreSnapshot {
            generation: Some(4),
            active_review: None,
            drafts: vec![saved],
        };
        let mut editor = SubmittedSummaryEditor::default();
        assert!(matches!(
            editor.complete_load(0, Ok(disk)),
            super::SubmittedDraftLoadCompletion::Restored { .. }
        ));
        let (_, mut fresh) = submitted_review_fixture();
        fresh.coordinates.host = "GITHUB.COM".into();
        fresh.coordinates.owner = "Octo".into();
        fresh.coordinates.repository = "Repo".into();
        let (body, source_changed, resumed) = editor.begin(fresh.clone());
        assert_eq!(body, "typed under canonical storage identity");
        assert!(source_changed);
        assert!(resumed);
        assert_eq!(editor.drafts().len(), 1);
        assert_eq!(editor.drafts()[0].review, fresh);
        assert!(same_review_coordinates(
            &editor.drafts()[0].review.coordinates,
            editor.active_coordinates().unwrap()
        ));
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn existing_pr_and_post_close_transition_restore_target_submitted_input(
        cx: &mut gpui::TestAppContext,
    ) {
        use super::review_interactions::{ControllerLoad, ReviewInteractionController};
        use cibergit::{
            domain::{ChangedFile, Comparison, Revision},
            participation::{DiffSide, LineSelection},
            review::ReviewSession,
        };
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, review_a) = submitted_review_fixture();
        let mut review_b = review_a.clone();
        review_b.coordinates.pull_request = 8;
        review_b.coordinates.remote_id = "REVIEW_B".into();
        let mut review_c = review_a.clone();
        review_c.coordinates.pull_request = 9;
        review_c.coordinates.remote_id = "REVIEW_C".into();
        let pull_a = transition_pull_request(7);
        let pull_b = transition_pull_request(8);
        let pull_c = transition_pull_request(9);
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.repositories.push(RepoRuntime {
                    repository: repository.clone(),
                    pull_requests: Arc::new(vec![pull_a.clone(), pull_b.clone(), pull_c.clone()]),
                    state: LoadState::Ready,
                    generation: 0,
                    refresh: Default::default(),
                });
                for pull in [pull_a.clone(), pull_b.clone(), pull_c.clone()] {
                    this.install_tab_with_restore(
                        repository.clone(),
                        pull,
                        None,
                        InstallTabOptions {
                            activate: false,
                            window: None,
                            start_background_work: false,
                        },
                        cx,
                    );
                }
                for (index, (review, body)) in [
                    (review_a.clone(), "exact draft A"),
                    (review_b.clone(), "distinct draft B"),
                    (review_c.clone(), "third draft C"),
                ]
                .into_iter()
                .enumerate()
                {
                    let editor = &mut this.tabs[index].submitted_summary_editor;
                    editor.assume_loaded_for_test();
                    editor.begin(review);
                    editor.store_active_body(body.into());
                    editor.mark_current_durable(false);
                }

                let session = ReviewSession::new(Comparison {
                    revision: Revision {
                        base_sha: "1".repeat(40),
                        head_sha: "2".repeat(40),
                    },
                    files: vec![ChangedFile {
                        path: "src/lib.rs".into(),
                        previous_path: None,
                        raw_path: None,
                        raw_previous_path: None,
                        status: "modified".into(),
                        additions: 1,
                        deletions: 1,
                        patch: Some("@@ -1 +1 @@\n-old\n+new".into()),
                        patch_complete: true,
                    }],
                    complete: true,
                    notice: None,
                });
                for (index, body) in ["file A", "line B", "file C"].into_iter().enumerate() {
                    let mut controller = match ReviewInteractionController::load(
                        data.path(),
                        &repository,
                        7 + index as u64,
                        &session,
                    )
                    .unwrap()
                    {
                        ControllerLoad::Ready(controller) => controller,
                        ControllerLoad::RecoveryRequired(reason) => panic!("{reason}"),
                    };
                    if index == 1 {
                        controller
                            .select_line(&session, LineSelection::single(DiffSide::New, 1))
                            .unwrap();
                    } else {
                        controller
                            .select_file_with_canonical(&session, &session)
                            .unwrap();
                    }
                    let snapshot = controller.stage_composer_text(body.into()).unwrap();
                    controller.store_for_test().save(&snapshot).unwrap();
                    let id = controller
                        .composer
                        .as_ref()
                        .and_then(|c| c.draft_id.clone())
                        .or_else(|| {
                            controller
                                .file_composer
                                .as_ref()
                                .and_then(|c| c.draft_id.clone())
                        })
                        .unwrap();
                    controller.finish_composer_save(&snapshot, &id, body, Ok(()));
                    this.tabs[index].interactions = super::InteractionState::Ready(controller);
                }
                this.activate_tab_in_window(0, false, window, cx);
                assert_eq!(this.composer_input.read(cx).value(), "file A");

                // Start a real close handler while an owned submitted save is outstanding.
                this.submitted_summary_input.update(cx, |input, cx| {
                    input.set_value("pending draft A", window, cx)
                });
                let editor = &mut this.tabs[0].submitted_summary_editor;
                editor.store_active_body("pending draft A".into());
                editor.queue_current();
                let save = editor.start_next_save().unwrap();
                let token = SubmittedDraftCallbackToken {
                    workspace_instance: this.workspace_instance,
                    tab_instance: this.tabs[0].instance_generation,
                    repository_key: repository.cache_key(),
                    pull_request: 7,
                    generation: save.operation_generation(),
                };
                this.close_tab(&crate::CloseTab, window, cx);
                assert!(this.tabs[0].submitted_summary_editor.close_after_save());
                assert!(this.composer_input.read(cx).presentation().is_disabled());
                let before = match &this.tabs[0].interactions {
                    super::InteractionState::Ready(c) => c.composition().clone(),
                    _ => unreachable!(),
                };
                this.open_inline_composer(DiffSide::New, 1, false, window, cx);
                this.close_inline_composer(cx);
                this.prepare_file_comment_confirmation(cx);
                this.start_comment_write(false, cx);
                this.open_submit_confirmation(cx);
                this.confirm_submission(cx);
                this.prepare_merge_confirmation(cx);
                this.confirm_merge(cx);
                this.confirm_lifecycle_mutation(cx);
                this.reconcile_action_journal(cx);
                assert!(
                    !this.tabs[0].write_in_flight,
                    "no later operation can strand the close barrier"
                );
                // Even a queued Change carrying old widget text cannot cross the close barrier.
                this.composer_input
                    .update(cx, |input, cx| input.set_value("late text", window, cx));
                this.persist_composer(cx);
                let after = match &this.tabs[0].interactions {
                    super::InteractionState::Ready(c) => c.composition().clone(),
                    _ => unreachable!(),
                };
                assert_eq!(before, after);
                assert_eq!(
                    match &this.tabs[0].interactions {
                        super::InteractionState::Ready(c) => active_review_composer_body(c),
                        _ => None,
                    },
                    Some("file A")
                );
                assert!(this.tabs[0].confirmation.is_none());
                assert!(!this.tabs[0].write_in_flight);
                this.composer_input
                    .update(cx, |input, cx| input.set_value("file A", window, cx));
                assert!(this.apply_submitted_draft_save_completion(
                    &token,
                    Err("controlled local failure".into()),
                    cx
                ));
                assert!(!this.composer_input.read(cx).presentation().is_disabled());
                assert_eq!(this.tabs.len(), 3);
                this.tabs[0]
                    .submitted_summary_editor
                    .store_active_body("exact draft A".into());
                this.tabs[0]
                    .submitted_summary_editor
                    .mark_current_durable(false);
                this.submitted_summary_input
                    .update(cx, |input, cx| input.set_value("exact draft A", window, cx));

                assert_eq!(
                    this.submitted_summary_input.read(cx).value(),
                    "exact draft A"
                );

                // The already-open PR selection is a real synchronous handler path and must use
                // the supplied Window rather than trying to reacquire it through App::with_window.
                this.open_pr_in_window(0, 8, window, cx);
                assert_eq!(this.composer_input.read(cx).value(), "line B");
                assert_eq!(
                    this.submitted_summary_input.read(cx).value(),
                    "distinct draft B"
                );
                assert_eq!(
                    this.tabs[1]
                        .submitted_summary_editor
                        .active_draft()
                        .unwrap()
                        .review
                        .coordinates
                        .remote_id,
                    "REVIEW_B"
                );

                this.open_pr_in_window(0, 7, window, cx);
                this.close_tab(&crate::CloseTab, window, cx);
                assert_eq!(this.tabs[this.active_tab.unwrap()].pull_request.number, 8);
                assert_eq!(
                    this.submitted_summary_input.read(cx).value(),
                    "distinct draft B"
                );

                // Two context-only transitions before deferred effects drain must never stage
                // the still-visible B text into C or the replacement A tab.
                this.activate_tab_context(1, false, cx);
                assert!(this.composer_input.read(cx).presentation().is_disabled());
                this.persist_composer(cx);
                this.prepare_file_comment_confirmation(cx);
                assert!(this.tabs[1].confirmation.is_none());
                assert_eq!(
                    match &this.tabs[1].interactions {
                        super::InteractionState::Ready(c) => active_review_composer_body(c),
                        _ => None,
                    },
                    Some("file C")
                );
                this.activate_tab_context(0, false, cx);
                assert!(
                    this.submitted_summary_input
                        .read(cx)
                        .presentation()
                        .is_disabled()
                );
                assert_eq!(
                    this.tabs[1]
                        .submitted_summary_editor
                        .active_draft()
                        .unwrap()
                        .body,
                    "third draft C"
                );

                // Model the context-only save-barrier completion: C closes and B is selected;
                // restoration is admitted later by exact workspace/tab/repository/PR identity.
                this.activate_tab_in_window(1, false, window, cx);
                assert_eq!(
                    this.submitted_summary_input.read(cx).value(),
                    "third draft C"
                );
                assert_eq!(this.composer_input.read(cx).value(), "file C");
                this.finish_close_tab(1, cx);
            });
        });
        cx.update(|_, _| {});
        let (value, disabled, active_pull, active_review, stored_body) = cx.read(|cx| {
            let this = &root.read(cx).review;
            assert_eq!(this.composer_input.read(cx).value(), "line B");
            assert!(!this.composer_input.read(cx).presentation().is_disabled());
            let active = this.active_tab.unwrap();
            let editor = &this.tabs[active].submitted_summary_editor;
            (
                this.submitted_summary_input.read(cx).value().to_string(),
                this.submitted_summary_input
                    .read(cx)
                    .presentation()
                    .is_disabled(),
                this.tabs[active].pull_request.number,
                editor
                    .active_draft()
                    .unwrap()
                    .review
                    .coordinates
                    .remote_id
                    .clone(),
                editor.active_draft().unwrap().body.clone(),
            )
        });
        assert_eq!(value, "distinct draft B");
        assert!(!disabled);
        assert_eq!(active_pull, 8);
        assert_eq!(active_review, "REVIEW_B");
        assert_eq!(stored_body, "distinct draft B");
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn actions_run_controls_activate_by_real_pointer_and_keyboard_without_any_read(
        cx: &mut gpui::TestAppContext,
    ) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data.path().to_owned()),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        cx.update(|window, cx| {
            window.resize(size(px(1440.), px(900.)));
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.install_actions_control_fixture(window, cx);
            });
            window.draw(cx).clear(cx);
        });

        // Every control resolves for a fully identified run; the fresh
        // preparation read decides which one GitHub can accept.
        //
        // This is deliberately weak evidence and is not relied on: GPUI
        // inserts debug bounds before its visibility early-return, so an
        // element can resolve here every frame and still be absent from
        // layout and from the tab ring. The real evidence is the pointer
        // activation below, which goes through actual hit testing and asserts
        // the specific control that ran.
        for action in RUN_CONTROLS {
            assert!(
                cx.debug_bounds(action.control_element_id()).is_some(),
                "{} does not resolve",
                action.label()
            );
        }

        // Real hit-tested pointer activation, control by control. The status
        // names the exact action, so a press that landed on a neighbour cannot
        // satisfy these.
        for action in RUN_CONTROLS {
            cx.update(|_, cx| {
                root.update(cx, |root, _| {
                    let this = &mut root.review;
                    this.status = "sentinel".into();
                });
            });
            let bounds = cx.debug_bounds(action.control_element_id()).unwrap();
            cx.simulate_click(bounds.center(), Modifiers::default());
            cx.run_until_parked();
            root.read_with(cx, |root, _| {
                let this = &root.review;
                assert!(
                    this.status.contains(action.label()) && this.status.contains("zero writes"),
                    "the pointer press did not reach {}: {}",
                    action.label(),
                    this.status
                );
                assert!(this.tabs[0].confirmation.is_none());
                assert!(!this.tabs[0].write_in_flight);
            });
            cx.update(|window, cx| window.draw(cx).clear(cx));
        }

        // Each control tracks a caller-owned focus handle and accepts focus.
        // Real traversal and Enter/Space activation are asserted separately by
        // `actions_run_controls_are_tab_reachable_and_activate_on_enter_and_space`;
        // this test stays pointer-only so the two kinds of evidence do not
        // depend on each other.
        for (position, action) in RUN_CONTROLS.into_iter().enumerate() {
            cx.update(|window, cx| {
                root.update(cx, |root, cx| {
                    let this = &mut root.review;
                    this.actions_control_focus.controls[position].focus(window, cx);
                });
                window.draw(cx).clear(cx);
                root.update(cx, |root, _| {
                    let this = &mut root.review;
                    assert!(
                        this.actions_control_focus.controls[position].is_focused(window),
                        "{} does not accept focus",
                        action.label()
                    );
                });
            });
        }

        root.read_with(cx, |root, _| {
            let this = &root.review;
            assert!(this.tabs[0].confirmation.is_none());
            assert!(!this.tabs[0].write_in_flight);
        });
    }

    /// The Jobs pane has the same shape of Enter interception the Checks pane
    /// had, and it is reachable: a focused job row would never answer its own
    /// Enter, because the pane shortcut would load the already-selected job's
    /// log instead of selecting the focused row.
    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn a_focused_jobs_row_answers_enter_and_the_pane_shortcut_survives(
        cx: &mut gpui::TestAppContext,
    ) {
        use gpui::{KeyDownEvent, KeyUpEvent, Keystroke};

        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data.path().to_owned()),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        let (mut repository, _) = submitted_review_fixture();
        repository.owner = "cli".into();
        repository.name = "cli".into();
        cx.update(|window, cx| {
            window.resize(size(px(1440.), px(900.)));
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.install_tab_with_restore(
                    repository.clone(),
                    transition_pull_request(7),
                    None,
                    InstallTabOptions {
                        activate: true,
                        window: Some(window),
                        start_background_work: false,
                    },
                    cx,
                );
                let details = actions_details_fixture(&repository);
                this.tabs[0].checks_selection.reconcile(&details.checks);
                this.tabs[0].details = Some(details);
                this.tabs[0].details_state = LoadState::Ready;
                this.tabs[0].inspector_section = InspectorSection::Checks;
                this.inspector_open = true;
                this.panel_layout.sidebar_collapsed = true;
                this.panel_layout.file_tree_collapsed = true;
                let (_, locator, _, _) = this.selected_actions_locator(0).unwrap();
                let snapshot = actions_snapshot(&locator, 7, &[11, 12, 13]);
                // Present the jobs pane directly: this regression is about key
                // dispatch, not about the read path that fills it.
                this.tabs[0].ci_read.reconcile_locator(Some(&locator));
                this.tabs[0].ci_read.install_fresh_jobs_for_test(snapshot);
                this.tabs[0].ci_read.select_job(Some(13));
                this.focus_current_ci_pane(0, window, cx);
            });
            window.draw(cx).clear(cx);
        });

        let press = |cx: &mut gpui::VisualTestContext, key: &str| {
            let keystroke = Keystroke::parse(key).unwrap();
            cx.simulate_event(KeyDownEvent {
                keystroke: keystroke.clone(),
                is_held: false,
                prefer_character_input: false,
            });
            cx.simulate_event(KeyUpEvent { keystroke });
            cx.run_until_parked();
        };
        press(cx, "tab");
        cx.update(|window, cx| window.draw(cx).clear(cx));
        assert!(
            cx.debug_bounds("actions-job-11").is_some(),
            "the first job row must be painted for this regression to mean anything"
        );

        let row_handle = root.read_with(cx, |root, _| {
            let this = &root.review;
            this.jobs_first_row_focus.clone()
        });
        let mut reached = cx.update(|window, _| row_handle.is_focused(window));
        for _ in 0..200 {
            if reached {
                break;
            }
            cx.update(|window, cx| window.focus_next(cx));
            cx.update(|window, cx| window.draw(cx).clear(cx));
            reached = cx.update(|window, _| row_handle.is_focused(window));
        }
        assert!(reached, "Tab traversal must land on the first job row");

        // Job 13 is selected and job 11 is focused, so the two outcomes are
        // distinguishable: the row's own Enter selects 11, while the pane
        // shortcut would leave the selection alone and start a log read.
        press(cx, "enter");
        root.read_with(cx, |root, _| {
            let this = &root.review;
            assert_eq!(
                this.tabs[0].ci_read.selected_job_id,
                Some(11),
                "a focused job row must answer its own Enter instead of the pane shortcut"
            );
            assert_eq!(
                this.tabs[0].ci_read.pane,
                CiPane::Jobs,
                "the pane shortcut must not have loaded a log from a focused row"
            );
        });

        // Guarding the shortcut must not delete it: with focus back on the pane
        // itself, Enter still reaches the pane-level log action.
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.status = "sentinel".into();
                this.jobs_focus.focus(window, cx);
            });
            window.draw(cx).clear(cx);
        });
        press(cx, "enter");
        root.read_with(cx, |root, _| {
            let this = &root.review;
            assert_ne!(
                this.status, "sentinel",
                "the pane-level Enter shortcut must still act when the pane itself holds focus"
            );
        });
    }

    /// Real keyboard operation of every Actions run control.
    ///
    /// Written to the convention validated while the Checks pane Enter
    /// interception was diagnosed: focus only through Tab traversal onto the
    /// control's own caller-owned handle, never through a pointer press, which
    /// a click handler can move off the button; redraw between focusing and
    /// pressing, because GPUI registers a focused element's Enter and Space
    /// listeners only while painting it focused; and assert real controller
    /// state rather than a painted ring, which clipping or mouse modality can
    /// hide.
    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn actions_run_controls_are_tab_reachable_and_activate_on_enter_and_space(
        cx: &mut gpui::TestAppContext,
    ) {
        use gpui::{KeyDownEvent, KeyUpEvent, Keystroke};

        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data.path().to_owned()),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        cx.update(|window, cx| {
            window.resize(size(px(1440.), px(900.)));
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.install_actions_control_fixture(window, cx);
            });
            window.draw(cx).clear(cx);
        });

        let press = |cx: &mut gpui::VisualTestContext, key: &str| {
            let keystroke = Keystroke::parse(key).unwrap();
            cx.simulate_event(KeyDownEvent {
                keystroke: keystroke.clone(),
                is_held: false,
                prefer_character_input: false,
            });
            cx.simulate_event(KeyUpEvent { keystroke });
            cx.run_until_parked();
        };
        // Enter keyboard modality with a real keystroke before traversing.
        press(cx, "tab");
        cx.update(|window, cx| window.draw(cx).clear(cx));

        let viewport = cx.update(|window, _| window.viewport_size());
        let visible_area = gpui::Bounds {
            origin: gpui::point(px(0.), px(0.)),
            size: viewport,
        };
        for (position, action) in RUN_CONTROLS.into_iter().enumerate() {
            // Establish the control is genuinely on screen first, so an
            // offscreen fixture layout can never masquerade as a keyboard
            // defect. debug_bounds alone would not prove this.
            let bounds = cx
                .debug_bounds(action.control_element_id())
                .unwrap_or_else(|| panic!("{} must be painted", action.label()));
            assert!(
                bounds.intersects(&visible_area) && bounds.size.width > px(0.),
                "{} must have real painted area inside the viewport",
                action.label()
            );

            let focused_now = |cx: &mut gpui::VisualTestContext| {
                let handle = root.read_with(cx, |root, _| {
                    let this = &root.review;
                    this.actions_control_focus.controls[position].clone()
                });
                cx.update(|window, _| handle.is_focused(window))
            };
            let mut reached = focused_now(cx);
            for _ in 0..200 {
                if reached {
                    break;
                }
                cx.update(|window, cx| window.focus_next(cx));
                cx.update(|window, cx| window.draw(cx).clear(cx));
                reached = focused_now(cx);
            }
            assert!(
                reached,
                "Tab traversal must land on {}; it is painted every frame, so \
                 failing here means the control is absent from the tab ring",
                action.label()
            );

            for key in ["enter", "space"] {
                cx.update(|_, cx| {
                    root.update(cx, |root, _| {
                        let this = &mut root.review;
                        this.status = "sentinel".into();
                    });
                });
                cx.update(|window, cx| window.draw(cx).clear(cx));
                assert!(
                    focused_now(cx),
                    "{} lost focus before {key}",
                    action.label()
                );
                press(cx, key);
                root.read_with(cx, |root, _| {
                    let this = &root.review;
                    // The status names the exact control, so a key answered by
                    // some other element cannot satisfy this.
                    assert!(
                        this.status.contains(action.label()) && this.status.contains("zero writes"),
                        "{key} on a focused {} did not reach the controller: {}",
                        action.label(),
                        this.status
                    );
                });
                cx.update(|window, cx| window.draw(cx).clear(cx));
            }
        }

        // Both confirmation controls, and both keys on each. Cancel retires the
        // frozen request, so the confirmation is reinstalled and focus
        // reacquired by traversal before every activation rather than assuming
        // either survives the previous one.
        for (selector, confirm) in [
            ("confirm-actions-run-control", true),
            ("cancel-actions-run-control", false),
        ] {
            for key in ["enter", "space"] {
                cx.update(|window, cx| {
                    root.update(cx, |root, _| {
                        let this = &mut root.review;
                        this.install_synthetic_actions_confirmation(
                            ActionsRunControlAction::RerunFailedJobs,
                        );
                        this.status = "sentinel".into();
                    });
                    window.draw(cx).clear(cx);
                });
                assert!(
                    cx.debug_bounds(selector).is_some(),
                    "{selector} is not painted before {key}"
                );

                let handle = root.read_with(cx, |root, _| {
                    let this = &root.review;
                    if confirm {
                        this.actions_control_focus.confirm.clone()
                    } else {
                        this.actions_control_focus.cancel.clone()
                    }
                });
                let mut reached = cx.update(|window, _| handle.is_focused(window));
                for _ in 0..200 {
                    if reached {
                        break;
                    }
                    cx.update(|window, cx| window.focus_next(cx));
                    cx.update(|window, cx| window.draw(cx).clear(cx));
                    reached = cx.update(|window, _| handle.is_focused(window));
                }
                assert!(
                    reached,
                    "Tab traversal must land on {selector} before {key}"
                );
                cx.update(|window, cx| window.draw(cx).clear(cx));
                assert!(
                    cx.update(|window, _| handle.is_focused(window)),
                    "{selector} lost focus before {key}"
                );

                press(cx, key);
                root.read_with(cx, |root, _| {
                    let this = &root.review;
                    if confirm {
                        // Confirm reaches the dispatch path and stops at the
                        // synthetic scene's zero-capability guard.
                        assert!(
                            this.status.contains("not dispatched")
                                && this.status.contains("zero writes were sent"),
                            "{key} on a focused Confirm did not reach the controller: {}",
                            this.status
                        );
                        assert!(this.tabs[0].confirmation.is_some());
                    } else {
                        assert!(
                            this.status.contains("retired"),
                            "{key} on a focused Cancel did not retire the request: {}",
                            this.status
                        );
                        assert!(this.tabs[0].confirmation.is_none());
                    }
                    assert!(!this.tabs[0].write_in_flight);
                    assert!(this.tabs[0].ci_actions.in_flight.is_none());
                });
                cx.update(|window, cx| window.draw(cx).clear(cx));
            }
        }
        // Leave no prepared request behind.
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.invalidate_actions_control_confirmation(0, "test teardown");
                let _ = cx;
            });
            window.draw(cx).clear(cx);
        });
        root.read_with(cx, |root, _| {
            let this = &root.review;
            assert!(!this.tabs[0].write_in_flight);
            assert!(this.tabs[0].ci_actions.in_flight.is_none());
        });
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn a_prepared_actions_control_confirmation_discloses_its_exact_request_and_cancels(
        cx: &mut gpui::TestAppContext,
    ) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data.path().to_owned()),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        cx.update(|window, cx| {
            window.resize(size(px(1440.), px(900.)));
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                let locator = this.install_actions_control_fixture(window, cx);
                let request = ReviewWorkspace::synthetic_actions_control_request(
                    &locator,
                    ActionsRunControlAction::RerunFailedJobs,
                );
                let generation = this.tabs[0].ci_actions.invalidate();
                this.tabs[0].confirmation = Some(NativeConfirmation::ActionsRunControl {
                    generation,
                    request: Box::new(request),
                });
            });
            window.draw(cx).clear(cx);
        });
        let composer_before = root.read_with(cx, |root, cx| {
            let this = &root.review;
            this.composer_input.read(cx).value().to_string()
        });

        // Pointer activation of Confirm reaches the real handler and dispatches
        // nothing in a scene without provider capability.
        let confirm = cx.debug_bounds("confirm-actions-run-control").unwrap();
        cx.simulate_click(confirm.center(), Modifiers::default());
        cx.run_until_parked();
        root.read_with(cx, |root, _| {
            let this = &root.review;
            assert!(
                this.status.contains("zero writes were sent"),
                "{}",
                this.status
            );
            assert!(this.tabs[0].confirmation.is_some());
            assert!(!this.tabs[0].write_in_flight);
        });

        // Both confirmation controls accept caller-owned focus. Keyboard
        // activation is not asserted, for the reason documented in the
        // pointer/focus test above.
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.actions_control_focus.confirm.focus(window, cx);
            });
            window.draw(cx).clear(cx);
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                assert!(this.actions_control_focus.confirm.is_focused(window));
                this.actions_control_focus.cancel.focus(window, cx);
            });
            window.draw(cx).clear(cx);
            root.update(cx, |root, _| {
                let this = &mut root.review;
                assert!(this.actions_control_focus.cancel.is_focused(window));
            });
        });

        // Cancel by pointer discards the prepared control and sends nothing.
        let cancel = cx.debug_bounds("cancel-actions-run-control").unwrap();
        cx.simulate_click(cancel.center(), Modifiers::default());
        cx.run_until_parked();
        root.read_with(cx, |root, cx| {
            let this = &root.review;
            assert!(this.tabs[0].confirmation.is_none());
            assert!(this.status.contains("zero writes sent"), "{}", this.status);
            assert!(!this.tabs[0].write_in_flight);
            // Shared inputs and the private recovery controller are untouched
            // by every control interaction above.
            assert_eq!(
                this.composer_input.read(cx).value(),
                composer_before.as_str()
            );
            assert!(matches!(
                this.tabs[0].interactions,
                InteractionState::Ready(_)
            ));
            assert!(this.tabs[0].session.is_some() && this.tabs[0].canonical_session.is_some());
        });

        // A moved check selection discards a still-visible confirmation rather
        // than letting it confirm against a different exact run.
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                // A token captured before Cancel must never dispatch after it.
                let cancelled =
                    this.install_synthetic_actions_confirmation(ActionsRunControlAction::CancelRun);
                this.cancel_actions_control_confirmation(&cancelled, cx);
                assert!(this.tabs[0].confirmation.is_none());
                assert!(this.status.contains("retired"), "{}", this.status);
                this.confirm_actions_run_control(cancelled, cx);
                assert!(this.tabs[0].ci_actions.in_flight.is_none());
                assert!(!this.tabs[0].write_in_flight);
                assert!(this.tabs[0].confirmation.is_none());

                // A moved check selection discards a still-visible frozen
                // request, and that token cannot dispatch either.
                let moved = this
                    .install_synthetic_actions_confirmation(ActionsRunControlAction::RerunAllJobs);
                this.tabs[0].checks_selection.selected_id = None;
                this.reconcile_ci_selection(0);
                assert!(this.tabs[0].confirmation.is_none());
                assert!(this.status.contains("Zero writes sent"), "{}", this.status);
                this.confirm_actions_run_control(moved, cx);
                assert!(this.tabs[0].ci_actions.in_flight.is_none());
                assert!(!this.tabs[0].write_in_flight);
                assert!(this.tabs[0].confirmation.is_none());
            });
            window.draw(cx).clear(cx);
        });
        cx.run_until_parked();
        root.read_with(cx, |root, cx| {
            let this = &root.review;
            // Discarding a prepared control preserves every shared input, the
            // private recovery controller, and both comparison identities.
            assert_eq!(
                this.composer_input.read(cx).value(),
                composer_before.as_str()
            );
            assert!(matches!(
                this.tabs[0].interactions,
                InteractionState::Ready(_)
            ));
            assert!(this.tabs[0].session.is_some() && this.tabs[0].canonical_session.is_some());
            assert_eq!(
                this.tabs[0].canonical_full_revision.head_sha,
                "2".repeat(40)
            );
            assert!(this.tabs[0].details.is_some());
        });

        // A preparation whose display moved while it was in flight retires by
        // ownership: it releases its own busy state and refuses to install the
        // confirmation. This is the no-write path, distinct from the
        // post-dispatch uncertain case below.
        cx.update(|_, cx| {
            root.update(cx, |root, _| {
                let this = &mut root.review;
                this.tabs[0].checks_selection.selected_id =
                    Some("SYNTHETIC_ACTIONS_CHECK_NODE".into());
                let (token, request) =
                    this.install_synthetic_actions_preparation(ActionsRunControlAction::CancelRun);
                // The display moves while the preparation read is outstanding.
                this.tabs[0].checks_selection.selected_id = None;
                this.tabs[0].details_generation += 1;

                let index = this.apply_actions_control_preparation(&token, Ok(*request));
                assert_eq!(
                    index,
                    Some(0),
                    "a stale preparation lost its own retirement"
                );
                assert!(!this.tabs[0].write_in_flight, "busy state leaked");
                assert!(this.tabs[0].ci_actions.in_flight.is_none());
                assert!(
                    this.tabs[0].confirmation.is_none(),
                    "a stale preparation installed a confirmation"
                );
                assert!(
                    this.status.contains("zero writes were sent"),
                    "{}",
                    this.status
                );
            });
            let _ = cx;
        });

        // A dispatched control releases its own busy state and reports its
        // outcome even when the display moved while it was in flight.
        cx.update(|_, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.tabs[0].checks_selection.selected_id =
                    Some("SYNTHETIC_ACTIONS_CHECK_NODE".into());
                let token = this
                    .install_synthetic_actions_confirmation(ActionsRunControlAction::RerunAllJobs);
                this.tabs[0].ci_actions.in_flight = Some(token.ownership.clone());
                this.tabs[0].write_in_flight = true;

                // An in-flight control is not fenced by a selection change.
                this.tabs[0].checks_selection.selected_id = None;
                this.reconcile_ci_selection(0);
                assert!(this.tabs[0].confirmation.is_some());
                this.tabs[0].details_generation += 1;
                this.tabs[0].ci_actions.invalidate();

                let index = this.apply_actions_control_completion(
                    &token,
                    ProviderMutationOutcome::Uncertain {
                        context: cibergit::domain::MutationContext {
                            operation_id: token.ownership.operation_id.clone(),
                            attempt_id: token.ownership.attempt_id.clone(),
                            action: "rerun-actions-run-all-jobs".into(),
                            payload: serde_json::json!({}),
                        },
                        reason: "synthetic lost acknowledgement".into(),
                    },
                );
                assert_eq!(
                    index,
                    Some(0),
                    "a dispatched control lost its own completion"
                );
                assert!(!this.tabs[0].write_in_flight, "busy state leaked");
                assert!(this.tabs[0].ci_actions.in_flight.is_none());
                assert!(
                    this.status.contains("frozen against replay"),
                    "an uncertain outcome was dropped: {}",
                    this.status
                );
                let _ = cx;
            });
        });
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn dismissal_reason_change_cannot_cross_context_only_tab_restore(
        cx: &mut gpui::TestAppContext,
    ) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, review_a) = dismissal_review_fixture(7, "REVIEW_A");
        let (_, review_b) = dismissal_review_fixture(8, "REVIEW_B");
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                for (pull, review, reason) in [
                    (transition_pull_request(7), review_a.clone(), "reason A"),
                    (transition_pull_request(8), review_b.clone(), "reason B"),
                ] {
                    this.install_tab_with_restore(
                        repository.clone(),
                        pull,
                        None,
                        InstallTabOptions {
                            activate: false,
                            window: None,
                            start_background_work: false,
                        },
                        cx,
                    );
                    let index = this.tabs.len() - 1;
                    this.tabs[index].details = Some(details_with_reviews(vec![review.clone()]));
                    this.tabs[index]
                        .dismissal_editor
                        .begin(review.coordinates.clone());
                    this.tabs[index]
                        .dismissal_editor
                        .store_active_reason(reason.into());
                }
                this.activate_tab_in_window(0, false, window, cx);
                assert_eq!(this.dismissal_reason_input.read(cx).value(), "reason A");
                assert!(
                    this.dismissal_reason_input_owner
                        .as_ref()
                        .is_some_and(|owner| {
                            owner.review.as_ref() == Some(&review_a.coordinates)
                        })
                );

                this.dismissal_reason_input.update(cx, |input, cx| {
                    input.set_value("late queued A text", window, cx);
                    cx.emit(gpui_base::input::InputEvent::Change);
                });
                this.activate_tab_context(1, false, cx);
                assert!(this.active_tab_input_restore.is_some());
                assert!(this.dismissal_reason_input_owner.is_none());
                assert_eq!(this.tabs[1].dismissal_editor.active_reason(), "reason B");
            });
        });
        cx.update(|_, _| {});
        cx.read(|cx| {
            let this = &root.read(cx).review;
            assert_eq!(
                this.tabs[0].dismissal_editor.active_reason(),
                "late queued A text"
            );
            assert_eq!(this.tabs[1].dismissal_editor.active_reason(), "reason B");
            assert_eq!(this.dismissal_reason_input.read(cx).value(), "reason B");
            assert!(this.active_tab_input_restore.is_none());
            assert!(
                this.dismissal_reason_input_owner
                    .as_ref()
                    .is_some_and(|owner| { owner.review.as_ref() == Some(&review_b.coordinates) })
            );
        });
        cx.update(|window, cx| {
            let input = {
                let this = &root.read(cx).review;
                this.dismissal_reason_input.clone()
            };
            input.update(cx, |input, cx| {
                input.set_value("late queued A text", window, cx);
                cx.emit(gpui_base::input::InputEvent::Change);
            });
        });
        cx.update(|_, _| {});
        cx.read(|cx| {
            let this = &root.read(cx).review;
            assert_eq!(
                this.tabs[1].dismissal_editor.active_reason(),
                "late queued A text",
                "the current B entity must accept a legitimate first edit equal to old A text"
            );
        });
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn dismissal_deferred_restore_mounts_current_entity_in_native_confirmation(
        cx: &mut gpui::TestAppContext,
    ) {
        cx.update(gpui_base::init);
        let appearance =
            std::env::var("CIBERGIT_SMOKE_APPEARANCE").unwrap_or_else(|_| "light".into());
        cx.update(|cx| {
            cx.set_window_appearance(Some(if appearance == "dark" {
                WindowAppearance::Dark
            } else {
                WindowAppearance::Light
            }));
        });
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, review_a) = dismissal_review_fixture(7, "REVIEW_A");
        let (_, mut review_b) = dismissal_review_fixture(8, "REVIEW_B");
        review_b.author = None;
        review_b.body =
            "Synthetic older-commit review; dismissal authority is explicitly not real.".into();
        review_b.dismissal_capability.as_mut().unwrap().authority = DismissalAuthority::Unknown {
            reason: "Synthetic authority: GitHub decides authorization for the selected account."
                .into(),
        };
        let old_entity = cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                for (pull, review, reason) in [
                    (transition_pull_request(7), review_a.clone(), "old A reason"),
                    (
                        transition_pull_request(8),
                        review_b.clone(),
                        "Synthetic bounded reason: obsolete approval; zero transport.",
                    ),
                ] {
                    this.install_tab_with_restore(
                        repository.clone(),
                        pull,
                        None,
                        InstallTabOptions {
                            activate: false,
                            window: None,
                            start_background_work: false,
                        },
                        cx,
                    );
                    let index = this.tabs.len() - 1;
                    this.tabs[index].details = Some(details_with_reviews(vec![review.clone()]));
                    this.tabs[index]
                        .dismissal_editor
                        .begin(review.coordinates.clone());
                    this.tabs[index]
                        .dismissal_editor
                        .store_active_reason(reason.into());
                }
                this.activate_tab_in_window(0, false, window, cx);
                this.dismissal_reason_input.entity_id()
            })
        });
        let mounted_notification = Rc::new(Cell::new(0usize));
        let mounted_notification_witness = mounted_notification.clone();
        let review_b_coordinates = review_b.coordinates.clone();
        let _notification_subscription = cx.update(|_, cx| {
            cx.observe(&root, move |root, cx| {
                if root.read_with(cx, |root, _| {
                    matches!(&root.review, this
                    if this.active_tab == Some(1)
                        && this.active_tab_input_restore.is_none()
                        && this.dismissal_reason_input_owner.as_ref().is_some_and(
                            |owner| owner.review.as_ref() == Some(&review_b_coordinates)
                        ))
                }) {
                    mounted_notification_witness
                        .set(mounted_notification_witness.get().saturating_add(1));
                }
            })
        });
        cx.update(|_, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.activate_tab_context(1, false, cx);
                assert!(this.active_tab_input_restore.is_some());
            });
        });
        cx.update(|_, _| {});
        assert_eq!(
            mounted_notification.get(),
            1,
            "deferred entity replacement must notify the mounted Root exactly once"
        );
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                let index = this.active_tab.unwrap();
                assert_eq!(this.tabs[index].pull_request.number, 8);
                assert!(this.active_tab_input_restore.is_none());
                assert_ne!(this.dismissal_reason_input.entity_id(), old_entity);
                assert_eq!(
                    this.dismissal_reason_input.read(cx).value(),
                    "Synthetic bounded reason: obsolete approval; zero transport."
                );
                assert!(
                    this.dismissal_reason_input_owner
                        .as_ref()
                        .is_some_and(|owner| owner.review.as_ref() == Some(&review_b.coordinates))
                );
                this.tabs[index].dismissal_confirmation_generation = 41;
                let request = dismissal_request(
                    &repository,
                    &review_b,
                    "Synthetic bounded reason: obsolete approval; zero transport.",
                    "synthetic-native-dismissal",
                    "synthetic-native-dismissal-attempt",
                );
                this.tabs[index].confirmation =
                    Some(NativeConfirmation::DismissSubmittedReview {
                        generation: 41,
                        request: Box::new(request),
                    });
                this.tabs[index].inspector_section = InspectorSection::Activity;
                this.tabs[index].review_page = 0;
                this.inspector_open = true;
                this.inspector_scroll.set_offset(point(px(0.), px(0.)));
                this.status = "Synthetic dismissal authority; hard-zero mutation transport before credentials."
                    .into();
                window.resize(size(px(1180.), px(820.)));
                cx.notify();
            });
            window.draw(cx).clear(cx);
        });
        if let Some(capture_dir) =
            std::env::var_os("CIBERGIT_DISMISSAL_CAPTURE_DIR").map(PathBuf::from)
        {
            fs::create_dir_all(&capture_dir).unwrap();
            cx.update(|window, _| {
                window
                    .render_to_image()
                    .unwrap()
                    .save(capture_dir.join(format!(
                        "native-dismissal-mounted-confirmation-{appearance}.png"
                    )))
                    .unwrap();
            });
        }
    }

