    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn dismissal_preparation_actual_ok_err_and_aba_callbacks_are_fenced(
        cx: &mut gpui::TestAppContext,
    ) {
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    ..Default::default()
                },
            )
        });
        let (repository, review) = dismissal_review_fixture(7, "REVIEW_A");
        cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.install_tab_with_restore(
                    repository.clone(),
                    transition_pull_request(7),
                    None,
                    InstallTabOptions {
                        activate: false,
                        window: None,
                        start_background_work: false,
                    },
                    cx,
                );
                this.tabs[0].details = Some(details_with_reviews(vec![review.clone()]));
                this.tabs[0]
                    .dismissal_editor
                    .begin(review.coordinates.clone());
                this.tabs[0]
                    .dismissal_editor
                    .store_active_reason("exact reason".into());
                this.activate_tab_in_window(0, false, window, cx);
                this.tabs[0].dismissal_confirmation_generation = 30;
                this.tabs[0].write_in_flight = true;
                let token = DismissalPreparationToken {
                    workspace_instance: this.workspace_instance,
                    tab_instance: this.tabs[0].instance_generation,
                    repository_key: repository.cache_key(),
                    pull_request: 7,
                    review: review.coordinates.clone(),
                    reason: "exact reason".into(),
                    editor_generation: this.tabs[0].dismissal_editor.generation,
                    operation_id: "dismiss-prep".into(),
                    attempt_id: "attempt-prep".into(),
                    action_generation: 30,
                };
                assert_eq!(
                    this.apply_dismissal_preparation(&token, Err("controlled read error".into())),
                    Some(0)
                );
                assert!(!this.tabs[0].write_in_flight);
                assert!(this.tabs[0].confirmation.is_none());

                this.tabs[0].write_in_flight = true;
                let request = dismissal_request(
                    &repository,
                    &review,
                    "exact reason",
                    "dismiss-prep",
                    "attempt-prep",
                );
                assert_eq!(
                    this.apply_dismissal_preparation(&token, Ok(request.clone())),
                    Some(0)
                );
                assert!(matches!(
                    this.tabs[0].confirmation.as_ref(),
                    Some(NativeConfirmation::DismissSubmittedReview { generation: 30, .. })
                ));

                assert!(this.invalidate_dismissal_confirmation(0, "controlled edit"));
                this.tabs[0]
                    .dismissal_editor
                    .store_active_reason("ABA changed".into());
                this.tabs[0]
                    .dismissal_editor
                    .store_active_reason("exact reason".into());
                this.tabs[0].write_in_flight = true;
                assert_eq!(
                    this.apply_dismissal_preparation(&token, Ok(request)),
                    None,
                    "old preparation must not apply after reason ABA"
                );
                assert!(this.tabs[0].write_in_flight);
                assert!(this.tabs[0].confirmation.is_none());
                this.tabs[0].write_in_flight = false;

                this.tabs[0].dismissal_confirmation_generation = 40;
                let old_request = dismissal_request(
                    &repository,
                    &review,
                    "exact reason",
                    "dismiss-stale-completion",
                    "attempt-stale-completion",
                );
                this.tabs[0].confirmation = Some(NativeConfirmation::DismissSubmittedReview {
                    generation: 40,
                    request: Box::new(old_request.clone()),
                });
                let old_completion = DismissalConfirmationToken {
                    workspace_instance: this.workspace_instance,
                    tab_instance: this.tabs[0].instance_generation,
                    repository_key: repository.cache_key(),
                    pull_request: 7,
                    generation: 40,
                    request: old_request.clone(),
                };
                this.tabs[0].dismissal_confirmation_generation = 41;
                this.tabs[0].confirmation = Some(NativeConfirmation::DismissSubmittedReview {
                    generation: 41,
                    request: Box::new(old_request.clone()),
                });
                this.tabs[0].write_in_flight = true;
                let sentinel = "newer identical dismissal lifetime";
                this.status = sentinel.into();
                for stale_outcome in [
                    ProviderMutationOutcome::Acknowledged(
                        SubmittedReviewDismissalAcknowledgement {
                            operation_id: old_request.operation_id.clone(),
                            target: old_request.target.clone(),
                            viewer: old_request.viewer.clone(),
                            final_state: "DISMISSED".into(),
                        },
                    ),
                    ProviderMutationOutcome::Uncertain {
                        context: cibergit::domain::MutationContext {
                            operation_id: old_request.operation_id.clone(),
                            attempt_id: old_request.attempt_id.clone(),
                            action: "dismiss-submitted-review".into(),
                            payload: serde_json::json!({"request": old_request}),
                        },
                        reason: "synthetic stale error".into(),
                    },
                ] {
                    assert_eq!(
                        this.apply_dismissal_completion(&old_completion, stale_outcome),
                        None,
                        "stale completion must not apply to a newer byte-identical confirmation"
                    );
                    assert!(this.tabs[0].write_in_flight);
                    assert_eq!(this.status, sentinel);
                    assert!(matches!(
                        this.tabs[0].confirmation.as_ref(),
                        Some(NativeConfirmation::DismissSubmittedReview { generation: 41, .. })
                    ));
                }
                this.tabs[0].write_in_flight = false;
            });
        });
    }

    #[test]
    fn late_preexisting_same_review_load_preserves_both_until_explicit_choice() {
        let (_, fresh) = submitted_review_fixture();
        let mut editor = SubmittedSummaryEditor::default();
        editor.begin(fresh.clone());
        editor.store_active_body("typed before load callback".into());
        let mut historical = fresh.clone();
        historical.edit_summary_capability = None;
        historical.body = "historical source".into();
        let disk = SubmittedDraftStoreSnapshot {
            generation: Some(8),
            active_review: Some(historical.coordinates.clone()),
            drafts: vec![SubmittedSummaryDraft {
                review: historical,
                body: "preexisting two-window durable text".into(),
            }],
        };

        assert_eq!(
            editor.complete_load(0, Ok(disk)),
            super::SubmittedDraftLoadCompletion::Conflict
        );
        assert_eq!(
            editor.active_draft().unwrap().body,
            "typed before load callback"
        );
        assert_eq!(
            editor.conflict().unwrap().drafts[0].body,
            "preexisting two-window durable text"
        );
        assert!(editor.pending_snapshot().is_none());
        assert_eq!(editor.durable_snapshot().generation, None);

        assert!(editor.resolve_conflict_keep_current());
        assert_eq!(editor.durable_snapshot().generation, Some(8));
        assert_eq!(
            editor.active_draft().unwrap().body,
            "typed before load callback"
        );
        assert_eq!(
            editor.pending_snapshot().unwrap().drafts[0].body,
            "typed before load callback"
        );
    }

    #[test]
    fn conflict_choices_preserve_local_only_b_and_disk_only_c() {
        let (_, review_a) = submitted_review_fixture();
        let mut review_b = review_a.clone();
        review_b.coordinates.remote_id = "REVIEW_B".into();
        let mut review_c = review_a.clone();
        review_c.coordinates.remote_id = "REVIEW_C".into();
        let local_a = SubmittedSummaryDraft {
            review: review_a.clone(),
            body: "local A".into(),
        };
        let local_b = SubmittedSummaryDraft {
            review: review_b,
            body: "local-only B".into(),
        };
        let mut historical_a = review_a;
        historical_a.edit_summary_capability = None;
        let saved_a = SubmittedSummaryDraft {
            review: historical_a,
            body: "saved A".into(),
        };
        review_c.edit_summary_capability = None;
        let saved_c = SubmittedSummaryDraft {
            review: review_c,
            body: "disk-only C".into(),
        };
        let disk = SubmittedDraftStoreSnapshot {
            generation: Some(9),
            active_review: None,
            drafts: vec![saved_a.clone(), saved_c.clone()],
        };
        let mut editor = SubmittedSummaryEditor::default();
        editor.begin(local_a.review.clone());
        editor.store_active_body(local_a.body.clone());
        editor.begin(local_b.review.clone());
        editor.store_active_body(local_b.body.clone());
        editor.begin(local_a.review.clone());
        assert_eq!(
            editor.complete_load(0, Ok(disk)),
            super::SubmittedDraftLoadCompletion::Conflict
        );

        let mut use_saved = editor.clone();
        assert!(use_saved.resolve_conflict_use_saved());
        assert_eq!(
            use_saved
                .draft_for(&saved_a.review.coordinates)
                .unwrap()
                .body,
            "saved A"
        );
        assert_eq!(
            use_saved
                .draft_for(&local_b.review.coordinates)
                .unwrap()
                .body,
            "local-only B"
        );
        assert_eq!(
            use_saved
                .draft_for(&saved_c.review.coordinates)
                .unwrap()
                .body,
            "disk-only C"
        );
        assert!(use_saved.active_coordinates().is_none());
        assert_eq!(use_saved.pending_snapshot().unwrap().drafts.len(), 3);

        assert!(editor.resolve_conflict_keep_current());
        assert_eq!(
            editor.draft_for(&local_a.review.coordinates).unwrap().body,
            "local A"
        );
        assert_eq!(
            editor.draft_for(&local_b.review.coordinates).unwrap().body,
            "local-only B"
        );
        assert_eq!(
            editor.draft_for(&saved_c.review.coordinates).unwrap().body,
            "disk-only C"
        );
        assert!(editor.active_coordinates().is_some());
        assert_eq!(editor.pending_snapshot().unwrap().drafts.len(), 3);
    }

    #[test]
    fn rejected_save_state_keeps_exact_current_text_and_close_barrier_dirty() {
        let (_, review) = submitted_review_fixture();
        let mut editor = SubmittedSummaryEditor::default();
        editor.assume_loaded_for_test();
        editor.begin(review);
        editor.store_active_body("must remain after rejected save".into());
        editor.queue_current();
        let started = editor.start_next_save().unwrap();
        assert_eq!(
            editor.request_close(),
            SubmittedDraftCloseDisposition::WaitForOperation
        );
        assert_eq!(
            started.snapshot().drafts[0].body,
            "must remain after rejected save"
        );
        let failure = editor
            .complete_save(
                started.operation_generation(),
                Err("injected rejection".into()),
            )
            .unwrap()
            .unwrap_err();
        assert!(failure.ends_with("injected rejection"));
        assert_eq!(
            editor.active_draft().unwrap().body,
            "must remain after rejected save"
        );
        assert!(!editor.is_current_durable());
        assert_eq!(editor.request_close(), SubmittedDraftCloseDisposition::Save);
    }

    #[test]
    fn delayed_save_actual_apply_path_rejects_tab_and_workspace_replacements() {
        let (repository, review) = submitted_review_fixture();
        let mut editor = SubmittedSummaryEditor::default();
        editor.assume_loaded_for_test();
        editor.begin(review);
        editor.store_active_body("delayed exact snapshot".into());
        editor.queue_current();
        let started = editor.start_next_save().unwrap();
        let token = SubmittedDraftCallbackToken {
            workspace_instance: 40,
            tab_instance: 50,
            repository_key: repository.cache_key(),
            pull_request: 7,
            generation: started.operation_generation(),
        };
        let mut receipt = started.snapshot().clone();
        receipt.generation = Some(1);

        assert!(
            apply_submitted_draft_save_if_current(
                &token,
                41,
                50,
                &repository.cache_key(),
                7,
                &mut editor,
                Ok(receipt.clone()),
            )
            .is_none()
        );
        assert!(editor.has_active_operation());
        assert!(
            apply_submitted_draft_save_if_current(
                &token,
                40,
                51,
                &repository.cache_key(),
                7,
                &mut editor,
                Ok(receipt.clone()),
            )
            .is_none()
        );
        assert_eq!(
            editor.active_draft().unwrap().body,
            "delayed exact snapshot"
        );

        assert_eq!(
            apply_submitted_draft_save_if_current(
                &token,
                40,
                50,
                &repository.cache_key(),
                7,
                &mut editor,
                Ok(receipt),
            ),
            Some(Ok(()))
        );
        assert!(!editor.has_active_operation());
        assert!(editor.is_current_durable());
    }

    #[test]
    fn acknowledged_clear_queue_does_not_invalidate_owned_save_completion() {
        let (repository, review) = submitted_review_fixture();
        let mut editor = SubmittedSummaryEditor::default();
        editor.assume_loaded_for_test();
        editor.begin(review);
        editor.store_active_body("owned save before clear".into());
        let captured = editor.active_draft().unwrap().clone();
        editor.queue_current();
        let started = editor.start_next_save().unwrap();
        editor.queue_clear(captured);
        let token = SubmittedDraftCallbackToken {
            workspace_instance: 40,
            tab_instance: 50,
            repository_key: repository.cache_key(),
            pull_request: 7,
            generation: started.operation_generation(),
        };
        let mut receipt = started.snapshot().clone();
        receipt.generation = Some(4);

        assert_eq!(
            apply_submitted_draft_save_if_current(
                &token,
                40,
                50,
                &repository.cache_key(),
                7,
                &mut editor,
                Ok(receipt),
            ),
            Some(Ok(()))
        );
        assert!(!editor.has_active_operation());
        assert!(editor.has_clear_work());
        assert_eq!(
            editor.request_close(),
            SubmittedDraftCloseDisposition::WaitForOperation
        );
    }

    #[test]
    fn acknowledged_clear_actual_apply_path_preserves_newer_typed_body() {
        let (_, review) = submitted_review_fixture();
        let mut editor = SubmittedSummaryEditor::default();
        editor.assume_loaded_for_test();
        editor.begin(review);
        editor.store_active_body("exact sent body".into());
        let captured = editor.active_draft().unwrap().clone();
        let durable = SubmittedDraftStoreSnapshot {
            generation: Some(12),
            ..editor.current_snapshot()
        };
        let edit_generation = editor.edit_generation();
        editor.complete_load(edit_generation, Ok(durable));
        editor.queue_clear(captured);
        let clear = editor.start_clear(false).unwrap().unwrap();
        editor.store_active_body("newer typed body".into());
        let tombstone = SubmittedDraftStoreSnapshot {
            generation: Some(13),
            active_review: None,
            drafts: Vec::new(),
        };

        assert_eq!(
            editor.complete_clear(clear.operation_generation(), Ok(tombstone)),
            Some(Ok(false))
        );
        assert_eq!(editor.active_draft().unwrap().body, "newer typed body");
        assert_eq!(editor.durable_snapshot().generation, Some(13));
        assert_eq!(
            editor.pending_snapshot().unwrap().drafts[0].body,
            "newer typed body"
        );
    }

    #[test]
    fn clear_a_after_b_activity_excludes_unchanged_a_but_retains_changed_a() {
        let (_, review_a) = submitted_review_fixture();
        let mut review_b = review_a.clone();
        review_b.coordinates.remote_id = "REVIEW_B".into();
        review_b.body = "source B".into();
        let draft_a = SubmittedSummaryDraft {
            review: review_a,
            body: "sent A".into(),
        };
        let draft_b = SubmittedSummaryDraft {
            review: review_b,
            body: "newer B".into(),
        };
        let cleared = SubmittedDraftStoreSnapshot {
            generation: Some(13),
            active_review: Some(draft_b.review.coordinates.clone()),
            drafts: vec![draft_b.clone()],
        };
        let mut editor = SubmittedSummaryEditor::default();
        editor.complete_load(
            0,
            Ok(SubmittedDraftStoreSnapshot {
                generation: Some(12),
                active_review: None,
                drafts: Vec::new(),
            }),
        );
        editor.begin(draft_a.review.clone());
        editor.store_active_body(draft_a.body.clone());
        editor.begin(draft_b.review.clone());
        editor.store_active_body(draft_b.body.clone());
        editor.mark_current_durable(false);
        editor.queue_clear(draft_a.clone());
        let clear = editor.start_clear(false).unwrap().unwrap();
        assert_eq!(
            editor.complete_clear(clear.operation_generation(), Ok(cleared.clone())),
            Some(Ok(true))
        );
        assert!(editor.draft_for(&draft_a.review.coordinates).is_none());
        assert_eq!(editor.active_draft().unwrap().body, "newer B");
        assert!(editor.pending_snapshot().is_none());

        let mut changed = SubmittedSummaryEditor::default();
        changed.complete_load(
            0,
            Ok(SubmittedDraftStoreSnapshot {
                generation: Some(12),
                active_review: None,
                drafts: Vec::new(),
            }),
        );
        let mut changed_a = draft_a.clone();
        changed_a.body = "new unsent A after acknowledgement".into();
        changed.begin(draft_a.review.clone());
        changed.store_active_body(draft_a.body.clone());
        changed.mark_current_durable(false);
        changed.begin(draft_b.review.clone());
        changed.store_active_body(draft_b.body.clone());
        changed.begin(draft_a.review.clone());
        changed.queue_clear(draft_a.clone());
        let clear = changed.start_clear(false).unwrap().unwrap();
        changed.store_active_body(changed_a.body.clone());
        assert_eq!(
            changed.complete_clear(clear.operation_generation(), Ok(cleared)),
            Some(Ok(false))
        );
        assert_eq!(
            changed.draft_for(&draft_a.review.coordinates).unwrap().body,
            "new unsent A after acknowledgement"
        );
        assert!(changed.pending_snapshot().is_some());
    }

    #[test]
    fn submitted_confirmation_token_rejects_tab_workspace_account_and_payload_changes() {
        let (repository, review) = submitted_review_fixture();
        let action = submitted_review_edit_action(&repository, 7, &review, "after".into()).unwrap();
        let confirmation = NativeConfirmation::UpdateSubmittedSummary {
            generation: 30,
            action: Box::new(action.clone()),
        };
        let token = SubmittedConfirmationToken {
            workspace_instance: 10,
            tab_instance: 20,
            repository_key: repository.cache_key(),
            pull_request: 7,
            confirmation_generation: 30,
            action: action.clone(),
        };
        assert!(token.matches_values(10, 20, &repository.cache_key(), 7, Some(&confirmation)));
        assert!(!token.matches_values(11, 20, &repository.cache_key(), 7, Some(&confirmation)));
        assert!(!token.matches_values(10, 21, &repository.cache_key(), 7, Some(&confirmation)));
        assert!(!token.matches_values(10, 20, "other-account", 7, Some(&confirmation)));
        assert!(!token.matches_values(10, 20, &repository.cache_key(), 8, Some(&confirmation)));
        let repeated_payload = NativeConfirmation::UpdateSubmittedSummary {
            generation: 31,
            action: Box::new(action.clone()),
        };
        assert!(!token.matches_values(10, 20, &repository.cache_key(), 7, Some(&repeated_payload)));
        let changed = NativeConfirmation::UpdateSubmittedSummary {
            generation: 30,
            action: Box::new(
                submitted_review_edit_action(&repository, 7, &review, "changed".into()).unwrap(),
            ),
        };
        assert!(!token.matches_values(10, 20, &repository.cache_key(), 7, Some(&changed)));
        assert!(!token.matches_values(10, 20, &repository.cache_key(), 7, None));
    }

    #[test]
    fn file_confirmation_token_rejects_full_fence_changes_and_identical_aba() {
        let (repository, source, target, confirmation, token) = pending_file_confirmation_fixture();
        let matches = |token: &FileCommentConfirmationToken,
                       workspace,
                       tab,
                       repository_key: &str,
                       pull_request,
                       confirmation: Option<&NativeConfirmation>| {
            token.matches_values(workspace, tab, repository_key, pull_request, confirmation)
        };
        assert!(matches(
            &token,
            10,
            20,
            &repository.cache_key(),
            7,
            Some(&confirmation)
        ));
        assert!(!matches(
            &token,
            11,
            20,
            &repository.cache_key(),
            7,
            Some(&confirmation)
        ));
        assert!(!matches(
            &token,
            10,
            21,
            &repository.cache_key(),
            7,
            Some(&confirmation)
        ));
        assert!(!matches(
            &token,
            10,
            20,
            "other-account",
            7,
            Some(&confirmation)
        ));
        assert!(!matches(
            &token,
            10,
            20,
            &repository.cache_key(),
            8,
            Some(&confirmation)
        ));
        let repeated_payload = NativeConfirmation::PendingFileComment {
            generation: 31,
            draft_id: "file-draft-1".into(),
            body: "Whole-file rationale".into(),
            target: target.clone(),
            source: Box::new(source.clone()),
        };
        assert!(!matches(
            &token,
            10,
            20,
            &repository.cache_key(),
            7,
            Some(&repeated_payload)
        ));
        let mut changed_source = source;
        changed_source.current_head_sha = "3".repeat(40);
        let changed_witness = NativeConfirmation::PendingFileComment {
            generation: 30,
            draft_id: "file-draft-1".into(),
            body: "Whole-file rationale".into(),
            target,
            source: Box::new(changed_source),
        };
        assert!(!matches(
            &token,
            10,
            20,
            &repository.cache_key(),
            7,
            Some(&changed_witness)
        ));
        assert!(!matches(&token, 10, 20, &repository.cache_key(), 7, None));
        assert!(file_confirmation_matches_visible_body(
            &token,
            "Whole-file rationale"
        ));
        assert!(!file_confirmation_matches_visible_body(
            &token,
            "Visible edit after confirmation"
        ));
        assert!(review_subject_allows_actions(ReviewSubject::Line));
        assert!(review_subject_allows_actions(ReviewSubject::File));
        assert!(!review_subject_allows_actions(ReviewSubject::Unknown));
    }

    #[test]
    fn pending_review_start_confirmation_fences_body_target_account_and_aba() {
        let (repository, target, confirmation, token) = pending_review_start_confirmation_fixture();
        let matches = |candidate: &PendingReviewStartConfirmationToken,
                       workspace,
                       tab,
                       repository_key: &str,
                       pull_request,
                       confirmation: Option<&NativeConfirmation>| {
            candidate.matches_confirmation_values(
                workspace,
                tab,
                repository_key,
                pull_request,
                confirmation,
            )
        };
        assert!(matches(
            &token,
            10,
            20,
            &repository.cache_key(),
            7,
            Some(&confirmation)
        ));
        assert!(!matches(
            &token,
            11,
            20,
            &repository.cache_key(),
            7,
            Some(&confirmation)
        ));
        assert!(!matches(
            &token,
            10,
            21,
            &repository.cache_key(),
            7,
            Some(&confirmation)
        ));
        assert!(!matches(
            &token,
            10,
            20,
            "other-account",
            7,
            Some(&confirmation)
        ));
        assert!(!matches(
            &token,
            10,
            20,
            &repository.cache_key(),
            8,
            Some(&confirmation)
        ));
        let repeated_payload = NativeConfirmation::PendingFileReviewStart {
            generation: 31,
            intent: Box::new(token.intent.clone()),
            mode: Box::new(token.mode.clone()),
        };
        assert!(!matches(
            &token,
            10,
            20,
            &repository.cache_key(),
            7,
            Some(&repeated_payload)
        ));
        let mut changed_intent = token.intent.clone();
        changed_intent.body = "edited visible body".into();
        let changed_body = NativeConfirmation::PendingFileReviewStart {
            generation: 30,
            intent: Box::new(changed_intent),
            mode: Box::new(token.mode.clone()),
        };
        assert!(!matches(
            &token,
            10,
            20,
            &repository.cache_key(),
            7,
            Some(&changed_body)
        ));
        let mut changed_target_intent = token.intent.clone();
        let mut changed_target = target;
        changed_target.path = "assets/other.bin".into();
        changed_target.file_key = "assets/other.bin".into();
        changed_target_intent.target = ReviewCommentTarget::File(changed_target);
        let changed_target = NativeConfirmation::PendingFileReviewStart {
            generation: 30,
            intent: Box::new(changed_target_intent),
            mode: Box::new(token.mode.clone()),
        };
        assert!(!matches(
            &token,
            10,
            20,
            &repository.cache_key(),
            7,
            Some(&changed_target)
        ));
        assert!(pending_review_start_confirmation_matches_visible_body(
            &token,
            "Whole-file rationale"
        ));
        assert!(!pending_review_start_confirmation_matches_visible_body(
            &token,
            "edited visible body"
        ));
    }

    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn pending_start_early_finish_notifies_active_and_inactive_exact_tabs(
        cx: &mut gpui::TestAppContext,
    ) {
        use super::review_interactions::{ControllerLoad, ReviewInteractionController};
        use cibergit::{
            domain::{ChangedFile, Comparison, Revision},
            review::ReviewSession,
        };
        use std::{cell::Cell, rc::Rc};

        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        let notifications = Rc::new(Cell::new(0usize));
        let observed = notifications.clone();
        let _subscription =
            cx.update(|_, cx| cx.observe(&root, move |_, _| observed.set(observed.get() + 1)));
        let (repository, _, _, fixture_token) = pending_review_start_confirmation_fixture();
        let session = ReviewSession::new(Comparison {
            revision: Revision {
                base_sha: "1".repeat(40),
                head_sha: "2".repeat(40),
            },
            files: vec![ChangedFile {
                path: "assets/example.bin".into(),
                previous_path: Some("assets/old.bin".into()),
                raw_path: None,
                raw_previous_path: None,
                status: "renamed".into(),
                additions: 0,
                deletions: 0,
                patch: None,
                patch_complete: false,
            }],
            complete: true,
            notice: None,
        });
        let active_token = cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                let mut pull = transition_pull_request(7);
                pull.base_sha = "1".repeat(40);
                pull.head_sha = "2".repeat(40);
                this.install_tab_with_restore(
                    repository.clone(),
                    pull,
                    None,
                    InstallTabOptions {
                        activate: true,
                        window: Some(window),
                        start_background_work: false,
                    },
                    cx,
                );
                let controller = match ReviewInteractionController::load(
                    &this.interaction_root,
                    &repository,
                    7,
                    &session,
                )
                .unwrap()
                {
                    ControllerLoad::Ready(controller) => controller,
                    ControllerLoad::RecoveryRequired(reason) => panic!("{reason}"),
                };
                this.tabs[0].interactions = InteractionState::Ready(controller);
                let mut token = fixture_token.clone();
                token.workspace_instance = this.workspace_instance;
                token.tab_instance = this.tabs[0].instance_generation;
                token.repository_key = repository.cache_key();
                this.tabs[0].pending_review_start_live = Some(token.clone());
                this.tabs[0].write_in_flight = true;
                token
            })
        });
        notifications.set(0);
        cx.update(|_, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.start_pending_review_thread(active_token.clone(), cx);
                assert!(!this.tabs[0].write_in_flight);
                assert!(this.tabs[0].pending_review_start_live.is_none());
                assert!(this.status.contains("disappeared"));
            });
        });
        cx.update(|_, _| {});
        assert!(
            notifications.get() > 0,
            "active early finish must invalidate Root"
        );

        let inactive_token = cx.update(|window, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                let mut pull = transition_pull_request(8);
                pull.base_sha = "1".repeat(40);
                pull.head_sha = "2".repeat(40);
                this.install_tab_with_restore(
                    repository.clone(),
                    pull,
                    None,
                    InstallTabOptions {
                        activate: true,
                        window: Some(window),
                        start_background_work: false,
                    },
                    cx,
                );
                let mut token = fixture_token.clone();
                token.workspace_instance = this.workspace_instance;
                token.tab_instance = this.tabs[0].instance_generation;
                token.repository_key = repository.cache_key();
                this.tabs[0].pending_review_start_live = Some(token.clone());
                this.tabs[0].write_in_flight = true;
                assert_eq!(this.active_tab, Some(1));
                token
            })
        });
        notifications.set(0);
        cx.update(|_, cx| {
            root.update(cx, |root, cx| {
                let this = &mut root.review;
                this.start_pending_review_thread(inactive_token.clone(), cx);
                assert!(!this.tabs[0].write_in_flight);
                assert!(this.tabs[0].pending_review_start_live.is_none());
                assert_eq!(this.active_tab, Some(1));
            });
        });
        cx.update(|_, _| {});
        assert!(
            notifications.get() > 0,
            "inactive early finish must invalidate Root"
        );
    }

