    #[cfg(feature = "ui-smoke")]
    #[gpui::test]
    fn explicit_utility_navigation_cancels_delayed_workspace_restore(
        cx: &mut gpui::TestAppContext,
    ) {
        use super::{TabState, WorkspaceState, workspace_save};
        cx.update(gpui_base::init);
        let data = tempdir().unwrap();
        let data_root = data.path().to_owned();
        let (root, cx) = cx.add_window_view(|window, cx| {
            Root::review(
                window,
                cx,
                Startup {
                    data_dir: Some(data_root),
                    provider_reads_disabled: true,
                    ..Default::default()
                },
            )
        });
        let (repository, _) = submitted_review_fixture();
        root.update(cx, |root, cx| {
            let this = &mut root.review;
            let mut workspace = WorkspaceState {
                repositories: vec![repository.clone()],
                ..Default::default()
            };
            let pull = transition_pull_request(7);
            workspace.tabs.push(TabState {
                repository_key: repository.cache_key(),
                number: 7,
                revision: pull.revision(),
                pull_request: Some(pull),
                selected_file: None,
                scroll_offset: 0.0,
                diff_mode: "auto".into(),
            });
            for page in 0..3 {
                this.persistence =
                    workspace_save::WorkspacePersistence::new(this.store.clone(), &workspace);
                let delayed = this
                    .persistence
                    .begin_restore(&workspace)
                    .unwrap()
                    .execute();
                let before = this.user_intent_generation;
                match page {
                    0 => this.open_history(Some(repository.clone()), cx),
                    1 => this.open_pr_browser(Some(repository.clone()), cx),
                    _ => this.open_settings(cx),
                }
                assert_eq!(this.user_intent_generation, before + 1);
                assert!(!this.persistence.restore_pending());
                assert!(
                    this.persistence
                        .complete_restore(delayed, &workspace.repositories, &[])
                        .is_none()
                );
            }
            assert!(this.settings_active);
        });
    }

    #[test]
    fn explicit_lookup_and_disk_restore_converge_without_duplicate_or_late_reopen() {
        let identity = ("exact-account/repository".to_owned(), 42);
        let token = super::OpenPrToken {
            workspace_instance: 7,
            user_intent_generation: 3,
            identity: identity.clone(),
            intent: super::OpenPrIntent::ExplicitStartup,
        };

        assert_eq!(
            super::admit_open_pr_completion(&token, 7, 3, std::slice::from_ref(&identity)),
            super::OpenPrCompletion::Existing(0),
            "disk-first completion selects and refreshes the restored tab"
        );
        assert_eq!(
            super::admit_open_pr_completion(&token, 7, 3, &[]),
            super::OpenPrCompletion::Install,
            "network-first completion installs once before disk restore sees the identity"
        );
        assert_eq!(
            super::admit_open_pr_completion(&token, 7, 4, &[]),
            super::OpenPrCompletion::Refused,
            "newer navigation or close prevents a delayed explicit reopen"
        );
        assert_eq!(
            super::admit_open_pr_completion(&token, 8, 3, &[]),
            super::OpenPrCompletion::Refused,
            "a replaced workspace rejects the old lookup"
        );
    }

